/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20160119-6","meetingId":"h28-cm01","date":"2016年1月19日","dateIso":"2016-01-19","committee":"区民委員会","time":"午後 １時００分～午後 ３時１５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"マイナンバー「個人番号カード」の交付等","agenda":"マイナンバー「個人番号カード」の交付等","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"私も全然わからなかったので、どういう対応をされているかというのを教えていただきたいのが１つと、あと、コンビニ交付の利用促進で安く、料金を下げて、時間も６時半から１１時というところで、非常に利便性を考えてやられるわけですけれども、これは本人確認はどういうふうにするのか、そのあたりの説明がなかったと思うので、ちょっと心配なので、教えていただきたいと思います。","respondent":"井浦戸籍住民課長","answer":"１点目のさまざまな事情で通知カードがお手元に届かない方への対応です。確定申告の関係で会社にマイナンバーを申告する必要があるというお客様がいらっしゃいます。品川区につきましても、個人番号記載の住民票の発行が可能ですので、そのように案内しています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"確認","question":"そうなると、お仕事等々でいろいろお忙しい方にとっては、それはそれで一つの利便性かなとも思うのですけれども、果たして絶対に大丈夫だというふうになるのかというのはいささか心配なところなのですが、そういう安全、それから個人情報の漏れ等々について、どういうふうに考えているか、その辺を一つ伺いたいのと、それから、最初のほうの住民票の発行等々での確定申告、扶養対応なのですけれども。","respondent":"井浦戸籍住民課長","answer":"１点目のコンビニ交付の暗証番号の設定ですが、こちらは、少数の自治体ですが、住基カードによって住民票のコンビニ交付を行うということは既に三、四年実施されておりまして、セキュリティにつきましては、技術的、物理的、制度的な措置が講じられておりまして。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"１２桁の個人番号ということで、これはいずれ一般新聞等々の報道等でも、基本４情報以外のさまざまな情報がひもづけという形で入ってくると言われているし、当初からそこのところは想定されているということでもあるわけで、非常に不安な状況があると思うので、やはり個人情報の流出も現実的にいっぱいいろいろなところで起きていることなので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"コンビニ交付についてなのですけれども、品川区では住基カードのときのコンビニ交付はやっていなかった……。そうすると、今回、新たに始めるということで、そこに対してどのくらいの税金がとか、そういう話を聞いても大丈夫ですか。情報保護について、本当にどうなのかというところを教えてください。","respondent":"井浦戸籍住民課長","answer":"こちらについてはさまざまな事情で行っておりまして、品川区につきましては、マイナンバー制度を直前に控えてございましたので、初期経費等々の効果的な実施ということで、住基カードの活用ではなく、マイナンバーを待つという方針をとっていたものです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"今、住基カードで行っているほかの自治体では、今まで情報が漏れてしまったとか、そういったことはなかったのでしょうか。","respondent":"井浦戸籍住民課長","answer":"これまではございません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"たけうち委員","kind":"確認","question":"表の通知カードの再送付なのですけれども、前に伺ったかもしれないですが、もう１回、再送付する場合の考え方というのですか、要は何が聞きたいかというと、区で保管しているところにとりにこられる方が１日２００人とかいらっしゃるというのですけれども、どうしても取りにこられない方なんかはどうすればいいのかということ、送っていただけるのかとか、その辺を聞かせてください。","respondent":"井浦戸籍住民課長","answer":"会社に早く出す必要がある方については、住民票に個人番号の情報が記載されたものをとっていただいて提出していただくというご案内をしています。それから、３点目……。","voiceIndex":18,"id":"exchange-006"},{"speaker":"松永委員","kind":"確認","question":"私からは確認で質問します。通知カードに関しては、全部の世帯、区民の方に行き渡っているとは思うのですけれども、品川区ではその確認をどのように行っているのか、お伺いいたします。","respondent":"井浦戸籍住民課長","answer":"したがいまして、2)の区保管で２万４,０００件余りの方についてはお手元に届いてございませんので、日々、窓口で私ども、平均２００件前後ですが、交付を行ってあります。再送付の方は自動的に送付されるという３区分です。","voiceIndex":24,"id":"exchange-007"},{"speaker":"松永委員","kind":"質問","question":"聞いた話なのですが、実際どうかはわかりませんけれども、自宅にまず届いていないということと、郵便局の紙も届いていないという方がいるとお伺いしたものですから、では、その方は区に行けばあるという確証を持っていいのかなと思うのですが、その辺はいかがでしょうか。","respondent":"井浦戸籍住民課長","answer":"郵便局の不在連絡票を見失ってしまう、あるいは紛失されている方もいらっしゃいまして、コールセンターに相談を寄せられております。私ども、調べまして、区で保管しているかどうか、ご案内申し上げまして、あるいは非常にレアなケースについては個別に対応しています。","voiceIndex":26,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"もう１回、コンビニの手数料のところをもっとわかりやすく教えていただきたいのですけれども。","respondent":"井浦戸籍住民課長","answer":"コンビニにつきましては、まず利用者にお支払いいただく手数料について、窓口は３００円ですが、２００円を予定してございまして、ぜひ奮って利用していただきたいということで期待しています。","voiceIndex":30,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"区、どういうことなのだろう。ごめんなさい、ちょっといいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-010"},{"speaker":"渡辺委員","kind":"確認","question":"最初、通知カードの送付状況の報告があって、これは大体想定どおりだったのでしょうか。というのは、いざやってみたらこういうことがあったとかいうのがあるのかどうか、あるいは大体想定どおり来たので混乱なく行けているのかの確認が１つ。どんなふうに今後見込んで体制を整えていくか。","respondent":"井浦戸籍住民課長","answer":"国から１１月、１２月に通知カードが送られたわけですが、当初、１０月から通知カードを送付する予定でございましたが、１１月後半にずれ込んだというところで、会社に提出する期間そのものが短くなってしまったということで、現在。","voiceIndex":40,"id":"exchange-011"},{"speaker":"渡辺委員","kind":"意見","question":"最初のところ、まず送付の状況、戻ってくる率が想定より多かったと。その辺の変動はあるのか。私は、あってだめとかではなくて、今こそやはり混乱を避けるために、必要な経費は、いろいろな場合の対応は必要だと思うのですが、それだけ、最後にお聞かせください。","respondent":"井浦戸籍住民課長","answer":"事務の補助的なものについて、委託で対応できるところについてはできるだけ対応するという方針で臨んでございまして、国の事務のおくれ、ずれに対応するために、委託の人員増という部分についても、変更契約も含めまして予算上の措置を講じながら対応しています。","voiceIndex":42,"id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"ちょっと混乱したので、わからないまま聞きます。区にとって、このコンビニ交付はいいことなのですか。","respondent":"井浦戸籍住民課長","answer":"区が直営で朝６時半から２３時まで年中無休というのはなかなかコスト的に厳しいところですが、コンビニの営業時間、そしてＩＴ技術の進捗、セキュリティのかなりの進捗状況ということで、コンビニ交付ということでメリットを図っているところでございまして。","voiceIndex":44,"id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"やはり情報が本当に保護され、今の時代、本当にそれで安全なのかという、その安全の確証が全くもって不安なのです、コンビニとかでされてしまうと。品川区でコンビニ交付が始まって、もしも情報が漏れてしまったという場合はどうなるのですか。","respondent":"井浦戸籍住民課長","answer":"コンビニ交付につきましては、個々の店員が対応するものではなくて、コンビニに備え付けの機械で行います。","voiceIndex":48,"id":"exchange-014"},{"speaker":"田中委員","kind":"質問","question":"私もよくやるのですけれども、ＡＴＭとかの機械だとよくわからなくて、店員にこれはどうやってやるのですかと私はよく聞くのです。そうやって、そのやりとりの場合に店員が一緒にかかわることになるではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"そうなるのですか。そういうときはどうなるのでしょう。","respondent":"井浦戸籍住民課長","answer":"キオスク端末の画面表示にあります多言語対応でいたします。音声案内により個人番号カード取り忘れ防止対策等も講じられているものですので、安全が確保された形で実施できると考えています。","voiceIndex":51,"id":"exchange-016"},{"speaker":"田中委員","kind":"質問","question":"コンビニ交付は、確かに利用時間が増えて、いつでも行ける身近なところにあって、交付ができるというのはあるかもしれないのですけれども、情報が漏れてしまうというリスクが高くないですか。全て機械に任せてしまうとかというのは、どうなのでしょうか、リスクが高いと思うのですけれども。","respondent":"井浦戸籍住民課長","answer":"国の機関が一元的に情報安全につきましては責任を持って専用の回線、専用のシステムで管理していますので、外部から情報漏洩のアクセスができるような仕組みは、物理的にも技術的にも存在していないと認識しています。","voiceIndex":53,"id":"exchange-017"},{"speaker":"田中委員","kind":"質問","question":"今の答弁の感じだと、何かが起きても国のシステムなので区には問題ないということですか。","respondent":"井浦戸籍住民課長","answer":"マイナンバー法の施行に伴いまして、国の現在でき得る非常に高いＩＴのセキュリティレベルで構築されておりますので、そのようなことはないと考えています。","voiceIndex":55,"id":"exchange-018"},{"speaker":"田中委員","kind":"質問","question":"すみません。では、何かあった場合を考えていない、何かがあった場合には国の問題ということでよろしいですか。","respondent":"堀越地域振興部長","answer":"それは区としてやるべきことをしっかりとやるです。ただ、繰り返しますが、今現在の技術水準、それから物理的な対応、システム環境の中では、委員がご心配になるような事由については、発生する可能性は極めて低いと考えているところです。","voiceIndex":58,"id":"exchange-019"},{"speaker":"田中委員","kind":"質問","question":"区からコンビニの店員に、セキュリティの問題だったり交付の方法だったりとか、そういう指導はないのですか。","respondent":"堀越地域振興部長","answer":"それからあわせまして、用紙についても改ざん防止の所要の措置もなされますので、そういったこともあわせて対応していくです。それは当然行うということでご理解いただければと思います。","voiceIndex":60,"id":"exchange-020"},{"speaker":"たけうち委員","kind":"確認","question":"すいません、２回目ですが、コンビニのところなのですけれども、さっき、２００円予定で、それで現在、窓口が３００円と。これは、窓口も２００円にすると言っていたかどうか、そこの確認と、あと、多分ほかの方も思っていらっしゃると思いますけれども、そうすると、１２３円がコンビニに入ってしまうと、実質８７円しか区に歳入が入ってこない……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-021"},{"speaker":"たけうち委員","kind":"質問","question":"７７円ね。それで、なおかつ、コンビニのほうが安ければ、多分そっちに誘導するということで、かなりそっちを利用されると。ただ、それでもさっきおっしゃっていたように、その分、ほかの仕事ができるとか、区民の利便性とか考えて、区としてはこれでいいのではないかということだと思うのですけれども、予想としてはどれくらい減ってしまうのですか。","respondent":"井浦戸籍住民課長","answer":"２００円にして区の歳入がどうなるかですけれども、この点につきましては、やはり全発行数の１０％あるいは２０％という形でコンビニ交付が普及してくるにつれて、窓口でのニーズもその分減ってありますので、窓口の混雑緩和という効果も考えてあります。","voiceIndex":65,"id":"exchange-022"},{"speaker":"渡部副委員長","kind":"質問","question":"４月にでも、９月から２００円になりますよと言っていただいて、では、４月に申請したら９月に絶対間に合ってカードができているのかということなのです。それが間に合う担保がないのだったら、もっと早く告知しなければだめではないですかということを言いたいのです。","respondent":"井浦戸籍住民課長","answer":"本日の資料の２ページ目に書いてありますが、条例等の整備ということで、コンビニ交付には条例の制度が必要でございまして、平成２８年第１回定例会に上程予定ですので、早目に告知をしながら、このような利便性ということで皆様にお知らせしていきたいと考えています。","voiceIndex":73,"id":"exchange-023"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"だけれども、事前にコンビニ交付が始まって、２００円なのだよというときに、私、２月に申請しているのに９月の時点で２００円になるカードが来ていないというのが問題になるのかなと私は思って、それが８月でも７月にでもカードが絶対に到着しているのであれば、制度としていいと思うのですけれども、そういう方々に対してそういうふうにならない仕組みはあるのかなと思っているので。","respondent":"井浦戸籍住民課長","answer":"補足ですが、１１月に申請されている方のものが１月に国から納品されているですので、２月に申請された方は４月には区に届くのではないかということは間違いないかと思います。","voiceIndex":77,"id":"exchange-024"},{"speaker":"渡部副委員長","kind":"質問","question":"先ほどからみんなで言っている、２００円になって１２３円、コンビニだって仕事ですから、それは手数料があって、やると思います。逆に人の手を介さない分、安全なのかなと。１００％なくなりますよね。逆に、収入がなくなる分のところは行財政改革においてさまざまな仕組みを打っていくのかなと、それはまた後の問題なのですけれども、流れ的にはそういうふうに思うのですが、いかがですか。","respondent":"井浦戸籍住民課長","answer":"副委員長がおっしゃるとおりでございまして、例を申し上げますと、日曜開庁につきましては、７０％の方が住民票あるいは印鑑証明が必要で見えている方ですので、お近くのコンビニで交付を受けることができるという仕組みを推進してまいりますと。","voiceIndex":79,"id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"コンビニ交付なのですけれども、今年９月からということですから、これは当初から予定していたことだったのかなというのを、その辺を教えていただきたいのと、先ほど発行件数は未定だとおっしゃっていたけれども、大体どのくらい個人番号カードの発行を想定しているのか、予算をつくる上で必要だと。","respondent":"井浦戸籍住民課長","answer":"コンビニ交付の利用ですが、やはり個人番号カードがないと利用できないという部分がありますので、上限として全窓口発行数の１０％ほどを初年度で利用していただければと想定しています。","voiceIndex":82,"id":"exchange-026"},{"speaker":"南委員","kind":"意見","question":"窓口発行の１０％程度、初年度ですけれども、その後はどういうふうに推移するかわからないけれども、その１０％程度が１００円安い２００円の交付手数料になってくるということですね。そんなところで留めておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":84,"id":"exchange-027"}]},{"id":"topic-02","title":"「品川区消費生活・社会貢献活動展」の開催","agenda":"「品川区消費生活・社会貢献活動展」の開催","exchanges":[{"speaker":"南委員","kind":"質問","question":"ありがとうございました。その辺りを伺いたいと思います。","respondent":"河内協働・国際担当課長","answer":"一方で今回の社会貢献活動品川なのですが、まず一番の目的といたしましては、各団体の化学反応といいますか、お互いをまずは知るというところが大事になってまいります。そこで、団体の大事な要素は実は事業と人という面があります。","voiceIndex":91,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"出展団体一覧、数多くあるので、どういう形で入っているのか、また、入っていないかもしれないのですけれども、私が思うのは、こういうときこそ、多数来場者があるわけですから、やはりオリンピック・パラリンピックのブースを作ってアピールしていかないといけないという思いがすごくあるのですけれども、部が違うというのもあるかもしれないのですが、品川区という意味で、大イベントであるわけですから。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そうしたイベント関係につきましては、全てと言い切れはしませんけれども、今後もそういったイベントにおいて、こちらも見極めて、できるだけ出展をしていくような方向で考えているところです。","voiceIndex":95,"id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"バッジの色は関係ないとは思うのですけれども、毎回聞くと、そこのお二人の理事者の方でちょっと違う感じがするのですが。今、オリンピック・パラリンピックの担当課長にはこういうふうにやっていきますという答弁をいただいて、今までのこういう成果というか、やっていますと伺ったので、今日、担当が……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"そうそう、国際のほうの課長ですから、どういうふうにやっていこうと思っているのかについて、お伺いします。それと、あえて伺えば、バッジの色は関係ないのですということも答弁いただいて。何か違うから、その辺。","respondent":"河内協働・国際担当課長、小川オリンピック・パラリンピック準備課長","answer":"国際的にも大変恵まれたところですので、まずはリオオリンピックで国際的な盛り上がりを見せるとともに、本番の東京オリンピックに向けまして。現在、オリンピック・パラリンピックの暫定エンブレムといたしましては、こちらの桜のバッジが暫定的なエンブレムということで、こちらについては全職員並びに管理職等にもきちんと配布をして対応しています。","voiceIndex":98,"id":"exchange-031"}]},{"id":"topic-03","title":"第１２回 品川区新製品・新技術クラスターフェアの開催","agenda":"第１２回 品川区新製品・新技術クラスターフェアの開催","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"参加してみたいなという気持ちはあります。それと、さっき言ったように、そんな差し障りのあるようなところまで求めるつもりはないのですけれども、この２０社の大きな角度での特徴みたいなのがもしあったら、教えていただきたいと思います。","respondent":"立木産業活性化担当課長","answer":"やはり産業支援の交流施設ということでＳＨＩＰを開設させていただきましたので、そちらでいろいろな交流の中から生まれる新しいビジネス、新しい産業を品川ビジネスクラブとともに生み出していければというところで、来年度以後の施策に反映させていきたいと考えています。","voiceIndex":105,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"何で２月４日にやると決めたのかということと、それと、何で１日だけの開催なのですかという２点。","respondent":"立木産業活性化担当課長","answer":"実は昨年度はもうちょっと後ろでございましたけれども、区の行事予定とか議会の予定等をいろいろ勘案いたしまして、この２月４日という時期で、あと、企業がやはり３月になりますと、年度の切り替えということで、期末にもかかってまいりますので、３月。","voiceIndex":108,"id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"やはり大田区は３日間、日にちが長いからいいとか、そういう意味ではないのですけれども、私は個人的なことで言うならば、成果とかこの後またいろいろ出てくるとは思いますけれども、１日の凝縮ということもすばらしいと思いますが、大田区はたしか３日かけて同じ時期にやるということにおいて、それが効果があるとかないとか、いい悪いではなくて、頑張っているという思いがあるのですけれども。","respondent":"山崎商業・ものづくり課長","answer":"今回、自前のフィールドに戻りましたので、そうした日時、期間については今まで以上に柔軟な対応ができるかなということで、これからいろいろな意味で最適なものを検討してまいりたいなということと、開催のタイミングにつきましては、いろいろスケジュール的なものよりも。","voiceIndex":110,"id":"exchange-034"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、せっかくいい企業がプレゼンをやったりとか、区長も積極的にやるので、区内だけではなくて区外の方とか、幅広く目にとまって、せっかくそこに来て、すごく大きいビジネスチャンスが生まれる可能性も出展されている方にはあるので、そういう部分での広報はどれくらい力を入れていくべきなのかなということに見解があれば教えてください。","respondent":"立木産業活性化担当課長","answer":"いろいろ区のかかわりのあるメディアに、これからも引き続き周知に関してはいろいろＰＲを打っていきたいと考えております。","voiceIndex":112,"id":"exchange-035"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ある程度お金がかかっても、やってあげたほうがいいような気がするのです。私たちも委員会で初めて知るみたいなイメージがどうしてもあるので、事前に別のところで大々的というか、かかるお金等の兼ね合いもありますけれども、もうちょっとそっちにお金を使ってあげて、やっていただいてもいいかなと思いますので、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-036"},{"speaker":"渡部副委員長","kind":"質問","question":"日精ビルのときに何回か行って、今度、場所的には日精ホールより少し広くなるのですか。今回、自前のところに戻るというか、初めてＳＨＩＰの中でやれるということで、受付方法は、一般の方は入られたときに全体の名刺受けとかはありましたか。ではなくて、各ブースごとに名刺受けを持っているだけで、入りたい方は自由に入れる仕組みでしたか。どういう感じの入場をやっていたか、教えてください。","respondent":"立木産業活性化担当課長","answer":"入場に関しましては、特に名刺受けという形ではなく、各ブースでの名刺交換を行っていただくという形で行ってあります。","voiceIndex":115,"id":"exchange-037"},{"speaker":"渡部副委員長","kind":"確認","question":"どちらかと言いますと、当然、技術者ですとかメーカー、商社に見てもらいたいというところ、まして今回自前のところでいろいろ動かせるというのであれば、受付、どうですか、見本市みたいな感じで用意する必要があるかどうかは別ですけれども、例えばそこで名刺をもらっておくと、次からそれがデータベースになりますよね。２０社はビジネスクラブに入ってくれているのですよね。確認をします。","respondent":"立木産業活性化担当課長","answer":"受付の方法とか、その後の連携といいますか、ネットワークに関しまして、国内等でもさまざまな展示会等にも私ども職員が行っておりますので、そういったものも研究しながら、いろいろ工夫をしてまいりたいと思います。","voiceIndex":117,"id":"exchange-038"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"ありがとうございました。加入促進もしていただきたいのと、受付の方法を考えて、書いてもらうでは大変ですから、投げ込んでもらって、それをどう使うか、「何かの案内に使います」とかでいいと思うのですけれども。","respondent":"立木産業活性化担当課長","answer":"例えば展示会をきっかけに大手のメーカーと取引が始まったというようなことを聞いている案件もありますので、そういったものも何らかの形でＰＲしていきたいと思ってあります。","voiceIndex":119,"id":"exchange-039"},{"speaker":"南委員","kind":"質問","question":"すみません、さっき伺えばよかったのですけれども、この作ってくださった資料に出展企業が出ているのですが、例えば行きたいなと思っても、５分ずつのプレゼンにしても１時間半ずつ聞くのもつらいところがあるかななんて思ったりしたときに、例えば、わからないのですけれども、一番最後の株式会社ワイヤードジャパンは南大井にある企業ではないかなと気がして、そういうところがわかれば。","respondent":"立木産業活性化担当課長","answer":"そういったものも当日ご用意する予定ですので、そちらをご参考に、ぜひ各ブースをご覧いただければと思います。","voiceIndex":121,"id":"exchange-040"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"すみません、このような取組みの効果がどれほどあったら、例えば平成２７年度予算、はがきが３６万５,０００円あって、実績が６０件とかは、これは果たしていいのか悪いのかというのが実際問題どうなのだろうというのがよくわからなくて、そこら辺の説明をしていただきたいのと、どう考えていけばいいのかなということを聞きます。","respondent":"久保田地域活動課長","answer":"私どもが何もやらなければこういった加入の件数もなかったわけですし、二、三年前からはがきの申込は始めているのですけれども、やはりこういった取組みを地道に続けてきたことによって、町会活動が知られて加入へと結びついているですので。","voiceIndex":127,"id":"exchange-041"},{"speaker":"田中委員","kind":"質問","question":"この地域相談窓口の設置についてもなのですけれども、平成２７年度１２月時点で相談件数が２５件というのも、これもいつからカウントしているのかということとか、もうちょっと具体的に教えていただけたらありがたいなと思いました。","respondent":"久保田地域活動課長","answer":"はがきですけれども、当初始めたときは、宅建協会等と連携をして、不動産契約の際にファミリー世帯を対象に渡していただいたのですが、そのときは正直言って数件程度ということで、最近になりまして転入者の窓口等にも置こうということで。","voiceIndex":131,"id":"exchange-042"},{"speaker":"田中委員","kind":"確認","question":"確認です。今、相談件数が平成２６年４月から平成２７年１２月までで２５件ということで大丈夫ですか。","respondent":"久保田地域活動課長","answer":"はい、そのように思っていただければ。","voiceIndex":133,"id":"exchange-043"},{"speaker":"松永委員","kind":"質問","question":"ガイドブックについて質問したいのですが、このガイドブック、種類がさまざまで内容もさまざまだったのですけれども、これは誰がこのような作成をされているのか、お聞きしたいと思います。例えば連合会の会長が集まって、こういうふうにやったほうがいいのではないかという案を出しながら作られたのか、それとも地域センターで作られたのか、伺いたいと思います。","respondent":"久保田地域活動課長","answer":"例えば品川第一地区をご覧いただければと思いますけれども、制作は品川区第一地区町会・自治会連合会で作成しましたと記載をさせていただいていまして、実際には地域センターが事務局でかかわってありますけれども、各町会長等からご意見をもらいながら。","voiceIndex":136,"id":"exchange-044"},{"speaker":"松永委員","kind":"質問","question":"そうしますと、これは普通の紙でございまして、カラーで刷ったものと、これはちゃんとした分厚い紙だということで、これは多分地区ごとによって予算というか、違うのではないかなとは思うのですけれども。一緒ですか。大井第三地区連合会と大井第二地区連合会の差について。","respondent":"久保田地域活動課長","answer":"失礼しました。薄い紙のところは、部数がちょうど今なかったので、すみません、コピーで代用させていただいていますので、各地区ともしっかりした紙で作っています。申し訳ございません。","voiceIndex":138,"id":"exchange-045"},{"speaker":"松永委員","kind":"意見","question":"ちょっと関連して、最後。このガイドブックについては、地域センターに置かれているのか、それとも町会にどさっと置かれているのか。地域センターだったら、大井第三地域センターに大体何部数置いているのか、わかればお願いしたいのですけれども。","respondent":"久保田地域活動課長","answer":"大体つくる際には、地区の人口等もありますけれども、１万部程度ぐらいは作成させていただいて、それがなくなり次第、増刷をすると。内容の見直しとかを図りながらやっているです。","voiceIndex":140,"id":"exchange-046"},{"speaker":"たけうち委員","kind":"質問","question":"同じような質問になってしまうのですが、そうすると、各地区ごとにもちろん独自性を出していくのですけれども、統一のところとしては、地図は入れるよとか、濱野区長の挨拶が必ず入っているのですが、その辺は多分区の、そちらの部署なのかわからないけれども、こういうのはやってくださいねというもとでやっているのかなというのが１つと、これもすごくつまらないことで恐縮なのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-047"},{"speaker":"たけうち委員","kind":"質問","question":"時期が古いのか。やはり地図は入れようとか濱野区長を入れようとか、幾つかそういうのがあって、ただ、町会、あれによっては加入はがきをつけているところがあれば、それはあるところとないところがあるので、そういう意味で独自性はもちろん持ちながら、一定程度の統一性はやっているという考えでいいのですか。","respondent":"久保田地域活動課長","answer":"委員ご指摘のとおりでございまして、これは区と連携して作っていますので、区から最低こういうものは載せてくださいという項目の指定をしています。例えばですけれども、町会ごとの避難所については載せてくださいと。","voiceIndex":145,"id":"exchange-048"},{"speaker":"渡辺委員","kind":"質問","question":"世帯数は増えるのだけれども、戸建てで大体１００％近く入っていたところが、ひとり暮らし用になる、そして若い方が入るのは結構なのだけれども加入率は下がると。地域性。あるいはうちは結構いいのだよねと、安心とかではなく、ほっとしてもらうとか、こういう分析のことを、これは地域にやれというのは無理ですから、行政サービスとしてあり得るのかなと思うのですが、現状での見解を伺えればと思います。","respondent":"久保田地域活動課長","answer":"その前にはやはり現状分析が必要ですので、例えば加入率を例にとれば、加入の世帯をどう捉えているかとかいうこともお話を伺いながら、できるだけ一つの目安ではなくて基準になるような考え方で臨んでいきたいなとは思ってありますが、何分、相手のあることでもありますので。","voiceIndex":148,"id":"exchange-049"},{"speaker":"渡辺委員","kind":"質問","question":"入るべきですよと強くリードできる気がするのです。個別になったときにも、うちの町会の中では集合住宅、ファミリー層は１００％近く目指そうとか、何かそういう導きというか、リードを行政が、各町会は各町会だけれども、全体としてのリードは力を入れるべきだなという思いがあったので、すぐではなくですね、そこだけ伺って終わりにしたいと思います。","respondent":"久保田地域活動課長","answer":"それで、どこまでの範囲で、町会を拘束をしないような、自主性、主体性を尊重しながら、そういった区としての考え方、目標みたいなものを今後検討させていただきまして、示していければと思いますので、少しお時間をいただいて検討を進めていきたいと思います。","voiceIndex":150,"id":"exchange-050"},{"speaker":"たけうち委員","kind":"確認","question":"加入率のグラフなのですけれども、さっきもご説明があったとおり、大崎第二はカウントの仕方がというお話で、そうすると、今は各地区でカウントの仕方、さっき、特に一番大きいのは、マンション１棟でそれを１と数えるのか、１００世帯あって、１００入っていたら１００と数えるかで大きく違ってしまうと思うのだけれども、それは統一されているのですねという確認と、もし統一されていたとして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-051"},{"speaker":"たけうち委員","kind":"質問","question":"大崎第二と同じ、考えが変わったからこうなったのか、それとも何か要因があって、つかんでいらっしゃるか、教えてもらいたい。","respondent":"久保田地域活動課長","answer":"大崎第二は、過去の数のカウントの仕方がどうだったのですかということで確認をして、多分そういうことだろうという回答があったというものでございまして、その後、多分戻されて、こういう形で推移をしてきているとは思うのですけれども。","voiceIndex":154,"id":"exchange-052"},{"speaker":"たけうち委員","kind":"意見","question":"よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":156,"id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2742#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":42088,"voices":169}},{"id":"h28-20160119-7","meetingId":"h28-cm01","date":"2016年1月19日","dateIso":"2016-01-19","committee":"厚生委員会","time":"午後 １時００分～午後 ４時００分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"御殿山小学校西側敷地の事業計画案","agenda":"御殿山小学校西側敷地の事業計画案","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。１５日に地域の方への説明会があったということですので、この説明会での地元の方の声ですとか、また、複合施設ということでありますので、図書館、病院が併設されるということでの何か地域の皆様の声がありましたら、お聞かせいただきたいと思います。","respondent":"大串福祉計画課長","answer":"先週金曜日の説明会のご質問です。この日は全部で８７名の方にご参加いただきました。７時からということで説明会を開始いたしまして、８７名の方にご参加いただき、この施設の説明、内容、中身についてのご説明をさせていただいた上で質疑という形になりました。","voiceIndex":5,"id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問","question":"お伺いしたいのですけれども、これは周りの明細地図を見ると、高層のビルといいますか、オフィスビルが林立といいますか、立って、中には一戸建てなのか、そういうところもある。向こう側は高級住宅街になっているわけです、八ツ山通りの向こう側といいますか。品川でもどちらかというと端のほうなので、どういったまちづくりを想定しておつくりになるのかということだけ教えてください。","respondent":"大串福祉計画課長","answer":"まちづくりといった観点でお答えするのはなかなか難しいところかと思いますけれども、まず冒頭お話しさせていただきましたように、２カ所目の老健施設ということ、ちょうど南側と北側にでき上がったといったところで、この拠点、２つ目ということで。","voiceIndex":8,"id":"exchange-002"},{"speaker":"いながわ委員","kind":"質問・要望","question":"本当に２カ所目の老健ができるということはすばらしいことであるのですけれども、それと同時に、そういった大きな建築物を建てるということは、やっぱり周りのさまざまなまちづくりにも影響が出てくる中で、恐らくいろいろな設計の中で建てていると思うのですけれども、ぜひまちづくりを牽引する、これは別に所管が違うからという議論ではなく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003"},{"speaker":"横山委員","kind":"質問","question":"１点だけお伺いをします。今回、図書館と老人介護保健施設との複合施設ということで、例えばインフルエンザですとか、エボラですとか、１類感染症などの衛生面につきまして、施設としてはどのような対応を考えていらっしゃるのでしょうか。","respondent":"大串福祉計画課長","answer":"ただ、今のところ、先ほど申し上げましたように、１階部分が総合受付という形になっておりまして、エントランス、基本的には病院の方、あるいは老健にいらっしゃる方、図書館にいらっしゃる方、入る形にはなっておりますけれども、まずはその辺のセキュリティ。","voiceIndex":11,"id":"exchange-004"},{"speaker":"のだて委員","kind":"確認","question":"２カ所目の老健施設としてできるということで、大変喜ばしいと考えています。そこで確認なのですけれども、今回、区分所有ということで区と事業者で分けると思うのですけれども、そこの確認なのですが、土地は区の所有で、建物はこの事業構成で書いてあるところの１）から４）番までが区の所有で、５）番が病院の所有ということでよいのかということです。","respondent":"大串福祉計画課長","answer":"土地の所有関係のご質問です。土地については、先ほど来申し上げますように品川区所有の土地です。建物ですが、建物につきましては、図書館のみが品川区の所有というふうになります。それ以外につきましては運営事業者であるこちらの河野臨牀医学研究所の所有という形になります。","voiceIndex":14,"id":"exchange-005"},{"speaker":"のだて委員","kind":"確認","question":"ちょっと勘違いしていたようで。そうすると、介護老健施設というのは民設民営ということになるということでよろしいかということと、この区分所有によって区と事業者でこういった所有の配分をして区の土地を貸し出してやるということは、これは今までもあったことなのかどうか、初めてのことなのかという確認です。","respondent":"大串福祉計画課長","answer":"２つご質問かと思います。１つ目、こちらの老健施設、これについては委員おっしゃっていただいたように民設民営という形になります。それから、こちらは、スキームとしては、今回、区として初めてになります。","voiceIndex":16,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうしますと、今後、建て替えというか、修繕とか、こういったことになってきたときに、この区分所有でやっていることによるメリットとかデメリットがどういったものがあるのかということをお聞かせいただきたいと思います。","respondent":"大串福祉計画課長","answer":"地域包括ケアというところで言葉を出させていただきましたけれども、最終的には在宅での生活の継続、これを最終的には区としても考えているところですので、こういった形でリハビリテーションの病院、リハビリ機能に特化した形での病院、それから、その後。","voiceIndex":18,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"１カ所で、この場所で病院と急性期の治療と、介護、在宅介護へもつなげて、ワンストップでできるということだと思いますので、それは大変すばらしいことだと思いますので、しっかりとやっていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"これは民設民営ということなのですけれども、区としてプロポーザル方式で事業者を公募して、そしてこの北品川が採用されたということになると思うのですけれども、区とのこれからのかかわりというところは、どうなっていくのかというあたりを教えていただきたいのですけれども、この事業者と区との契約というのですか、どんな契約が交わされていくのかということと、あと、ここの公募の中でも、定期借地料。","respondent":"大串福祉計画課長","answer":"そこから借受事業者ということで、この法人と話し合いを進めながらこの計画を進めているといった中です。今般、基本設計がまとまったという段階で、こういった地域への説明等々を行ったという流れになっております。","voiceIndex":21,"id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もう１つは、この公募の要項の中では、老健およびショートステイは、入所者１人当たりの延床面積を４０m2以上としてくださいということがあったのですけれども、この４０m2という意味は、多分個室の１人当たりの占用面積というものではなくて、全部割返した面積というふうなことになるのかと思うのですけれども、そこら辺の４０m2という意味を教えていただきたいのと、それからあと。","respondent":"大串福祉計画課長","answer":"済みません、前段の４０m2という、それは後ほどご答弁します。今のところ、多床室、要するに、従来型のものと個室というところでは、９６床を従来型というふうに考えております。４室については個室という形で今のところ整備計画を詰めているところです。","voiceIndex":23,"id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"補助金については、ここに書かれている東京都の補助金、１ベッド当たり４０５万円掛ける、多分この１.５というのは整備率の低いところは１.５倍になるというふうなところで１.５というふうになっているのかと思うのですけれども、この４０５万円掛ける１.５掛ける定員数というところでの補助金が出るということで考えていいのでしょうか。","respondent":"大串福祉計画課長","answer":"施工費の関係、老健関係です。訪問看護と訪問リハ、これが入った形になりますけれども、施工費としては、今のところ、１７億６,５００万円ほどを見込んでいるです。","voiceIndex":25,"id":"exchange-011"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"最後にご説明いただいた就労の総定員なのですけれども、昨年度、就労継続支援Ｂ型とＡ型が結構増えているのですけれども、これは新たな施設が建設されたのか、それとも定員を増やしたのか、もともとある施設にさらに拡大したのか、その確認です。","respondent":"中山障害者福祉課長","answer":"平成２６年度から平成２７年度にかけて伸びているところですけれども、特にＢ型については、ふれあい作業所が法内事業化したというところで、定員がここで増えているところです。それからＡ型の事業所としましては、この間、民間の事業所ができております。","voiceIndex":31,"id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"障害者計画などを見ても、この就労支援については、障害に合った仕事が見つからないとか、相談できるところを増やしてほしいというか、自分に合った仕事を見つける支援を求めるということがアンケートで一番多いものになっているのですけれども、そのところをこの『げんき品川』が担っていると思うのですけれども、今、職員配置５人と書いてありますけれども、しっかりと支援できているのか。","respondent":"中山障害者福祉課長","answer":"５人の人数につきましては、現在、場所の問題もございまして、その中でやってはいるのですけれども、ただ、自立支援協議会の下部組織である就労の部会ですとか、そういうところには区内のこうした事業所も全部入っていただいて、連携をとりながら進めているところですので。","voiceIndex":35,"id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"平成３０年から精神障害者の方の雇用義務化もされるということで、今これはなかなか障害者だけでなく、企業との関係性もあって、やはり自分に合った仕事を見つけることが難しいということでしたけれども、今、区が重点に置いているというか、課題と思っているところはどこか伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"課題といいますか、やはり障害のある方はいろいろな障害があるので、その方お一人おひとりに合ったマネジメントをしていくことがすごく難しいと思っています。","voiceIndex":37,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうですね。今おっしゃられたとおりに、やはり障害者の方でも仕事をして社会で一緒に生活していけるような品川区にしていっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"確認なのですけれども、この表に示していただいておりますこの関係機関、連携をとっているということなのですが、具体的にどのような形で会議がもたれているのか、どういう形で場のあっ旋を進めていただいているのかということを確認をさせていただきたいと思います。これは基本、認定を受けてから利用するという流れでよろしいのか確認をさせていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"実際には、例えば、今どういった取り組みをしているか、それぞれの事業所の工夫ですとか、あるいは困難ケースのケース・スタディーみたいなものを共通の場で認識を持つことで意見を出し合って、では。","voiceIndex":40,"id":"exchange-016"},{"speaker":"新妻委員","kind":"質問・要望","question":"本当になかなか現状は難しいところもあると思うのですが、しっかりまた確保の拡大に向けて取り組みを進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-017"},{"speaker":"横山委員","kind":"質問・要望","question":"何点か質問させていただきたいと考えています。新しいお仕事を請け負えば、それだけ障害者の方の就労の可能性ですとか、お一人おひとり持った能力を生かしていける枠組みが広がってくるのかと思うのですけれども、新規開拓をするような営業のようなことにつきましては、区として何か支援されていることがあるのか教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"区といたしましては、就労支援センターの『げんき品川』にそうした啓発事業のところをお願いしておりますので、法が変わったということですとか、新たなこういう障害の理解をというところについては、そのような形で進めていることが１つと、それから、今年度は。","voiceIndex":43,"id":"exchange-018"},{"speaker":"横山委員","kind":"提案","question":"今、議員の方からのご紹介などもあるというお話がございましたけれども、障害者の支援をされたいという企業がいらっしゃるかと思いますので、区のホームページのご案内ですとか、先ほどの総務課の啓発事業の中で、また講演会の中でそういったマッチングですとか提案、こういったことがやっていただけないかみたいな提案制度みたいなものもご検討いただいたり、また、周知をいただけたらと考えていますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この就労の問題で、障害者団体の皆さんと懇談をしたときに、就労Ｂ型でも、実際の定員よりもすごく利用者が多いということで、一覧表もいただいてご要望いただいてきたのですけれども、１４年までしかないのですけれども、１４年のときには、さつきでは４０名のところが５７名、第二しいのき学園では６０名が７９名、西大井福祉園では１５名が１８名、それから。","respondent":"中山障害者福祉課長","answer":"今、ご利用人数のお話があったのですが、定員と登録者、それから実際の稼働率を入れた利用率があるのですけれども、利用率で見ると、就労継続Ｂ型でいくと、１００％はまだ超えていないのが現状です。","voiceIndex":46,"id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この障害者計画の中でも、就労機会の充実と就労支援体制の充実というところで、現状と課題というところで、法定雇用率の達成に至っていない状況だというのは、多分これは品川区役所ということではなくて、全体でというところで、それをいろいろな形で啓発もしながら進めていくということだと思うのですけれども、品川区役所としてもできることというところでは。","respondent":"中山障害者福祉課長","answer":"今のところは法の制度はそうなっております。品川区の実際の内訳というようなお話かと思うのですけれども、これは最終的には人事に確認してみないとわからないのですけれども、身体障害者の方を中心に、精神障害の方も雇用しているというような状況になっています。","voiceIndex":48,"id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もう１つお聞きしたいのが、この『げんき品川』の職員配置が５人となっているのですが、この５人の職員の方の仕事の中身というのですか、相談の人が何人いるとか、ジョブコーチの方が何人いるとか、５人の方の仕事の中身について教えていただきたいのと、それからあと、多分、『げんき品川』の方だけでなく、ジョブコーチという仕組みがあると思うのですけれども。","respondent":"中山障害者福祉課長","answer":"お一人は生活支援です。勤めるということは、まず日常生活が安定していないと次のステップには行けませんので、生活支援の相談を主にする人がお一人。それから、就労の支援ということで、ジョブコーチを含めてやる方が３人。","voiceIndex":50,"id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"実際に就労の現場で、障害を持っても働き続けることができるかどうかというのは、ジョブコーチの方が、その方を本当に障害を含めてきちんと理解をして、そしてその人に合った形で支えて支援をしていくということがすごく大事なのではないかと思うのですけれども、現実のところでいろいろと相談を受けている部分もあったりするのですけれども、ジョブコーチの方の研修だったりとか。","respondent":"中山障害者福祉課長","answer":"一方で、報酬でつなげることで、しっかりとした仕組みをつくっていくというのが法の枠組みの中で１点あるのと、それからやはり品川区内の事業所であれば、そういったことを先ほど申しました就労支援の定例会の中でも話をしていっておりますので。","voiceIndex":52,"id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"障害を持っても働き続けたいというのは、本当に皆さん思っていることだと思うのですけれども、それが実際に続けられるためには、さまざまな支援が必要だと思うのです。そういうところで本当に障害の方への理解と十分なハード面に加えたソフト面の充実というふうなところに引き続いて取り組みを進めていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういう考えでこれを進めていかないと、区として、地方自治体としては、なかなか大変なのかという気もあるのだけれども、これのもともとの考え方は、どういうふうに捉えたら、我々もいろいろな方から、いろいろな団体の方から聞くのだけれども、そこまで全部は、いろいろ伺うと、だめとは言わないけれども、役人言葉みたいな、議員も使ってはいけないのだろうけれども。","respondent":"中山障害者福祉課長","answer":"障害のある方は、雇用の場に来られる方だけではなく、大変重たくて医療の必要な方ですとか、いろいろなさまざまな支援を必要とされている方がいらっしゃるので、状況をトータルに見て、どこからやっていくか、一遍に全てのことができるわけではないと考えていますので。","voiceIndex":55,"id":"exchange-025"},{"speaker":"若林委員","kind":"確認","question":"確認ですけれども、主にＡ・Ｂ、就労移行もありますけれども、いわゆる作業所といいますけれども、先ほど、ネジに何か巻くとかという、そういう作業所で行う作業、公園で清掃とかありますけれども、それも含めて、いわゆるそういう作業、主な内容はそういうことでいいのかという。代表的なものを逆に挙げていただければ、その２点。","respondent":"中山障害者福祉課長","answer":"実際に区内の作業所、就労継続支援Ｂ型・Ａ型でどのような仕事をしているかというところですが、ふれあい作業所の公園清掃などをはじめとして、例えばお菓子の製作ですとか、あるいは内職的なお仕事ですとか、あるいは手工芸品みたいなもの、ビーズですとか。","voiceIndex":58,"id":"exchange-026"},{"speaker":"若林委員","kind":"質問・要望","question":"一方で、よく耳にするのが、今は高齢者でも社会参加ということで、高齢者が高齢者のお世話をしたり、ちょっとしたことをご近所で、いわゆる支え愛・ほっとステーションみたいなことが今、品川区で行っていますけれども、障害のある方の中にも、支援区分の内容によっては、自分の手作業、自分の体を使うということ以外に、人と相対して何か、接客というとちょっとあれですけれども。","respondent":"中山障害者福祉課長","answer":"新たな課題ということで、相手先もあることですので、検討課題とさせていただきたいと思います。","voiceIndex":60,"id":"exchange-027"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"多分、建設委員会でご報告があったのかもしれませんが、この３年ぐらい開設まで月見橋が仮移転の場所になってしまうという、もうちょっと詳しい理由と、仮移設が延びることによって、建物の影響とか、そういった施設として問題ないのかということの確認です。","respondent":"永尾高齢者福祉課長","answer":"仮移設が延びることによる影響ですけれども、月見橋の家自体につきましては、特に影響はございません。こちらのデイサービスについては、送迎で実施しておりますので、今までの移設をする前の方のご利用者も継続して利用しています。","voiceIndex":69,"id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ノロウイルスによる食中毒というのは、随分前になるのですけれども、品川区立の保育園で、その当時まだノロウイルスという名前になっていなくて、ＳＲＳＶということでの食中毒の発生で、二次、三次に拡大していったというところで、厚生委員会でもすごい議論になったことを私は記憶しているのですけれども、そういうときに。","respondent":"高山生活衛生課長、舟木品川区保健所保健予防課長","answer":"もちろん被害の拡大防止ということで、そういった聞き取り、それから消毒に関する部分につきましては食品衛生監視員のほうから指導を試みたところです。感染につきましては、予防課長のほうからご説明を申し上げます。探知したときから保健予防課と食品衛生とで動きまして、感染発症の経過から、ノロウイルスも疑いまして、嘔吐物、あとは排泄物の処理についてのこと、あと、自分の手洗いが必要なこと等については、十分指導してまいりました。","voiceIndex":74,"id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"本当にこういうところで、多分、そこのところではかなりここの厚生委員会の中でも議論になりましたので、その後は、多分、保育園とかさまざまなところでそういうノロウイルスの発症があったときには、どういうふうに対応するというのはさまざまなところでマニュアルもできていて、そういう対応がされているのかと思うのですけれども、家族にもきちんと指導がされているということなので。","respondent":"高山生活衛生課長","answer":"これにつきましては、やはり手洗いの励行でありますとか、あるいは、調理従事者の健康管理などが大変重要になってまいりますので、そういったものについては今後も繰り返し衛生指導の中で普及啓発を図ってまいります。","voiceIndex":77,"id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今回は重症な方が出ていないということだったので幸いだったと思うのですけれども、子どもですとか、高齢者ですとかは、本当に下痢、嘔吐で脱水で重篤になる場合もありますので、教訓にしながら今後進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3436#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":33162,"voices":81}},{"id":"h28-20160119-8","meetingId":"h28-cm01","date":"2016年1月19日","dateIso":"2016-01-19","committee":"建設委員会","time":"午後 １時００分～午後 ３時４８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の区営住宅および都営住宅（平成２８年２月）の入居者募集","agenda":"の区営住宅および都営住宅（平成２８年２月）の入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"区営住宅のほうですけれども、このところの応募の人数の傾向をちょっとお伺いしたいのですが、このところ増えているのでしょうか、減っているのでしょうか。その原因についても合わせてお考えをお聞かせいただければと思います。","respondent":"矢木住宅担当課長","answer":"全体的傾向といっても、それぞれのお部屋の大きさであるとか、対象人数でありますとかでさまざまですので、ちょっと一概には把握できないというのが現状です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"直近の２回ということでしたけれども、増えているということもありますし、平均して６７.７倍ということで、大変多くの方が求めているということですので、ぜひ区民要望もありますので、積極的に区営住宅の増設に向けて努力していただきたいと思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"今のお話の中でも、倍率が結構高いというふうに思うのですが、今空き家が非常にあると思うのですけれども、それの有効活用としてなるべく多くの方に、要は建物は違うけれども、制度的に区営的な使い方で空き家を利用するとか活用するという考え方はないのでしょうか。そこまでする必要はないと区は思っているのか、いかがでしょうか。","respondent":"矢木住宅担当課長","answer":"空き家対策としては住宅確保要配慮者に対する住宅供給というのは当然のことながら検討する課題になるものと認識しておりますし、研究を始めているところです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"西本委員","kind":"意見","question":"意見ですけれども、希望者は多いと、前々から区営、都営はそうですけれども、多いというふうに感じていて、それに対して区内の空き家対策の一環として何か工夫ができればいいというふうに思っているのです。私もちょっと研究していきますが、ぜひとも検討をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-004"}]},{"id":"topic-02","title":"の品川区立区民住宅ファミーユ大井における漏水事故に係る損害賠償請求事件経過報告","agenda":"の品川区立区民住宅ファミーユ大井における漏水事故に係る損害賠償請求事件経過報告","exchanges":[{"speaker":"鈴木（真）委員","kind":"確認","question":"最初ちょっとわからなかったのですが、上部の階、７階だから８階ですか、ここから水漏れしたと、それの原因がわからないということですが、建物が古いからですか、そこをもう一回確認したい。","respondent":"矢木住宅担当課長","answer":"漏水部分につきましては、こちらが一番争いになったところなのですが、浴室に設置していた洗濯機のトレイとトラップ、あと排水の管があるのですが、そこのいずれかが外れて床下の空間を通りまして、それが階下の和室のほうにしみ出していった、そういう形です。","voiceIndex":15,"id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。それと、判決の一番下、米印のところに、結局この６２５万円余の請求は、勝ったというか、勝訴したわけですが、本人はもう引っ越したのですか、まだ住んでいるのですか、どうなっているのですか。","respondent":"矢木住宅担当課長","answer":"こちらの訴訟につきましては、平成２２年にまず建物の明渡し請求の訴訟をしておりまして、今般の訴訟を提起する前に勝訴判決を受けて退去しております。","voiceIndex":17,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"よくわからないところがあって、要はけがをされたと、これは２種類問題が書いてあるのです。一つはけがをされたので、それを補償しろというのが一つあると思うのですが、それとまた別途、滞納されているということにおいては、滞納は滞納で処置はされているということで二つ、同じ人なのですか。２種類あると思うのですが、そこの関係性がちょっとうまくわからないので、整理してもらってよろしいでしょうか。","respondent":"矢木住宅担当課長","answer":"滞納のほうからまいりますと、滞納は使用名義人と申しますか、使用者は今回原告の奥様でございまして、奥様に対して区が負った責任といたしましては、安全に住居内でお住まいになる大家としての義務、これを怠ったということに対しての水漏れの物損とあと一定期間。","voiceIndex":20,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"今回の判決が出たことで、今後どのような影響が出てくるのか、そこら辺を区としては考えているのかお伺いしたいのですが。","respondent":"矢木住宅担当課長","answer":"ですので、そういう場合は、同じ住宅内にお移りいただいて調査をいたしますとか、その期間内での費用を負担するとか、そういった対応をいたしまして、一刻も早い原因究明と復旧策、あと入居者に対するご説明をした上でご理解をいただいている。","voiceIndex":22,"id":"exchange-008"}]},{"id":"topic-03","title":"の品川区の環境に関する各計画の実績報告等","agenda":"の品川区の環境に関する各計画の実績報告等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、去年の年末にパリ協定ということで、新たな地球温暖化防止の世界的な合意があったわけですが、パリ協定では、気温上昇１.５度を視野に入れて、２度未満にとめるということが決定したということで言われておりますけれども、こういった世界的な目標を達成する上で、品川区の各計画の整合性はどうなっているのか、これから見直すという計画があるのかどうか、それをお伺いします。","respondent":"三ツ橋環境課長","answer":"年末のパリ協定に関しまして、品川区として整合性、こちらの削減率等につきましては、環境計画等の見直しを含めて、これから検討していきたいと思います。","voiceIndex":28,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"ですから、確かに新しく建つビルというのは、最新の技術でできているので、従前の同じ基準のビルに比べれば大変環境に配慮していると言えるかもしれないのですが、全体量が増えては本末転倒になってしまうのではないかと思うので、そこら辺の再開発等のオフィスビルとか、そういったことに対する対策というのは、ＣＯ２削減という点ではどのように区は考えているのかお伺いします。","respondent":"三ツ橋環境課長","answer":"業務部門につきましては、非常に難しい部分があります。ビルにつきましては、やはり今最新のビルというのはデムスなども取り入れているところが多くなっております。","voiceIndex":30,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"その辺はやはり推測ではなく、地域のデータとして従前の品川区の持っているデータと、それが再開発でビルが建った場合の量の比較というのはきちんとしていかないと、ちょっと科学的な排出抑制にならないのではないかと思いますので、その辺は研究していただきたいと思いますし、私たちも研究していきたいと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"３ページにあります実績と分析というのがあって、家庭と業務の部門の増加傾向が続いていると、重点を置いてということで、太陽光発電、ＬＥＤ照明設置助成ということなのですが、これは今後具体的なことが出てくるのでしょうか。太陽光発電というのは、品川区の中では難しいと思うのです。なので、非常に都会の中での太陽光発電というのは非常に難しい部分があるので、そこのところはどう考えられるのか。","respondent":"三ツ橋環境課長","answer":"太陽光発電につきましては、非常にそこの屋根というのも１個１個非常に難しい形態になっているのは委員おっしゃるとおりだと考えています。しかしながら、太陽光発電につきましては、区といたしましては推進していきたいと考えています。","voiceIndex":33,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"太陽光発電というのは難しいので、ここで大きく何かやろうと言っても現実的には難しいとは思っています。ただ、助成金がいいかどうかは私はわかりません。助成まで家庭にそれをするのは無理だろうというか、やはり努力をしてくださいということなのだろうと思うのです。最後に風力で、例えば地域のほうで風力発電の協定を組むとか、そういう考え方を品川区は設ける考えはありますでしょうか。","respondent":"三ツ橋環境課長","answer":"品川区内でどのようにしていけば自然エネルギーを使っていけるのか、また再エネルギーについては慎重に考えていかなければならない問題でして、風はどのあたりが一番効果的なのか、規模的にどのような部分で対応が可能なのか。","voiceIndex":35,"id":"exchange-013"}]},{"id":"topic-04","title":"の清掃事業の概要と事業系廃棄物への対応","agenda":"の清掃事業の概要と事業系廃棄物への対応","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"品川区のごみの量の推移がありましたけれども、このところ品川区は人口が増えているのですが、ごみの量は減っている。微減ということなのですけれども、ちょっと消費不況というのもあるのかと思っているのですけれども、その辺はどうなのかということをお伺いします。","respondent":"小林品川区清掃事務所長","answer":"ただ、かなり積極的に取り組んできてもらった結果として、まだまだ継続してまいりますけれども、今後のあい差、減少できるエリアというのは若干小さくなってきているのかと、資源がもっと進んでいるのかと思われたという委員のご印象がありましたけれども、大分進んできたので。","voiceIndex":41,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後のところは大分イメージがついてきました。そういったところにも役割分担等はあると思うのですけれども、品川区としても、できるところから働きかけ等を含めて取り組んでいく必要があると私は思っているのですが、いかがでしょうか。もし、既に何か取り組んでいるということがあれば教えていただきたい。あわせて、お伺いします。","respondent":"小林品川区清掃事務所長","answer":"あえて申しますと、一つリユースの観点からいうと、リターナブルびんの取り組みと、もう一つの例でありますけれども、根本的に製造システムの中の役割分担というのはむしろ国全体でその役割分担のあり方を検討していくという必要があるかと思います。","voiceIndex":43,"id":"exchange-015"},{"speaker":"筒井委員","kind":"質問・要望","question":"私の勉強不足かもしれないのですが、まず基本的な用語の定義というのをお聞きしたいのですけれども、まず廃棄物はごみですか。廃棄物イコールごみなのかということと、それから資源という定義をもう一度お伺いしたいと思います。リサイクルできるものが資源という意味なのか、その辺を確認したいのでご説明をいただきたいと思います。","respondent":"小林品川区清掃事務所長","answer":"一方資源、これもまたわからない言葉なのですけれども、一言で言うと再生利用が可能な物質、それをもって資源というふうに考えて、もう一回使えるようなものはリデユース、リユース、リサイクルとありますけれども。","voiceIndex":45,"id":"exchange-016"},{"speaker":"筒井委員","kind":"意見","question":"よろしくお願いします。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-017"},{"speaker":"つる委員","kind":"質問","question":"私も一つ教えてください。食品ロスについては、先ほどご案内いただいたごみレポの３５ページで、こちらなのですが、資源有効利用促進法の中の扱いというふうになるのでしょうか。それをまず基本的なことなのですけれども教えてください。","respondent":"小林品川区清掃事務所長","answer":"一方、食品の食べ残し等のものにつきましては、それをもう一度家畜飼料等に再生するというような試みも業種によっては取り組まれているというふうに聞いておりまして、その辺の推移を見守っていきたいと考えております。","voiceIndex":48,"id":"exchange-018"},{"speaker":"つる委員","kind":"質問","question":"その容器自体がいろいろな貧困で苦しんでいるような海外だとかの支援につながっているという取り組みもこの間紹介されていましたけれども、私もずっとそれに関心があって、長く追いかけていたら、たまたま国会で取り上げられていたのですけれども、そういうような視点で、そもそも特に食というところについては大事な観点がありますし、本日の部分につながるかと思うのですが、品川区として何か可能性とか。","respondent":"三ツ橋環境課長","answer":"今委員の食品ロスに関する考え方ですけれども、品川区の環境課といたしまして、“もったいない”推進店という“もったいない”プロジェクト事業を今年度から立ち上げておりまして、各商店街の中の、特に食品関係のお店につきまして。","voiceIndex":50,"id":"exchange-019"},{"speaker":"つる委員","kind":"質問","question":"国会のほうで紹介したものは学生が民間のホテルにというあれなのですけれども、そういうのを区として何かしらアクションを起こせないのかと思うのですが、ここをもう一度伺いたい。","respondent":"三ツ橋環境課長","answer":"しかしながら、何かやはり食品ロスに向けてはオリンピック・パラリンピックの環境配慮にも向けて取り組まなければいけないことだと考えていますので、また何か新しいことも考えていければと考えています。","voiceIndex":52,"id":"exchange-020"},{"speaker":"つる委員","kind":"確認","question":"だけれども、ちょっと私も国会の答弁を詳細に確認しているわけではないのですが、そこは非常に大事だと記憶しているのです。子どもの貧困だとか、子ども食堂という話も一般質問の中でさせていただいて、一方で、そういう食に困っている、本当に衣食住とかねてから言われているような基本的なところすらも危機的な家庭がある中で、一方で世界的に見ても食品ロスというのは大きいわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-021"}]},{"id":"topic-05","title":"のしながわ区民公園中央ゾーン改修工事等","agenda":"のしながわ区民公園中央ゾーン改修工事等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"公園内に保育園の設置ということなのですけれども、この所管の防災まちづくり部としましては、公園内の保育園設置が可能かどうかという判断基準というのですか、例えば面積になるのでしょうか。内容については固まっているのか、それとあわせて、住民説明会が２月２６日に行われるということですけれども、どういった方々を対象に説明会があるのかお伺いします。","respondent":"多並公園課長","answer":"説明会の対象ですけれども、直接ビラをまかせていただく範囲としましては、公園から２５０ｍの範囲の約６,０００戸の方々に直接ポスティングする計画です。","voiceIndex":59,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"アイデアのほうは、平成２０年にやっていました。それとあと、保育園の設置ですけれども、地域によっては本当に求められているところがまだまだあって、保育園の増設が必要だと思いますので、どんどん進めていただきたいと思っているのですが、今言ったような建設部門のほうの基準としては広場の３０％以内ということですので、割とあるのかと思ったのです。","respondent":"多並公園課長","answer":"だから、もともと平成２０年に子どもたちからいただいたアイデアを実現していこうということで、各地区の中で、改修の中でその一部を活かしていこうということで今まで進めてきて、鮫洲運動公園で初めてやって、２番目は二葉公園をやったのですけれども。","voiceIndex":61,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"確認ですが、キャンプ場も整備するということで、これはいつまで使えるのでしょうか。多分出入りのところでは１カ所、北門とかだと５時とかで閉じてしまうと思うのです。なので、住民説明会のときは保育課と協力してやるのでしょうけれども、いろいろと難しいかと、ご理解を求めても、ご理解できない方がいらっしゃるのではないかというふうに予測を立てているのですが、いかがでしょうか。","respondent":"多並公園課長","answer":"ただ、その中でも、樹木の先ほど申しましたけれども、それは一定のバッファでもありますから、そこら辺でご理解いただくように説明していきたいと考えています。","voiceIndex":64,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"もう少しちょっと、今の段階でキャンプ場のところですが、５月、ゴールデンウィーク明けぐらいから使えなくなる、いつごろまでですか。それであと保育園の件は、この保育園は、聞くところによると在籍費という考え方もあるので、ですから、やはり区民公園の予算というものを確保しつつ安全面を含めた形でうまくやっていただきたいと思うのです。住民に対しては、いろいろ意見が出てくると思います。","respondent":"多並公園課長","answer":"今予定としては、７月ぐらいに工事の説明会を行って、現場に入っていきたいというのが現在の考え方です。","voiceIndex":66,"id":"exchange-025"}]},{"id":"topic-06","title":"の(6)立会川雨水放流管工事（東京都下水道局施工）","agenda":"の(6)立会川雨水放流管工事（東京都下水道局施工）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"これは立会川の貯留管ができ上がって、その水を運河のほうに流す管ということの理解でいいのでしょうか。それとあと、周辺区民あるいは利用者等への説明を実施するということですけれども、これは東京都が説明するということのようですが、そういった方々にどのような形で説明をすると聞いておられるのかお伺いします。","respondent":"和田河川下水道課長","answer":"それから二つ目ですが、周辺への影響、それから防護とはどういうことかですが、周辺構造物への影響といいますのは、当然立会川の直下を掘進してまいりますので、立会川の護岸への影響、それから将来的にここに津波、高潮用の水門が建設局で設置される計画ですけれども。","voiceIndex":72,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"なぎさ会館から月見橋のところに全くまだ入っていないということですか。入る前になぎさ会館のところに建屋が既に建っていたと思うのですけれども、大分掘っているのかと私は認識していたのですが、全く掘られていなかった。全くではないかもしれないですけれども、なので、今回のというのは、全然まだ掘っていないと、赤線がという理解でよろしいでしょうか。","respondent":"和田河川下水道課長","answer":"貯留管としてできてありますので、なぎさ会館のところをたて穴として利用している期間、平成２０年からずっと占用しているわけなのですが、その間ずっと工事がされていなかったということではなくて、この立会川の下を掘進する工事、これはこの工事工程で言いますと。","voiceIndex":74,"id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この検討がされて、当然いい流れで、いい形にもっていくのでしょうけれども、この検討している状況は、品川区に通知があったのでしょうか。","respondent":"和田河川下水道課長","answer":"事実を申しますと、正式に報告がありましたのは、昨年１２月１５日、この日に区長に東京都下水道局の幹部から最終的な報告があったところです。それまでは報告はありませんでした。","voiceIndex":76,"id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"区としては当然やっていると思っていたわけでしょう。そこら辺は区に言ってもしようがないのだけれども、東京都は随分対応が遅かったのではないかという点は感じます。終わってしまったことなのでしようがないかもしれませんけれども、今後もいろいろなところで絡んでくると思うので、その辺をよく言っていただきたいと思いますが、いかがでしょうか。","respondent":"和田河川下水道課長","answer":"これまで２年半の間報告がなかったものですから、これについては強く抗議をしています。それについては、下水道局は申しわけなかったということで謝罪しています。それから、騒音計、月見橋のところの騒音計につきましては、あそこの工事は実はやっておりました。","voiceIndex":78,"id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"月見橋の件はわかりました。要望もしておいていただきたいと思います。なぎさ会館の駐車場のところを、工事が完成したら、また駐車場に戻るし、今は仮設の駐車場になっていますが、あれも復旧するということがたしか当初の約束だったと思うのですけれども、そうすると、これが遅れてくると、その辺の流れも全部、平成３２年の開始時期には復旧に向けていくということでよろしいのですか。","respondent":"和田河川下水道課長","answer":"なぎさ会館の全ての整備が完了するのは平成３２年の通水開始の後ですので、もう少々時間がかかるです。","voiceIndex":80,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"当初は３０年に終わっていればきれいな形で整備できていたと思うのですけれども、やはり人をこれからお迎えする段階で、ちょっと何かあそこら辺、見てくれが悪いというと表現は良くないかもしれないけれども、今もカバーをしてそれなりにはやってくれているけれども、何か品川区として来てくれる人に見栄えのいいものにしてもらいたいと思うのだけれども。","respondent":"和田河川下水道課長","answer":"委員のご指摘は当然ですので、強く申し入れをしていきたいと考えています。","voiceIndex":82,"id":"exchange-031"}]},{"id":"topic-07","title":"の(7)の平成２７年度 区内一斉防災訓練等実施結果","agenda":"の(7)の平成２７年度 区内一斉防災訓練等実施結果","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"今回ほぼ、１００％ではありませんけれども、かなり参加されて有意義だったというふうに思います。私も参加をして、みんな委員が参加されて、とってもよかったと思うのです。これは継続的にやっていく必要があると思いますから、これからもいろいろやっていただきたいと思いますが、この一斉防災訓練以外で一覧を出していただきました。一斉にも、ここにもやっていないというところはあるのでしょうか。","respondent":"黒崎防災安全担当課長","answer":"ただ年度訓練で計画を避難所ごとにしておりますので、今のところ新たに５カ所につきまして訓練の相談が入ってきております。ですので、合計しますと約１割、７避難所ぐらいがこの訓練に携わっていないというところが今年度については出てきてしまうというふうに受けとめています。","voiceIndex":88,"id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"７避難所、これが今、相談しているということなのですが、この７避難所というのは、今まではどうだったのでしょうか。今までの実施の実績というのはあるところなのでしょうか、ないところなのでしょうか。","respondent":"黒崎防災安全担当課長","answer":"過去ですが、今年度未実施なのですが、過去においてもやっていないというところは、昨年訓練計画をしていたのですが、選挙のため避難所訓練自体がなくなってしまったので、それが理由で１回もやったことがないというところを除きますとございません。","voiceIndex":90,"id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"その際に、では誰が主導権を握るべきなのか、本来は、これは避難所運営でも、地域の避難所なので、地域の方々が中心にということではあるのですが、ただ道筋はつけてあげないとなかなか難しい。その地域の方々のコミュニケーションをとってもらいながら、地域の実情に合わせながらつくり上げてもらうというのが理想だと思うので、その方向についてどういうふうにお考えなのでしょうか。","respondent":"鈴木（誠）防災課長","answer":"それと、そこの町会長、本部長の考え方は、今は単独の避難所でやるよりも地区でやりたいということで、今年はちょっと実施しないというようなお話を個別に情報を伺い、お返事をいただいていますので、会長の考え方も尊重しますが、やはり繰り返し訓練をして。","voiceIndex":92,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"避難所訓練と防災訓練があると思うのです。これはよかったです。そういう本当に実際の姿を皆さまにお見せしたいという意気込みのある学校だったので、そういうふうな、もっと実際どう訓練したらいいのか、学校現場ですから、子どもたちは当然いるわけであって、その都度一緒に解決するという形がやれたら最高だと考えていますので、意見という形にさせていただきたいと思います。非常によかったと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"もし、そういったものが幾つか特徴的なお声がありましたら、今紹介していただきたいですし、あとそれも大いに次年度以降の会議にも出して、みんなで改善点を出していくというのは大事だと思うのですけれども、そこら辺はいかがでしょうか。","respondent":"黒崎防災安全担当課長","answer":"そちらの内容は大体どこも全ての避難所で共通する内容なのですが、先ほどご報告の中で、ちょっとそこまで説明しなかったのですけれども、特に資料１、Ａ３の表ですけれども、例えば、城南第二小学校などは応援物資搬送訓練というものをやっております。","voiceIndex":95,"id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"それとあと、区の職員の動き方をお伺いしましたけれども、自宅を出発して参集ということで、すごいと思うのですが、実際なかなか他区から来られておりますし、震災が起きると電車も止まってしまいますのでなかなか大変だと思うのですが、各避難所の振り分けという点で、例えば少なくとも１人とか２人は割と近隣の方を配置しているとか。","respondent":"鈴木（誠）防災課長","answer":"その指名のときには、各所属で指名の推薦をいただくようにしていますけれども、基本的には区内在住の職員を中心にやっていますので、場合によっては歩いてでも来られる職員がかなりの割合を占めるというような体制で避難所のほうの支援の部隊が本部から行かなくても。","voiceIndex":97,"id":"exchange-037"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうしますと、やはり避難所訓練に参加されていた区民の方から、特に高齢者の方なのですけれども、和式だとやはり高齢者だと大変なので、高齢者が利用しやすい洋式の形にしてくれないかというお声を頂戴したので、私も確かにそのとおりだと思ったので、その洋式への改善、本当に全部替えるとなるとコスト面でも大変だと思うので、今和式のトイレを簡単に洋式にかえるキッドというか。","respondent":"鈴木（誠）防災課長","answer":"１点目の訓練開始時のスピーカーの声が聞き取りにくいですが、これは私が各訓練を実際に拝見して回って気づいたことなのですが、学校によっては学校の校庭につけてある本来の放送設備をお借りできたところは比較的話がよく聞こえたのですけれども。","voiceIndex":99,"id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の質問で、最初の開始のアナウンスというのは防災無線のことを言っているのではないのですか。私はそう思ったのだけれども、防災無線で入らない地域がどうしても出てきています。そういう中で、ラジオを区のほうでやってくれて、皆さま買ったけれども、在庫はなくなっているのか。そこの対応はどうなっているのか、今聞きながら思ったのですけれども、今後の在庫の問題と今後の対応について。","respondent":"鈴木（誠）防災課長","answer":"確実にそれが売れないと、今度は全額公費で負担して買い取らなければいけないということがございまして、現在までのところ、追加の発注はしていないということと、今後も少し防災無線本体のほうがデジタル化とか、今後改修計画がありますので。","voiceIndex":101,"id":"exchange-039"},{"speaker":"つる委員","kind":"質問","question":"当日議会としての訓練をさせていただいて、議会として出席している、これは区議会の話なので該当するかもしれませんが、腕章をつけてそれぞれの議員が住んでいる、所属している町会で避難所の訓練に参加させていただいたという感じなのですが、ここの人数の把握の仕方なのですけれども、こういうのは訓練の中で非常に一番大事な人員が何人いて、何人がどういう状況なのかというところで。","respondent":"黒崎防災安全担当課長","answer":"その実数を得たものですので、委員からご質問のあった各議員の皆様の人数は、申しわけございません、入れておりません。","voiceIndex":103,"id":"exchange-040"},{"speaker":"つる委員","kind":"質問・要望","question":"議会としてこれで２回、具体的には２回やっている中で、基本的には全員が出席という議会側として設定している中で、なかなか残念ながら全員は出ていないという現状もある中で、私が参加したところなんかでも、どちらの立場でいるのかと、ちょっとそういった部分もあって、その辺の、訓練とはいえど、そこに来ている人の把握という形が、特段名簿とかで出欠をとっているという姿もなかったものですから。","respondent":"鈴木（誠）防災課長","answer":"１点目、議会のほうで実施された訓練で、各議員の先生方が避難所にいらっしゃった件ですが、先ほど安全担当課長からご説明しましたように、実際の参加の確認は受付名簿でやっておりますが、実は避難所ごとに訓練項目を話し合っていただくときに、必要人員を算出しまして。","voiceIndex":105,"id":"exchange-041"},{"speaker":"つる委員","kind":"確認","question":"前半のほうは、体制的なことで、議員個人個人、一人ひとりの資質の部分だというところで、後で確認なので、すみません、ご答弁いただきましたけれども、当然議会としては本部で立ち上げの方法、体制とか、また行政側との連携とか、それは当然わかった上で、そういう姿勢はいかがなものかとちょっと思ったものですから、そういった場合で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-042"}]},{"id":"topic-08","title":"行政視察の報告書","agenda":"行政視察の報告書","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"内容はこれでいいのですけれども、立派な視察報告書ですので、ちょっと委員長に相談といいますか、あれなのですけれども、ぜひこれを公開というか、現状はどうなっているのかをお伺いしたいというか、区民の方が自由に見られるように、ぜひインターネットとかホームページ等で自由に閲覧できるようにしたほうが私はいいと思っているのですが、そこら辺に関して現状はどうなっているのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":113,"id":"exchange-043"},{"speaker":"安藤委員","kind":"意見","question":"紙ベースで資料コーナーにあるということかもしれないのですけれども、もっと開かれたという意味では、やはり議会ホームページ等で公開していったほうがいいのではないかという考えを私は持っていますので、それはちょっと、ここでやる場ではないのかもしれませんので意見として述べします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":115,"id":"exchange-044"},{"speaker":"安藤委員","kind":"意見","question":"ご説明の中で、区が１００m2未満では公園用地に買わないという規定があるというお話だったのですが、そこら辺はどういった規定に基づいてそういうふうになっているのか、そこら辺のルールがあれば、もう少し説明をいただければと考えています。","respondent":"寺嶋木密整備推進課長","answer":"それによって、例えば国費であり、区費でありといった財源獲得が複雑になっておりまして、基本的には１００m2未満ですと防災広場、それからその他の事業活用としてなかなか効率的な手法が見込めないということから。","voiceIndex":120,"id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"ちょっともう少しお伺いしたいのですが、つまり、国や都との補助金事業との関係ということなのでしょうか。ちょっと基準という話だったのですけれども、どういう条例なのか、要綱なのか、それとも区の考え方ということなのか、そこら辺をあわせてもう少しお伺いします。","respondent":"寺嶋木密整備推進課長","answer":"数字上の基準という観点でいきますと、東京都の基準を準用しているということがまず数字的な問題です。それから、実態として防災広場として活用できる面積がどの程度が妥当なのかというところですが、これは運用上区のほうで判断してやっているところです。","voiceIndex":122,"id":"exchange-046"},{"speaker":"安藤委員","kind":"確認","question":"ホームページのほうでアップしていると思うのですが、それもすぐ修正になるのでしょうか、そこだけちょっと確認をしたい。ホームページのほうで、これをアップしていると思うのですが、それは修正されるのか。","respondent":"鈴木（誠）防災課長","answer":"区のホームページでは、ＰＤＦのデータを公開しておりますので、そちらのほうも新しいものとリンクを交換しまして、区民の方にご覧いただけるようにしたいと考えております。","voiceIndex":131,"id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"おとといの夜から昨日の朝にかけて久しぶりに積雪が結構あって、地域によってはかなり大変な状況があったという報道がされていますが、前日から予報があったので、やはり一定対策をとることができるのかと思ったのですが、品川区内の被害状況とか、もし区としてつかんでいることがあればお伺いしたいのと、対応とかを、もしとられたことがあるのであれば、教えていただければと思います。","respondent":"鈴木（誠）防災課長","answer":"この週末から月曜にかけての雪の対応ですが、日曜日の夜、午後１１時に道路課のほうの関係で巡回をしたりする体制を敷くために、道路課長と職員２人、それから建設防災協議会のほうで３班のパトロール部隊に待機いただきまして対応したところです。","voiceIndex":134,"id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4160#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":50684,"voices":136}},{"id":"h28-20160119-9","meetingId":"h28-cm01","date":"2016年1月19日","dateIso":"2016-01-19","committee":"文教委員会","time":"午後 １時００分～午後 ４時５４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を77件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区教育大綱の策定","agenda":"品川区教育大綱の策定","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"「大綱の策定について」という１枚ぺらの資料のところの、２番の第３回品川区総合教育会議の(2)のところで、主な意見というので、丸印のところがあるのですけれども、これを主に今回の大綱素案に入れ込んだということなのでしょうか。具体的に、これがどう入って、どう具体策になっていくのかというところなのですけれども、教えてください。","respondent":"品川庶務課長","answer":"本日出しております大綱は、ちょうど第３回の総合教育会議に出された資料と全く同じものとなっておりますので、ここで出ました意見については、現在、まだ大綱のほうには反映されていない状況です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、今、課長が言ったとおり、これから意見を新たにここにまた取り入れた素案になっていくということは、まだもうちょっと意見を聞いていただけるということなのですか。それとも、もうパブコメは終わったわけですけれども、区民からの意見はもうこれで終わるということになってしまうのでしょうか。","respondent":"品川庶務課長","answer":"そうですね。区民からの意見としてはパブリックコメントのほうで現在意見を集約しましたので、またこの委員会の今日の場とか、そういったところの意見を踏まえまして、大体３月ぐらいをめどに大綱のほうを完成させていただきたいというふうに考えているところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"提案","question":"基本はやはりそういうところをきちんと捉えた大綱という位置づけにしていただきたいと思うのと、あと、基本理念のところにコメントを寄せられた方で５番のところに、「基本理念に「平和と人権を尊重し、主権者としての子どもたちを育てる」という趣旨を反映してください。この辺についてどういう状況なのか、ここに何が込められているのか、お伺いしたいと思います。","respondent":"品川庶務課長","answer":"それに合わせて、学校のほうも改築等も進めている部分があります。こういった点につきまして、こういう就学人口の動向だとか、また、国や都の動向だとか、そういったところも踏まえまして、今後、学校のあり方というのを検討していきますというような意味です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"意見をぜひ言わせていただきたいのですけれども、適切なクラスの人数というのはなかなか議論が煮詰まっていないので難しいとは思うのですが、やはりより一人ひとりの子どもたちのことをしっかりと教員がつかんでいくという意味の少人数学級を追求していくと、今後まだ伸びるけれども将来にわたって子どもが減っていくという先行きのところで、多分。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（博）委員","kind":"質問","question":"何が抜けているのかというと、今、梅毒が増えていたり、先進国の中でエイズが日本は唯一増えているとか、大体その辺のことというのは青少年の教育でしっかり、性教育もそうなのですけれども、避妊をするとか、そういう青少年における医学的な、例えば、感染症だとか、性教育だとか、その辺の文言というのはぜひ入れて。","respondent":"村尾教育総合支援センター長","answer":"ただ、エイズ等につきましては、学校では保健体育のほうで授業としては進めているところですので、少しまだ意見のほうはこちらのほうで承らせていただければというふうに思っております。","voiceIndex":12,"id":"exchange-005"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それと、それは教育の一部でやっていますということなのですが、これは教育大綱だから、健康教育というのは非常に大切なのです。これは非行防止だから健康教育の言葉は別にということで全然文章化しないというのは、あまり重要視をしていないというふうに見られてもおかしくないのではないかと思うので、この辺はぜひ再考をお願いしたいと思いますが、いかがでしょうか。非行の定義だけお願いします。","respondent":"村尾教育総合支援センター長","answer":"ただ、今、委員のおっしゃるとおり、性的な部分のエイズ等につきましてはこの部分に載せる内容なのか、また、今後違う形で各学校等で周知をしていくかについては、また検討させていただければというふうに思っております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"浅野委員","kind":"質問・要望","question":"応募が１９件で、意見が７５件ということで、この数が教育委員会として期待をしていたぐらいの件数なのか、それとも、もっとたくさん意見をいただきたかったというような気持ちがあるのかどうかというところは、なかなかこれは難しいかもしれませんけれども、この件数に関しての評価というのでしょうか、それを一つお願いしたいと思います。","respondent":"品川庶務課長","answer":"そういったＩＣＴに関する教育はしっかりと充実させて、こういう便利な機械ですので、当然、しっかりと使っていただいて、社会全体にメリットが出るような形で検討していきたい、このように考えております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問","question":"１つお伺いしたいのですが、８ページのところの「大綱の実現に向けて」というところなのですが、そもそも大綱というのが、区長部局のほうが教育委員会に云々という、そういった関係があったわけですが、これまでも教育委員会のほうは区長部局と連携・協力を図りながらというようなことをさまざまな委員会等の場面でお話しされていたと思うのですが、これまでもやってきたのにもかかわらず。","respondent":"品川庶務課長","answer":"これをさらに継続していくというような意味合いで、ここの８ページの図のほうは書いているです。","voiceIndex":20,"id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"そこで具体的に、こういうところがあったので連携がなかなか進んでいない部分もあったのでしょうかと言うつもりはないのですけれども、そうすると、別に今までとあまり変わりないですよということになるわけですよね。そうすることによってより密接な連携がとれるという部分も見えてくると思うのですけれども、具体的に新しい体制がないとすれば、その辺についてのお考えだけ伺いたい。","respondent":"品川庶務課長","answer":"今回の件というのは、結局、法律でこういうふうにやっていきなさいというような明記がされたということで、考え方としては、従来、品川区が先にやっていたことを、要するに、区長部局と教育委員会の連携、これは十分連携をしながら進めていっていたというところが。","voiceIndex":22,"id":"exchange-009"},{"speaker":"伊藤副委員長","kind":"質問","question":"この間の文教委員会でも指摘しましたけれども、あえてやっていることをどうして、多額の税金を使って大綱をまとめたのでしょうから、確かに法で決まったことなのかもしれないけれども、計画だけがあって具体的な政策のすり合わせがないとするならば、そういう素直な感想を持つわけです、議会としては。","respondent":"品川庶務課長","answer":"先ほどの答弁は、あくまでも連携する形というような形での説明でありまして、それにあわせて政策をどうしていくかという点につきましては、５ページから７ページの部分での表記として、今後、コミュニティ・スクールの展開、それから。","voiceIndex":24,"id":"exchange-010"},{"speaker":"伊藤副委員長","kind":"質問","question":"文化芸術もあるわけです。大綱でしょう。それを具体的に展開していかないことには、やはり議会としてはなかなか納得しにくい部分もあると思いますので、お伺いしたいのは、より具体的な政策の展開のところと、それから、庁舎内の会議体の設置等々について、これからこれをどのように具体化していくのかということをお聞かせください。","respondent":"品川庶務課長","answer":"何々会議とか、具体的な名前は出せませんけれども、この政策を進めていくにあたっては、いろいろな課で連携をしながら、そこの会議体をつくりつつ進めていきたいというふうに考えてあります。","voiceIndex":26,"id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"最初のアンケート、これはいつからとられているものなのか教えてください。それで、学校運営の改善につなげるというのが目的には書いてあるのですけれども、今時点で改善点は何があるのかを伺いたいと思います。","respondent":"野呂瀬学務課長","answer":"ですから、いろいろ複数回答になるのですけれども、傾向としては、学校選択をされる方というのは毎年同じ状況だということで、どういうふうに改善をしていくかということですけれども、それは、こういう回答がありましたということは校長会等でもお知らせしますし、また。","voiceIndex":32,"id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"意見","question":"このアンケートだけに限らず、いろいろなアンケートがある中で、学校側の運営の改善にということなのですけれども、こうやって調査の目的を今後の学校運営の改善につなげていきますという形でとられているわけですので、例えば、どんな改善がこういうアンケートでされているのかというのを、例で挙げていただけると。","respondent":"野呂瀬学務課長","answer":"それよりも、教育の内容とか、それぞれの学校独自の特色を活かした内容、学校選択をする前に各学校でやっている学校説明会で学校のやり方だとか運営の仕方だとかに共感を持ったとか、そういうところで学校の取組みに興味を持っているというのが一番多いというところです。","voiceIndex":34,"id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"確認","question":"それで、もう一枚のほうの抽選校の結果についてなのですけれども、今、いろいろ説明していただいたのですが、待機されている児童というのは、小学校が１月、中学校は２月に何も来なければ、先ほど言った就学指定通知の学校に通うことになるということですよね。ちょっと確認と、それと、就学指定通知の学校に通うことになってしまう、要は、希望した学校に入れない子どもたちというのは、毎年出るものなのか。","respondent":"野呂瀬学務課長","answer":"それと、冒頭申し上げましたけれども、学校選択というのはあくまでも学区域のお子様を第一優先で入れて、学区の中で受入れ予定数をオーバーしたときには抽選になります。","voiceIndex":36,"id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"入学する際に説明とか、学校選択制そもそものルールが学区内の子どもを優先というのは、それで抽選にもなっていくということはわかるのですけれども、入れなかったという思いというのは、子どもにとってはどんなふうに、希望したところに入れない、でもそういうルールだからねということになってくるのだと思うのですけれども、でも、やはり幼い子どもたちにとって。","respondent":"野呂瀬学務課長","answer":"そういうのから見ると、やはり当初はなかなか希望のところへ入れなかった、だけれども、学校に行ったら、その中で子どもたちもその学校で学ぶうちに学校のよさとかになっていくというのはあるのではないかと考えているところです。","voiceIndex":38,"id":"exchange-015"},{"speaker":"鈴木（博）委員","kind":"質問","question":"人数以上、オーバー枠でしょう、これ。それで、ただし、第三日野小学校なんかは、９０名のところ、無抽選で最初から１３５名、学区内で無条件で入れるということは、要するに、何回お話を聞いてもよくわからないのですけれども、何で学区の人が受入れの予定数より多いのでしょうか。同じ質問かもしれないのですけれども、納得できるご回答をお願いしたいのです。","respondent":"野呂瀬学務課長","answer":"ただ、御殿山小学校も昨年は最終的には、ここの９６名というのは学校選択を希望していない人ですので、その中でもちろんそのまま御殿山小学校を希望する人もいれば、逆に言えば、私立等に行って入学辞退をする方、または、９６名の中から数人でしょうけれども。","voiceIndex":40,"id":"exchange-016"},{"speaker":"鈴木（博）委員","kind":"質問","question":"最初からそもそも数がオーバーしているというのは、減るからいいのですよというのは、事前の話ではないような気がするのですけれども、それで、先ほど学務課長のほうから、毎年同じような傾向ですというお話があったのですけれども、毎年同じだったらどうして変えるように変更するとかというような検討というものはされないのでしょうか。その辺のご回答をお願いしたいのですが。","respondent":"野呂瀬学務課長","answer":"この表自体がわかりにくいというところで、結構いろいろ毎年毎年変えていったところはあるのですけれども、抽選に対しての結果ですので、無抽選で実際にはその学区にいる人で学校選択を希望していない人みたいな人というのが一番正確なのかもしれないのですけれども。","voiceIndex":42,"id":"exchange-017"},{"speaker":"鈴木（博）委員","kind":"質問","question":"改めて質問します。大体今、ほとんど中学受験というのは２月１日から３日だから、７日くらいまでいけば結果が出るので、７日ぐらいになるとはっきり、先ほど学務課長がおっしゃった、抜ける抜けないというのがほとんど明確になってくるわけだから、１週間ずらせば精度が大分違うと思うのですけれども、それはいかがですか。","respondent":"野呂瀬学務課長","answer":"それと、あとは、転出予定だとか、そういうのが２月ぐらいでしたら、３月までに転出予定だとかいう情報も固まりますので、そういうのも含めて、一応２月末を最終期限として定めておりますということで、決めさせていただいたものです。","voiceIndex":44,"id":"exchange-018"},{"speaker":"浅野委員","kind":"質問・要望","question":"１点ここだけ、だめだったら地元というような考え方なのか。そういうアンケートというのは多分とっていないのかもしれませんけれども、何か情報があれば教えていただきたいというのが１つ目です。そうした場合に、もしかすると、同じ学校に入れなくなる、そういう形勢というのでしょうか、可能性があると知って学校選択制を今回やってみようとする家庭というのはおられるのかどうか。","respondent":"野呂瀬学務課長","answer":"例えば、このアンケートにどれぐらい検討しましたかといったとしても、それは１点ここの学校がという方もいらっしゃるでしょうし、やはり教育活動に共感されている親御さんとしたら、似たような学校はここかここかみたいなところを選ぶ方もいらっしゃると思います。","voiceIndex":52,"id":"exchange-019"},{"speaker":"浅野委員","kind":"意見","question":"周知をされているということですけれども、やはり現実はなかなか厳しいものがあって、お兄さんを入れてから、次の子どものときは入れないかもしれないと言われたというふうに相談を受けたこともありますので、そこのところは、やはり親御さんにしてみれば、希望を持って学校選択制を使っているというところの中では。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"8)の「施設一体型小中一貫校の魅力」が５.５％、これをどう評価しているのかなと思うのと、中学校のところで一貫校を選んだ人が２.９％いて、これはどういう思いで選んでいるのかと、この辺も疑問を感じてしまったのですが、この辺、どう思っていらっしゃるのか教えてほしいのと、あと、抽選校のところなのですけれども、小学校は１月末、中学校は２月末のところで決定していくというのですが。","respondent":"野呂瀬学務課長","answer":"他区からというところですけれども、あくまでも学校選択というのは、これもルールの一つなのですけれども、前年度の１０月中の１カ月間に学校の選択をしていただくということで、それで受入れ数をオーバーしたときは抽選を行いますということですので。","voiceIndex":55,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"確認","question":"結果発表後はその学区域、あと、抽選に漏れた方も全て自分の学区域だったら吸収ができるということで確認、よろしいでしょうか。","respondent":"野呂瀬学務課長","answer":"先ほどおっしゃったとおり、そのとおりです。学区域に戻るというのも勘案して抽選を行っておりますので、抽選に漏れたら基本的には学区の学校に戻っていくというのがルールになっております。","voiceIndex":57,"id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"確認","question":"確認ですが、学区が決まっているわけですけれども、この学区というのはいつごろ決まったあれですか。もしわからなかったら、ここ二、三年でなければ。","respondent":"野呂瀬学務課長","answer":"学区自体は相当前、昭和２０年、昭和３０年、ほとんどのところがそうですけれども、学区域というのは決めなければいけないとなっていまして、その学区域に通学してくださいということで、学校選択をする前までは品川区も学区域が決まっていまして、あなたはどこどこ小学校です。","voiceIndex":59,"id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"質問","question":"最終的には入っている方も結構いるのかもしれませんけれども、そういうのを考えると、先ほどの教育大綱のところで、「就学人口の動向を見据え、校舎改築や学校配置のあり方について検討します」という文言があるのですが、先ほど学校の統廃合等をおっしゃった委員がいらっしゃいましたけれども、そういうことは置いておいて、学区とかそういうことも含めて。","respondent":"野呂瀬学務課長","answer":"それで２点目の質問になるのですけれども、今後どういうふうにするのかというご質問だと思うのですが、やはり委員おっしゃったとおり、これからの教育のあり方とか、そういうのを検討する協議というのは必要だと考えていますので、就学人口の増加だとか、義務教育学校の設置等。","voiceIndex":61,"id":"exchange-024"},{"speaker":"高橋（し）委員","kind":"確認","question":"例えば、城南小学校も改築するときに、おそらくクラスを増やさなければいけないのだと思うのです。これから改築も出てくるし、そういうことを含めると、今課長がおっしゃったような形で、そういった検討の場といいますか、そういうのを設置する必要があるのだと思うのですけれども、それは課長のお話ではないかもしれませんが、それだけ確認です。どなたかちょっとわからないですけれども。","respondent":"品川庶務課長","answer":"やはり学区域の見直しという点につきましても、就学人口の増に対して、対応する措置の一つとして考えられる選択肢は何かなというふうには思っております。今後、就学人口の動向等も調べて、どのようにするかという中での一つの選択肢という中には入っていると。","voiceIndex":63,"id":"exchange-025"},{"speaker":"伊藤副委員長","kind":"質問","question":"そうすると、品川区が学校選択をしなければ抽選する必要はなかったわけでしょう、理論的に。それが非常に矛盾を感じるのです。議会もそれに賛同した。できないこと、いいのだけれども、教員の追加配置をしてクラスを増やしていくなり、そこまですることは品川区が選択制を導入した責任ではないのですかと思うのがいつもついて回るのだけれども、その辺のお考えはいかがでしょうか。","respondent":"野呂瀬学務課長","answer":"今、副委員長がおっしゃったとおり、教員の配置だとか、学校の規模だとか、いろいろそういうのも今後勘案して、先ほど申しましたとおり、今後、品川区の教育のあり方を検討する中で協議をしていくのは必要と考えているところです。","voiceIndex":65,"id":"exchange-026"},{"speaker":"伊藤副委員長","kind":"質問","question":"品川区が前教育長のもとに相当な教育改革をやってきたことはすばらしいことだと思っていますし、進めるべきだと思います。そういうことをどこかで集約して、もう一度抽選がないように再検討する、調整をするなり、検討会を立ち上げていくなりするべきではないでしょうかと思うのですが、考え方をお聞かせください。すぐにできる、できないは言えないでしょうから、考え方だけお聞かせください。","respondent":"本城教育次長","answer":"一番基盤となるのは、１つは、就学人口の動向でありましたり、そういったことが一番ベースになると思いますので、まずはそれをしっかり押さえて、その上であるべき選択制のあり方がどういうものかということをしっかり常に検証して、その中では。","voiceIndex":67,"id":"exchange-027"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"そういうふうなことはやはりどこかで見直しをして、義務教育であるためにはできるだけ全ての児童・生徒がご自分の、繰り返し言うけれども、学校選択制を導入したのは品川区のほうですから、これは品川区の責任でやっていただいた上で、希望した子どもたち、移動したりとか、全員がそれぞれの小学校、中学校の学区に入れますように、柔軟な調整をお願いしたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-028"}]},{"id":"topic-02","title":"平成２８年度品川区立学校における土曜日の授業の実施","agenda":"平成２８年度品川区立学校における土曜日の授業の実施","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"原因は「月２回の土曜日授業」ということになります。学校５日制のリズムが崩れ、子どもたちも教職員も疲労が蓄積しています。中学校では、土曜日授業のためゆとりを持った部活動が難しくなりました。小学校では、金曜日になると必ず「明日、学校あるの？」と子どもたちが聞きます。品川区の授業というのは、ほかと比べると、授業時間が多いのでしょうか。その辺も教えてください。","respondent":"渋谷指導課長","answer":"パブリックコメントを読ませていただきましたが、そのほか、私ども、校長会等のやりとりの中で、校長先生方もＰＴＡのご意見をお聞きして、土曜日授業については第１・第３、２回が適切であるという意見が圧倒的な多数だというふうに認識しています。","voiceIndex":74,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面で、ぜひこういった面が一部の人の意見ではないと私は受けとめているので、現場の教員の方たちの意見もしっかりと聞いて、土曜日授業はどんなものかというのをぜひ総合的に勘案していただきたいと思いますが、いかがでしょうか。","respondent":"渋谷指導課長","answer":"ただ、今後、品川区もコミュニティ・スクールだとか、さまざまな取組みをして、地域の行事なんかにもどんどん出ていこうなんていうことを考えておりますので、一律授業日にするのがいいのかどうか等々については。","voiceIndex":76,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いろいろな方のご意見をぜひ聞いてほしいのと、やはり地域とのつながりも大事だし、先ほど大綱の中にも、家庭・地域・学校の連携、体力をつくっていく意味でも豊かな経験を、学校だけではなくて、その他のところでの豊かな経験、文化芸術にも触れてほしいといった意味で、総合的に考えていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-031"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ただし、お聞きしたいのですけれども、授業がないほかの土曜日、要するに、月２回ということは月２回は授業がないわけだから、そのときに実際小学生の子どもたちがどういう生活をしているかというようなアンケートとか調査とかは教育委員会のほうでされているのでしょうか。","respondent":"渋谷指導課長","answer":"第２・第４土曜日に具体的にどういう生活をしているかというピンポイントに絞ったアンケート調査はしておりませんが、休みの日にどんな過ごし方をしているのか等々というのは、全児童・生徒アンケート等で把握をしているところではあります。","voiceIndex":79,"id":"exchange-032"},{"speaker":"浅野委員","kind":"質問","question":"そういう意味では、子どもの体力づくりとか、コミュニケーションとか、そういうことを考えると、土曜日に授業があったほうが、もしかしたらコミュニケーションをもっととれるのかと思いますし、メリットもかなりあるのではないかというふうに思っている次第なのですが、今の小学生の休み時間の使い方、例えば、放課後でもいいのですけれども、放課後はよく缶蹴りなんかをやっていた記憶があるのですが。","respondent":"村尾教育総合支援センター長","answer":"休み時間に学年同士で外に出て、一緒に大縄をしようとかという運動的なもの、特に今、品川区ではスポーツトライアルという形で、休み時間等をうまく活用して、体力づくりというのを区全体で取り組んでいるところがあります。","voiceIndex":86,"id":"exchange-033"},{"speaker":"浅野委員","kind":"意見","question":"スポーツと学業ということで、子どもたちに一番必要な事柄が満遍なく行われているというふうに認識をしました。これからも続けていっていただければと思いますので、よろしくお願いします。","respondent":"渋谷指導課長","answer":"ふだんの勉強の中身についてどんなことをやっているのかということについても、学校の宿題を休みの日にやっているという子が６９％で、ふだんの日常の学習のあるときには８１.５％の子が学校の宿題をやっているということに比べると。","voiceIndex":88,"id":"exchange-034"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"ただ、学校がないときに何をしているのかわからない。先ほど出てきたコミュニティ・スクールだとか、非常にいいことだと思うので、なるべく学校の授業がない土曜日に、どのように子どもが豊かで人間性があふれるような学びができるかということに関しては、ある程度教育委員会のほうでも配慮していただければいいのではないかということを考えているのですけれども、いかがでしょうか。","respondent":"伊崎子ども育成課長","answer":"活動としましては、すまいるスクールは児童健全育成の場であるとともに、学習支援の場でもありますので、学習活動の支援、宿題を見たり、勉強会ということで学校の補習をしたり、それから、教科だけではなく、地域のいろいろな方々のご協力を得て、例えば。","voiceIndex":90,"id":"exchange-035"},{"speaker":"鈴木（博）委員","kind":"質問","question":"すまいるスクールというのは非常にすばらしい活動をされているということでお聞きして、少し安心したのですけれども、一応土曜日も、学校がある日はむしろ枠があるので、子どもはしっかり勉強するし、学校の先生が見てくれているからいいと思うのですが、ないときもすまいるスクールを中心にして、子どもがしっかりとその部分を育まれて、学べるような環境をつくっていただいたほうがいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-036"}]},{"id":"topic-03","title":"御殿山小学校西側敷地の事業計画案","agenda":"御殿山小学校西側敷地の事業計画案","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"今、２階の平面図を拝見させていただいたのですけれども、ベビーカー置場というのがあって、授乳室があるということは、ここまで結局、ベビーカーで入ってこられるということですか。","respondent":"木村品川図書館長","answer":"あくまでも仮ですが、そのようにこの図では想定をしています。","voiceIndex":97,"id":"exchange-037"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、図書館にベビーカーが入ってきて、授乳コーナーもあるということは、赤ちゃん連れのご両親が来るということだと、子どもが泣いてうるさいとか、当然そういうクレームとか、図書館というのは静穏なところですから、話が出てくると思うのですが、それに対しては何か対策とかというのはないのですか。","respondent":"木村品川図書館長","answer":"こちらに関しましては、本当は委員おっしゃるとおり、今の図書館でも実際に起こっている問題であります。ご意見を賜りまして、これから中身につきましては検討してまいりたいというふうに考えています。","voiceIndex":99,"id":"exchange-038"},{"speaker":"浅野委員","kind":"質問","question":"高齢者の方の施設が隣接するということで、３ページ、１階平面図案というのがあるのですが、左側が北側になるのでしょうか。図面の左側が北側になるのか。","respondent":"木村品川図書館長","answer":"そうです。","voiceIndex":101,"id":"exchange-039"},{"speaker":"浅野委員","kind":"質問","question":"その上側というのでしょうか、東側がここですね。","respondent":"木村品川図書館長","answer":"今後、実際にここの建物の管理組合みたいなものをつくりまして、老健施設と図書館と、このビルを一体的に管理するというところの中で、実際にここの出入口に関する児童・生徒の安全面に関しまして、どのように配慮していくかというところを今後検討して。","voiceIndex":103,"id":"exchange-040"},{"speaker":"浅野委員","kind":"質問","question":"ぜひともお願いします。ただ、ほとんどの方が、例えば、寝たきりでご迷惑をおかけするようなことがあってはいけないと思いますけれども、多少話はできるとか、そういうような方がおられるのであれば、そういうことも考えていただければ、高齢者の方も元気になるし、子どもたちもご高齢の方というのはということで、いい勉強にもなるかと思いますが、いかがでしょうか。","respondent":"木村品川図書館長","answer":"一般車の出入りにつきましては、先ほどと同様に、注意喚起の方法を含めまして、しっかり検討して対応していきたいと、今の段階ではそのように、そこまでしかお答えできませんが、考えてまいりたいと思います。","voiceIndex":105,"id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つは、区立図書館のところが２階で１,５７５.３３m2ということで、今ある図書館と比べて、どのくらいの規模の図書館なのかということと、特に特徴はなく普通の図書館なのか、イメージを聞かせていただきたいのが１つです。品川区立ですけれども、区立であって、運営がどうなるのか教えてください。","respondent":"木村品川図書館長","answer":"大きさですけれども、ちょうど見合うような大きさというのが、今の大崎図書館の２割増しぐらいでそのまま移転しますので、一番近いというと、今の大崎図書館の１階、２階、地下書庫の部分が全て１フロアという形で、大きさとしてはそこが一番近いかなです。","voiceIndex":107,"id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最初のＡ４の説明書きに「区立図書館の移転整備により」と書いてあるので、ここに大崎という名前がないので、私たちは今、大崎図書館の地域の皆様は、とにかく現地で存続をしてほしい。ここには本当に図書館を充実してほしいという願いがあるので、移転でなくて、ここの地域に必要な文化財として図書館を建設するといった意味で、充実をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-043"}]},{"id":"topic-04","title":"平成２８年度すまいるスクール利用料の減免等","agenda":"平成２８年度すまいるスクール利用料の減免等","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"減額と免除が何人ぐらいになるのか人数、またはパーセントを教えていただきたいと思います。","respondent":"伊崎子ども育成課長","answer":"減額ですが、全体から免除対象を引いた残りの方の中から減額ということになりますので、１４.７％程度の方が対象となると考えておりまして、合わせて４０％程度がこちらの減免の対象となると考えております。","voiceIndex":115,"id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、２人以上いるときに、最年長である児童１名を除くその他の児童を対象に半額になるということなのですけれども、３人目というのはどうなのか。それで、５割というのは何を根拠に行ったのか、伺いたいと思います。","respondent":"伊崎子ども育成課長","answer":"ちなみに学童保育料としていただいていたときも同じ２人目以上の兄弟が、これは利用している場合だったのですけれども、５割減とさせていただいておりました。","voiceIndex":117,"id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"有料になるというところに関しても反対はしてきたわけですけれども、それが２人目は半額で、３人目も、これはもっと減額してもいいのではないかと思うのです。そうではなくした、区の判断で決めてきたということですので、ぜひ３人目をさらに下げる、もしくは無料にしていっていただきたいと思うのですけれども、その辺の検討等はされたのか、今後利用の中でそういうのはあるのか、伺いたいと思います。","respondent":"伊崎子ども育成課長","answer":"このような考え方から、２人目以降は半額ということで今回は決定したものでございまして、３人目以降についての減額率を変えるということは、現在のところは考えておりません。","voiceIndex":119,"id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ考えていただきたいと思うのですけれども、すまいるスクールの利用料については、有料化になるというところは、一定の負担をしてもらうというときには、保護者に用紙が配られて、こういう金額の変更がありますということがお知らせされたと思うのですけれども、保護者に対しての説明は、こういった紙ベースの説明と、あと、遡ってですけれども。","respondent":"伊崎子ども育成課長","answer":"新１年生につきましては、昨年の秋の学校説明会のときに紙ベースの説明書を渡していただきまして、説明会は１月末から２月にかけて、これから通知を発送しまして、説明会を行いたいと考えています。","voiceIndex":121,"id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問","question":"説明会の際に、説明会後でもいいのですが、保護者の方からの声なんかはどのように聞かれているのか、把握されているのかというところをお伺いしたいのです。私のところには、やはり３,０００円という驚きの声が……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"質問","question":"なので、そういった声があれば伺いたいのと、やはりこれだけ、午後６時までが３,０００円で、午後７時までが４,０００円という利用料にしたわけですけれども、そのときの区の説明も、何でこの金額にしたのかというときもいろいろ比較というか、これを根拠にということが挙げられたのですけれども、その根拠も今のすまいるスクールとは比較にならない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-049"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、先ほど言った説明会では子どもの声と、あと、私たちのところには高すぎるという声が届いているのですけれども、今後、そういった声があれば検討はしていくことになっていくのかを伺いたいと思います。","respondent":"伊崎子ども育成課長","answer":"説明会のときには、まだ減額、免除が決まっておりませんでしたのでご説明ができませんでしたが、今回このような形で減額対象、免除対象を定めて、なるべく使えないという方が出ないような配慮を行うということで、進めてまいりたいと考えています。","voiceIndex":127,"id":"exchange-050"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これから進んでいくことですので、保護者の皆様の声を聞いていただいて、それから、３人目のところの検討なんかも、いろいろ再検討をしていきながら進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-051"},{"speaker":"浅野委員","kind":"質問・要望","question":"そのような中で教えていただきたいのが、当初予定していた歳入があるかと思います。今回、このような形で減免制度をとった場合に、歳入がどのくらいになるのかという、お金のことで申しわけないのですけれども、どのぐらい減ってしまうのかということについて、大まかで結構ですので、教えていただければと思います。","respondent":"伊崎子ども育成課長","answer":"詳細につきましては、来年度予算になりますので、大まかな数字でお答えいたしますと、こちらの当初の算定時には、約６,０００万円ほどの歳入を見込んでおりましたが、この減額をかけたところによりまして、２,０００万円ほど減少すると見込んでおります。","voiceIndex":130,"id":"exchange-052"},{"speaker":"浅野委員","kind":"質問・要望","question":"ぜひともそういう意味では、場合によってはさらなる充実も含めまして、これからの発展とか、計画なども立てていっていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"確認","question":"細かいことで申しわけないのですけれども、平成２７年度まではすまいるスクールの利用料は年度当初に一遍に納めていただいたという認識で、平成２８年度からは銀行の引き落としで毎月利用に応じて、そういう引き落としの体制だということの確認なのですけれども。","respondent":"伊崎子ども育成課長","answer":"委員のご指摘のとおりです。現在は現金で年度当初にいただいておりますが、今後は、３,０００円と４,０００円につきましては月ごとの引き落としで、午後５時までの２５０円につきましては半期ごとの引き落としと考えております。","voiceIndex":133,"id":"exchange-054"},{"speaker":"高橋（し）委員","kind":"質問","question":"保育園のご利用とか、いろいろあって大変だと思うのですけれども、そういうような形で、事務作業について、まず委託のほうとどういう打ち合わせをしているのかということと、それで、今までだったら、ある程度年度初めに納めるのでいいのですけれども、今回からは額が、今お話があったように、負担になる方もたくさんいらっしゃるということで、気がついたらたまっていて。","respondent":"伊崎子ども育成課長","answer":"利用料の滞納についてのご質問かと思いますが、滞納につきましては、口座引き落としが不能であった場合には、翌月にもう一度引き落としをかけるということをやりまして、それでも引き落としができない方については督促状をお送りして。","voiceIndex":135,"id":"exchange-055"},{"speaker":"高橋（し）委員","kind":"意見","question":"平成２７年度で変わって、ご負担いただくということですので、ご利用する方のお支払いにいろいろな問題が生じないように、今までのやり方と違って負担の額も増えますので、その辺をよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":137,"id":"exchange-056"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただきたいのですけれども、３人目も半額ということで、３人目がいる率というのがわかれば教えていただきたいと思うのと、あと、できる規定で申請が必要ということで、申請がなかなか煩雑にならないようにしていただきたいという思いがあるので、申請についてはどういうふうにしていくのかというのを教えていただければと思います。","respondent":"伊崎子ども育成課長","answer":"申請の書式につきましては、今、いろいろ検討はしていますが、申込書と延長利用とは別々の形でしまして、減額について丸をつけるような形にしたい。申込様式の中での、該当箇所に丸をつけるような形で、なるべく手を煩わせないような形でとは考えております。","voiceIndex":138,"id":"exchange-057"},{"speaker":"大倉委員","kind":"質問","question":"４人いる世帯が７世帯ということは、２８人ということでいいですか。","respondent":"伊崎子ども育成課長","answer":"そのとおりです。","voiceIndex":140,"id":"exchange-058"},{"speaker":"伊藤副委員長","kind":"質問","question":"１つだけ。先ほど、この料金は高いという話があったのですけれども、前回の条例審議の中で、すまいるスクールに関しては、総額の事業費が１１億１,４００万円という説明がありました。１人当たり平均これだけお金がかかっていますよと、出てくるわけですよね。そのうちにこれだけの金額を今回使わせていただきますというようなことになれば、相当理解が進むと思うのですが、いかがでしょうか。","respondent":"伊崎子ども育成課長","answer":"委員ご指摘のとおりでございまして、保護者会のときにも、そういった総経費の中での保護者の方のご負担ということも説明しております。","voiceIndex":142,"id":"exchange-059"},{"speaker":"伊藤副委員長","kind":"質問","question":"その極めて一部分を保育料なり利用料としていただいておりますということについては、いろいろな形でＰＲし続けることによって、例えば、すまいるスクールの利用だって、もしかしたら４月以降出てくるかもしれません。そのときになって、今回のような騒ぎにならない可能性も出てくるわけではないですか。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"減っていて、やっていけない状況ではないし、十分やっていける財源があるにもかかわらず、かかっていなかったことに不満はどこから出ていたのですか。これが２点目です。せっかくの免除と減額なので、十分本当に活用していただきたいと思うところにおいて、やはり漏れがないための努力を十分していただきたいのですけれども、どのようなことを考えておられているのか教えてください。","respondent":"伊崎子ども育成課長","answer":"サービスとして行います延長にかかる部分のご利用については、すまいるスクールの開始時間からのご利用の時間帯も含めまして、一定のサービスという側面から考えていただき、減免という形で、それぞれの能力に応じたご負担をいただこうと思っているところです。","voiceIndex":145,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"１点目の最初のところなのですが、コスト論コスト論とよく出されています。応能負担という言葉も出ています。これは区自体の考えですか。区民の側から声がいっぱい出ているということですか。いただいている声なのでしょうか。その点だけ明らかにしてください。","respondent":"伊崎子ども育成課長","answer":"これは一定、子どもの未来をつくっていくという意味では必要な負担と考えておりますが、そうはいっても、やはりこれは利用していない方を含めての税金で運営されているわけですので、そういったところを勘案いたしまして、区として判断したものです。","voiceIndex":149,"id":"exchange-062"}]},{"id":"topic-05","title":"子ども・子育て計画の一部改訂","agenda":"子ども・子育て計画の一部改訂","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"１つだけお聞きしたいのですけれども、今の課長のご説明だと、１号認定と２号認定で平成３０年度はプラス２７人になると言っていたと思うのですけれども、これを見てみると、平成２８年度から１号認定と２号認定はプラスになっているように見えるのですけれども、これはいかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"委員ご指摘のとおり、プラスマイナスの差は確かに平成２８年度から改善できているという状況です。","voiceIndex":156,"id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問","question":"今日お示しいただいた資料は一部改訂ということなのですけれども、説明の中身からすると、量の見込みと確保方策のところの数字の変化が主であるなと思ったのですが、ほかの部分はそんなに変わりがないという捉え方で、ここのところだけを注目すればいいのでしょうか。その点を教えてください。","respondent":"伊崎子ども育成課長","answer":"先ほどお話しいたしましたが、ほかの部分についても数字は変わっておりますので、後ほどまた改めて全体を報告します。","voiceIndex":158,"id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問","question":"主に３ページのところで見ると、平成３０年度に入ると、大まかに言って、待機児は解消されるというさっきのご説明だったのですけれども、その辺というのは、前の計画と比較すると、量の見込みというのは人口の推移で変わってきますよね。確保の方策のところも、具体的にこの後の長い横の表を見るとわかるのでしょうか。確保方策がどう構えられていて解消するのか、そこのところを教えてください。","respondent":"今井待機児童対策担当課長","answer":"ですので、こちらのほうを、以前の計画につきましては、本会議での答弁のとおり、平成２８年度末というふうなお話をしておりましたが、これが人口の推計に伴いまして、平成３０年度末、平成３０年度中に解消していきたいというふうに考えております。","voiceIndex":160,"id":"exchange-065"},{"speaker":"浅野委員","kind":"質問","question":"数字のお話がなかなかわからない感じですけれども、今回、品川区全域が一つの区域として設定をされているということで、品川区の全体像だと思いますが、前にもいろいろと区域ごとに見るとどうなのかという質問をさせていただきましたけれども、例えば、このような見方で資料をつくられる予定とか、そういうのはあるのかどうかお聞きします。","respondent":"今井待機児童対策担当課長","answer":"ただし、開設につきましては、やはり先ほどの人口動向も踏まえまして、適切な場所に開設できるように、逆に言うと、入園の申込み、それを踏まえながら開設のエリアについては検討をさらに進めていきたいと考えています。","voiceIndex":162,"id":"exchange-066"}]},{"id":"topic-06","title":"都市公園内における認可保育園の開設","agenda":"都市公園内における認可保育園の開設","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"整備・運営ということで、簡易型プロポーザル方式で公募型で事業者を決めていくということなのですが、私たちは、児童福祉施設、大事な保育園のところをぜひ公設公営で運営してほしいということを常々主張しているわけですけれども、なぜ公設公営で考えなかったのか、そこのところを１点、お伺いいたします。","respondent":"今井待機児童対策担当課長","answer":"品川区は、ご案内のとおり、平成２２年度から民間の事業者による保育園の開設に積極的に取り組んでまいりました。","voiceIndex":168,"id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"介護のところもいろいろ問題が起こっているので、ぜひここの、民間でできるところは民間で、コストの問題も民営化することによってさまざま工夫がされるという答弁だけでは納得いかない部分があるので、ぜひ考えを改めていただきたいと考えていますが、いかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"それは確認制度という中で、条例を通していただきました運営基準の条例、これは新制度で各自治体がそれぞれの施設、子ども・子育て支援新制度の対象内施設がどのように運営されているか、これは区も責任を持って見なさいという制度でございまして、今。","voiceIndex":170,"id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大事なお子さんたちの命を守る、本当に適正に行われていくのは当然で当たり前なのですけれども、それが当たり前にもかかわらず、世間ではいろいろなことが起こっているというところにおいて、やはり国が進めている規制緩和が大きく影響しているというところにおいては、私はぜひ区の確認の役割を十分果たしていただきたいのと、その中で働く職員の方々の労働環境、賃金も含めてですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":172,"id":"exchange-069"},{"speaker":"浅野委員","kind":"質問","question":"西大井広場公園に続いて２つ目ということで、開設をされるということで伺いました。今後の保育の需要なども考えながら検討されると思うのですけれども、そこら辺の今後の見通し、めど、場所のあるなしというのも要素としては入ってくると思うのですが、お考えがあれば教えてください。","respondent":"今井待機児童対策担当課長","answer":"なので、やはりこのような広場を活用できるエリアということもありますし、今、委員のご質問がありました、国の都市公園法の改正にも広場を３０％までの活用ですとか、公園近隣の住宅地への景観の配慮ですとか、さまざまな条件もついておりますので、その条件を十分踏まえながら。","voiceIndex":173,"id":"exchange-070"},{"speaker":"伊藤副委員長","kind":"確認","question":"当然、この保育園では延長、夜間保育をやるのでしょうから、そうすると、門の取扱いについての対応とか、それから、保育園を通って公園の中に入らないようにするという対応も必要ですよね。そういうことは担当課で調整をとっていただけるのでしょうかという確認をお願いします。","respondent":"今井待機児童対策担当課長","answer":"開設が平成３０年を予定しておりますので、細かい点については、また公園課、管理者と調整していきたいと考えていますが、今、委員ご指摘のとおり、やはりここは逆に、キャンプ場とかテニスとか野球とかで夜間も使っていらっしゃるエリアですので。","voiceIndex":176,"id":"exchange-071"}]},{"id":"topic-07","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"２点お伺いしたいのですけれども、まず１つなのですが、３ページ目のコミュニティ・スクールのところなのですけれども、これ、子ども未来部長はご覧になったと思うのですけれども、去年行政視察に行ったときに、下関市のコミュニティ・スクールを見学させていただいて、そのときに学校運営協議会と学校応援団というのをつくっているというお話を聞いたので、かなりよく理解できて。","respondent":"渋谷指導課長","answer":"国の中身のものと差別化するということと、それから、品川区の場合は、校区外部評価委員会という、地域の方が入って学校を支える仕組みができているので、そこをうまく移行させていくというようなことで、かなり事務局でいろいろな選択肢を検討してつくり上げた名前で。","voiceIndex":182,"id":"exchange-072"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"それと、英語をうまく使いこなせるし、身近な日本のことを英語で話そうと努力するということはすごく勉強になるから、だから、そういう逆の立場で、英語を日本人が教わるのではなくて、日本人が英語で、日本のことをよくわからない人に日本のことを説明するということは、日本の文化だとか教育だとか何かを教えることにもなるし、自分は日本人だということも自覚できるし。","respondent":"渋谷指導課長","answer":"小学校１年生から新たに今やっている英語の新カリキュラムでは、例えば、「おおきなかぶ」だとか「ももたろう」だとか、ああいう昔話を英語でジェスチャーつきで子どもたちが語れるようにすることによって。","voiceIndex":184,"id":"exchange-073"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"英語を教わるということは、あくまでも子どもが受け身になるので、子どもが主体的に英語を使って何かできると、主体的な取組みというのはすごくモチベーションが高くなると思うので、ぜひいろいろ検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問","question":"「ルネサンス」という言葉はたびたび聞いていますが、中身を伺っていて、今までやってきた積み重ねと、また新しいことといっぱい、すごくぎっしり詰まっていて、たびたび変えていく、検討していくという言葉が聞かれたわけですけれども、これ、ここまでつくり上げるのに、誰がと言ったらあれなのですが、どこで検討されて、どういう方たちがかかわってここまで来たのかというのと。","respondent":"渋谷指導課長、村尾教育総合支援センター長","answer":"どのような検討をというのは、冒頭ご説明申し上げましたが、基本的には、小中一貫教育推進委員会という組織で、それぞれ部会に分かれて検討してまいったところです。私から追加で、グローバル化に向けて、諸外国との関係づくりということで、区では３学期、また、来年度から、東京都と連携を図りながら、品川区のオリンピック・パラリンピック教育というものを進めていく予定になっています。","voiceIndex":187,"id":"exchange-075"},{"speaker":"高橋（し）委員","kind":"質問","question":"町会長に何かお願いに行ったときに、「何だ、それ」と。「何でこっち来るの」とかという話になると思うのです。あるいは、すまいるスクールで活躍している方をこちらにと言ったら、「何で」という話になったりすると思うので、そういったところの連携については、教育委員会もそうなのですけれども、他の所管の方たちはどう感じているかというのを伺いたいところはあります。","respondent":"渋谷指導課長","answer":"品川区の場合は生涯学習部門がまた、文化スポーツ振興部に分かれておりますので、今委員ご指摘いただいたように、さまざまな部署と、あるいは今お話があった部署以外の、例えば、福祉部門とももしかしたら連携をしなければいけないというようなことで、そういった役所の。","voiceIndex":190,"id":"exchange-076","title":"町会・自治会支援"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、そういった方が連携をとるというのは、話し合いの場ができるのでしょうか。","respondent":"渋谷指導課長","answer":"区のほうとしても、各学校のそういった連携の中心になるコーディネーターの方たちについては、コーディネーターの方たちに定期的に集まっていただく連絡会を設けまして、コーディネーターの方たちを通して、関係各課の方との連携のあり方だとか、また。","voiceIndex":194,"id":"exchange-077"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4874#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":69981,"voices":206}},{"id":"h28-20160119-5","meetingId":"h28-cm01","date":"2016年1月19日","dateIso":"2016-01-19","committee":"総務委員会","time":"午後 １時００分～午後 ２時５６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"は何もないことを祈るのと、こういう対応はよろしくお願いしたいと思うのですけれども、今、昨日の夜から今日までの経過の説明がありましたけれども、時間別というのでしょうか、昨日の１１時にどこに連絡があって、それがどう伝わって、区のほうでは何か、本部なのか、会議体なのか、何か立ち上がるのか、朝の庶務担当の会議があって、また今日の昼にホームページへのアップがあって、時間の系列と。","respondent":"江部危機管理室長","answer":"一応、夜間としては外周のパトロールと、それから警察との連携、連絡をとる。警視庁から来ておりますので、品川警察署とは既に連絡がとれておりましたので、そういう対応をし、朝の段階で方針を決めようというふうに判断したところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"ホームページへの掲載、つまり区民への一定の説明というか、経過も含めて、今日のお昼ごろということですけれども、こういう判断は、誰がどういうふうに打ち合わせてやっていくのかということと、あと区議会への報告と言ったらいいのか、情報提供と言ったらいいのか、そういう流れについて、もちろん会派としてお話は伺ってはいるのですけれども、昨日の夜１１時ごろということなので。","respondent":"江部危機管理室長","answer":"この手の件について、こうするというきちんとしたルールをつくっているわけではありませんので、過去あった事例、各区で、去年などは練馬区と足立区でありまして、それらを踏まえまして、こうしよう、ああしようということは、いろいろ議論はしております。","voiceIndex":7,"id":"exchange-002"}]},{"id":"topic-02","title":"品川区総合戦略の策定","agenda":"品川区総合戦略の策定","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"答申が出されたということですけれども、まず、この策定委員会における議論の経過や到達について若干伺いたいのですけれども、この答申文、表紙ではないのですね、これが答申文ということで、答申文について、この中で「将来に向けて、安定的な人口構造を確保するため」と、いわば総合戦略の目的が書かれておりますけれども、将来に向けて、安定的な人口構造の確保が目的というのは。","respondent":"柏原企画調整課長","answer":"今後の流れですけれども、基本的には、事務的な手続き等も含めて、３月末には発表といいますか、公表するように段取りをしていきたいと思ってありますので、遅くとも２月ぐらいには確定ができて、なかなか作業的には難しいところがありますが、いつ会議を開いてとか。","voiceIndex":14,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"そしてもう１つ、全体的に、一方で、保育だったり、介護だったり、福祉だったり、障害者だったり、防災だったり、施設建設の目標が実態と照らして乏しく、その仕組みや中身ももっぱら住民同士の助け合いを強調している点は改めるべきだと思うのですけれども、全体を通じてまずそこを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"それから内容につきましては、先ほども冒頭のほうで総合戦略の考え方、位置付けをお話をしたところですけれども、基本的には区の場合は、長期基本計画、総合実施計画ということで、大きな行政計画を持っている、これはトータルで５年間。","voiceIndex":16,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ経済的負担の軽減は重点課題として私は加えるべきだと思うのですけれども、その点を伺いたいと思います。やはり区の責任で支援の仕組みをつくることの位置づけが私は足りないと思うのですけれども、この点もいかがでしょうか。","respondent":"柏原企画調整課長","answer":"ただ、例えば区内オフィスとか企業等の雇用拡大がございましたけれども、産業的なところで申しますと、やはり区内産業の活性化というところは１つ大きな視点でありますので、その視点につきましては、この戦略の中で訴えているといいますか、触れている事業は。","voiceIndex":18,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"やはり新しい取組みや支援の形の検討を始めることをしっかり位置づけるべきではないかと思うのですけれども、その点を伺いたいと思います。やっぱり重点施策で掲げているだけに、計画との整合性等ありますけれども、戦略的にもっと強めていく要配慮者や備蓄や避難所の運営等々、そういう位置づけはやっぱり集中してやっていくべきことではないかと思うのですけれども、その点を伺いたいと思います。","respondent":"柏原企画調整課長","answer":"ただ、ハード的なところにつきましては、今回これはソフト的にどうしていくのだというところを打ち出させていただいてございまして、そのハード的なところにつきましては、長期計画、それから総合実施計画等々でこれは着実にやっていくといったところがありますので。","voiceIndex":20,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、予算の関係上というお話がありましたが、であれば、なおのこと２月でこれを決めてしまうというのはどうかなと思いまして、やはり第１回定例会を踏まえて意思決定をされるというのが筋ではないのかなというふうに思います。いずれにしても、切実な区民要望、様々な意見を取り入れていただきたいと思いますので、修正、改善、充実を要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-007"},{"speaker":"本多委員","kind":"質問","question":"これは意見が２６件ということで、１つ１つについては伺いませんけれども、意見に対する答えが、総合戦略策定の委員会で、学識委員が論点整理を行って回答をつくられているということなのですけれども、これは企画部のほうでつくられていて、回答はそれぞれの課題に対して所管の意見と、この委員会での答えと、その辺の整合はとれているのか、素朴にどうなのかなと思って、それだけ教えてください。","respondent":"柏原企画調整課長","answer":"パブリックコメントを受けた中で、当然、関連する所管のところとは事前に調整といいますか、話をした上で、区の今の考え方ということで、こちらのほうに示したものに対して、企画部、それから学識委員、それから策定委員会もそうですけれども。","voiceIndex":23,"id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"私はそのように受けとめたのですけれども、区側として、戦略として書いたものと、実際にこれから品川区として変化していく社会の中でどこに今後新たなことを入れていくのか、重点的にしていくのか、今までなかったこの分野に新たに踏み出していくかというような、どのようなプロセスでつくっていって、かつ、こういった戦略のタイトルをどのような関係、あるいは、関わり方になっていくのか。","respondent":"柏原企画調整課長","answer":"この総合戦略につきましては、今、総合実施計画のところでも議論をしていてというところからこちらのほうへ持ってきているといったところでありますので、全く新しい分野への方向性というのは、今回はそこまでは謳っていないものが増えています。","voiceIndex":25,"id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほど、本多委員のご質問と関連するかと思うのですけれども、この寄せられた意見への対応というものを読ませていただくと、意見への回答にはなっていると思うのですが、それがどういうふうに、パブリックコメントを求めて出していただく以上、それがどう反映されたかということが必要になっていくのではないかと思うのですが、パブリックコメントで寄せられた意見の総合戦略への反映ということでは。","respondent":"柏原企画調整課長","answer":"このご意見の中身にもよってくる部分ではありますけれども、直接的に文面であったり、考え方のところで総合戦略でそういったご意見をもとに修正をかけていくというところもありますし、若干この総合戦略そのものの記載というよりは、通常の事業の中であったり。","voiceIndex":27,"id":"exchange-010"},{"speaker":"吉田委員","kind":"意見","question":"わかりましたと言っていいのかどうかあれなのですけれども、やっぱり３名の方によるパブリックコメントということ自体も、パブリックコメントということに対してどう評価するかという、パブリックコメントのコメント者の数としてということも考えなければいけないと思うのですけれども、やっぱりコメントを得られたら、それは聞き置くのではなくて、こういうふうに議論されたというようなことが何かないと。","respondent":"柏原企画調整課長","answer":"先ほどちょっとお話ししましたように、ホームページのアクセス数は非常に多かったというところを考えると、なんだろうというところにはしてもらっているのだとは思うのです。ですので、その先にどううまく伝わるかというのは、それは工夫はさせていただきたいと考えています。","voiceIndex":29,"id":"exchange-011"},{"speaker":"あくつ副委員長","kind":"質問","question":"だから、先ほどのアクセスがあったけれども、なかなか素案自体の評価ができなかったというところも何なのだろうというところがすっきりしなかったのではないかということを感じているのですが、前回、課長のご答弁の中では、物によってはやはりゴールを目指したものもあれば、そのパフォーマンスを満たしているところもあるので。","respondent":"柏原企画調整課長","answer":"前回もご議論といいますか、お話しいただいた議論です。国ともＫＰＩとＫＧＩのところは少し調整といいますか、話はさせていただいたのですが、全ての事業、出したものに対してＫＰＩがそれにそぐうかどうかというのは、それは難しいでしょうというのは国も言っております。","voiceIndex":31,"id":"exchange-012"},{"speaker":"あくつ副委員長","kind":"確認","question":"当然そのとおりだと思うのですけれども、ということがあったので、下手をすると、パフォーマンスという言葉でするすると流れてしまう可能性もあるのか、達成したかどうかというところを、さっき評価という話がありましたけれども、そこのところはしっかり達成をされていくのかどうかという意識を持ってやっていくのかどうか、この２点、確認の部分とその点を教えてください。","respondent":"柏原企画調整課長","answer":"でも、これは５年間に向けた目標値といいますか、今後進んでいく目標として立てるものですから、それに向かって、それが実現できるように施策も充実して頑張っていくという姿勢でこの総合戦略はつくっていくというものです。","voiceIndex":33,"id":"exchange-013"}]},{"id":"topic-03","title":"品川区教育大綱の策定","agenda":"品川区教育大綱の策定","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それと教育大綱、区長が策定するものということなので、２つばかりまず伺いたいのですけれども、大綱素案の２ページの「しながわ学びの杜」の開設ですか、私もこれは不勉強でよくわからなかったのですけれども、これは今どういう動きになっているものなのか解説していただきたいのが１つ。まちづくりとして捉えているのか、長計の都市像の１つだから単純に「都市」という言葉がここについているのか。","respondent":"柏原企画調整課長","answer":"それについて、ご批判であるとか、ご意見をいただいて、いろいろな部分で地域の方とも事業を進めたいといったところがあるというふうには認識してございまして、全くこれが、こういったご意見をいただく中で、全ての位置づけという話ではないだろうというふうには思ってあります。","voiceIndex":39,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"内容について、以前指摘したところと同じ点なのですけれども、６ページ目の「良好な教育環境の確保のために、就学人口の動向を見据え、校舎改築や学校配置のあり方について検討します」と、この点について、改めて伺いたいのですけれども、前回のやりとりで、統廃合ありきではないというそういう答弁がありましたけれども、私はこれは統廃合を区長部局が教育委員会に求めるものだと思うので。","respondent":"柏原企画調整課長","answer":"今、学校の建物の老朽化であるとか、そういったところを考えたときに、この建物はそのままでいいのかという、いろいろなそういったハード的なところのことを考えたときに、就学人口が影響によっては大きく変わったりというものがありますので、そういったところを踏まえる中で。","voiceIndex":41,"id":"exchange-015"},{"speaker":"あべ委員","kind":"確認","question":"細かいところですけれども、やっぱりパブリックコメントのこの文章なり意見への対応というのは、直接お返しする形になるのでしょうか。それとも、当該の方にその部分をご説明とかという中で、このままこれそのものをお送りするような形になるのか、確認させてください。前も別の科目で聞いたような気がするのですけれども、改めてお伺いします。","respondent":"柏原企画調整課長","answer":"いろいろなことでパブリックコメントを行っている手法と同じ手法でございまして、もう少し中身は整理をいたしますけれども、これを直接お返しするということではなくて、この中身をつくったものを一般的に公表して、それをご覧いただくという形で捉えております。","voiceIndex":43,"id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"対応への書き方で、若干そっけなく見えるところが結構あるので、皆さんの目に触れるときには、もう少し柔らかくいい表現もあってもいいのかなと思うのと、若干まだ誤字が残っているので、それらを気をつけられたほうがいいと思います。これは細かい点ですが。それをどのようにお考えになっているか伺えればと思います。","respondent":"柏原企画調整課長","answer":"実は、まとめて書いてしまったので今回こういった書き方なのですが、前回の１２月の第３回の総合教育会議でも、多分今、委員がおっしゃっていただいた内容に近い部分で議論になってあります。","voiceIndex":45,"id":"exchange-017"},{"speaker":"あべ委員","kind":"意見","question":"でも、そのような視点からさらに議論を深めていっていただけるということですので、そちらに期待したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-018"},{"speaker":"あくつ副委員長","kind":"質問","question":"なぜかというと、５番目の文化芸術というこの項目自体、全く前後との一貫性がなくて、教育というふうにちょっと読み取れない。私も全く同意見なのですけれども、その後、この回答が、５番の文化芸術の振興において、区民が地域文化に親しむ機会の充実を図ってまいりますと。それとも、それはやっぱりもう、そこはあまり必要ないのですというお考えなのかどうか、そこのところを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"ただ、今、委員におっしゃっていただいたとおり、つくりとして様々な捉え方があるというのは、それは認識はしているところでありますので、一定程度、構成としてまとまりが出てきたところで、修正ができるのかどうかということはありますけれども。","voiceIndex":48,"id":"exchange-019"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"この方もそうでしょうし、私もそうなのですけれども、学校教育の充実というところに本当に１項目入れていただきたいぐらいの思いではあるのですけれども、それもなかなか今は難しいというお話であれば、例えば文化芸術の振興のところに、学校教育の一部を入れるとか、子どもという視点をあえて入れるとか、そういったところもぜひ入れていただきたいというふうに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"先ほどの総合戦略と同じような意見になってしまうかもしれないのですけれども、やっぱりこのパブリックコメントの扱い、さっきコメントが若干そっけないというものもありますし、やっぱり出した以上、どういうふうに反映されていくのかということで、ちゃんとパブリックコメントに対する答えとして、そもそもこういうふうに反映されますと、どこかで検討されて。","respondent":"柏原企画調整課長","answer":"回答としますと、これを全部一まとめにしてというものではなくて、この形式はもう少し整理しますけれども、こういった形で１つの意見に対してこういうふうな考えを持つということを、例えばホームページだとか、そういったところで公表をしていくということで考えております。","voiceIndex":51,"id":"exchange-021"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、ちょっとうまく言えないんですが、要するに、パブリックコメントについて、個々への対応だけではだめなのではないかということなのです。どういうふうに反映されたかということがコメントを寄せた人に対しては、その回答こそが求められるのではないかというふうに思います。","respondent":"柏原企画調整課長","answer":"今回やらせていただいたのは、先ほどもそうですけれども、この１つの計画、素案に対して、これの中身といいますか、このものについてご意見をいただきたいということで。","voiceIndex":53,"id":"exchange-022"},{"speaker":"吉田委員","kind":"意見","question":"今、もっとよく読み込めば、もっといろいろなことが出てくるのではないと思いますけれども、やっぱりそういうことを感じる方はいるのではないかと思うのです。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":55,"id":"exchange-023"},{"speaker":"大沢委員","kind":"質問","question":"簡単に伺いますけれども、22番ぐらいから、学校の現場のあるいは退職された先生、パブコメですから広く意見ということで拒むものではない、これは基本なのですけれども、そこら辺りをちょっと拝見しますと、明らかに現職の方あるいは退職をされた方、もちろん区民なのでパブコメをされたと思うのですけれども、そこら辺りの、そういう意味では、品川の教育の根幹の内部にいた方たちのご意見が寄せられた。","respondent":"柏原企画調整課長","answer":"ただ、あくまでこれは意見をいただくという１つの手法、場面でありますので、それに対しての答えをこちらのほうもほかの方と同様の形でするということで、特別に何かというところは、パブリックコメントという意味で言えばないというふうに考えているものです。","voiceIndex":56,"id":"exchange-024"},{"speaker":"大沢委員","kind":"質問","question":"このパブコメの結果ですが、これはやっぱり外に出るわけですね。教育委員会の方たちは、品川区の教育、公教育のもう一歩先、もう一歩先をということでご努力をされている中で、マイナスの部分を隠すことはいいことではないのですけれども、そこらの表現を工夫をしないと、何か混乱が生じてしまうのではないかと思うのですけれども、そこのところはどうでしょうか。","respondent":"柏原企画調整課長","answer":"ここの表現の出し方につきましては、なるべくいただいたご意見を原文のままでというような思いはありますけれども、出し方による誤解であるとかという、例えば表現的にちょっとこれは公表するには耐えられないといいますか、出してはまずいような文章もある場合もありますので。","voiceIndex":58,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"それが何となく課長の話が、ちょっと否定的とは言わないけれども、何かちょっと答弁はどうなのかなと思ったのです。私はやっぱり教育改革、私も区の教育改革はいろいろ問題もあると思うし、批判的には思いますが、やっぱりそうは言っても、子どものためになってほしいというふうに願いますので、意見と質問をさせていただきたいと思います。","respondent":"中山企画部長","answer":"例えば学校の部分でも、区民がここだと「一人ひとり」というような書き方をしていたり、文化芸術の部分だと、どちらかというとこれは主語があまりなくて、「区民が」というようなところ、こういうところに例えば「子どもから大人まで学校も含めて全てが」みたいに書くとか。","voiceIndex":60,"id":"exchange-026"}]},{"id":"topic-04","title":"債権の放棄","agenda":"債権の放棄","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"１件目の学童保育料なのですけれども、これ、放棄の根拠が５号になっているということは、特段、資力の問題としては払える状態だけれども、時間があまりに経って回収ができそうにないので放棄するというふうになるのですね。状況がどういう感じなのか教えていただければと思います。","respondent":"福島会計管理者","answer":"こちらですけれども、４月に学童保育に入会したということなのですが、保護者としては、すぐやめさせたというふうに思っていたらしいのですけれども、それがうまく伝わらずに、１年間あったということで督促をしていました。","voiceIndex":69,"id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"私は、この障害者福祉手当は、これ、返還する分なのですね。参考までに、どういうもので、どう返還すべきだったのかを教えてください。","respondent":"福島会計管理者","answer":"それでとれない。相続人ということで、妻ですとか子どもを探したのですけれども、名前も変わっていて住所もわからないというところで、もう取り立てることはできないだろうというふうに判断したものです。","voiceIndex":71,"id":"exchange-028"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"この変更に伴って何か区に負担が発生するとか、そういうことがないのか。たしか始まったときに全部東京都が負担するということで、区は何もないという話を聞いてはいるのですけれども、一応、変更なので、そこだけ確認させてください。","respondent":"提坂人権啓発課長","answer":"行政財産使用許可を出していますけれども、その期間が終了するということもありますので、その辺は延長でまた使用許可を出すということもあります。","voiceIndex":79,"id":"exchange-029"},{"speaker":"あべ委員","kind":"質問","question":"実際に、夏は結構暑くなるみたいですし、その他も、やはり２年半延びるとなると、あそこを利用されている方、ここは総務委員会なので直接の対象は限られてきますけれども、利用されるそれぞれの方々に、ある程度ヒアリングをしたり、これ以上使うのであれば、例えば暑さ対策ももう少し本格的にやったりとか、何か対策のようなものも一定必要ではないかと思うのですけれども。","respondent":"提坂人権啓発課長","answer":"私も約３年間、あそこで仕事をさせていただいているのですけれども、やっぱり夏場にちょっと日差しが強くて暑いとか、冬場は逆に寒いとか、そういう面もございまして、その辺は改善できるものについては要望を出させていただいて、２年半。","voiceIndex":81,"id":"exchange-030"},{"speaker":"あべ委員","kind":"質問・要望","question":"確認なのですが、その際の対策というのは、都のほうに要望を出して、都でやっていただくということでよろしいのでしょうか。","respondent":"提坂人権啓発課長","answer":"ただいま、都のほうとも調整しています。","voiceIndex":83,"id":"exchange-031"},{"speaker":"あべ委員","kind":"質問","question":"これ、少しずれてしまうのですけれども、この工事で、一方で公園も使えない状態になっていますけれども、これについては、周辺の方々のご理解もそうなのですけれども、あまり長くなると、どうなのでしょう、別の遊び場みたいなものを用意したほうがいいのではないかと思って、そういった考え方はないのでしょうか。工事の反対側のほうです。","respondent":"提坂人権啓発課長","answer":"工事関連の詳細については当方では把握していないのですけれども、立会川沿いの町会の方ですとか、現在の仮移転先の町会の皆様に対して、東京都がその辺を丁寧に説明していくとは聞いてあります。","voiceIndex":85,"id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2036#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":39663,"voices":91}},{"id":"h28-20160120-14","meetingId":"h28-cm01","date":"2016年1月20日","dateIso":"2016-01-20","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ３時１３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査の(1)国家戦略特区に関すること","agenda":"特定事件調査の(1)国家戦略特区に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"最初はまず区にお伺いしたいのですけれども、改めて区としてはこの介護・保育の人材不足の現状をどのように考えているでしょうか。保育士もほぼ同様の１０万円低いということになっていまして、私はこういった低い現状というのは、これが大変大きな問題だと思っているのですけれども、区としてはどのようにこの現状をお考えでしょうか。","respondent":"柏原企画調整課長","answer":"一つには人材の部分のところでの例示といいますか、委員のほうからもございました、福祉の現場、それから保育等の現場において、人材を確保するのが難しくなっているという状況が現実としてあるというのは認識しています。","voiceIndex":3,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり品川区としては、こうした根本的なところの待遇改善こそ力を尽くすべきだと思います。これは資料の中にありますけれども、規制対象の見直しなどをしているということもありますが、現状をお伺いしたいと思っていまして、どのような場所や時間帯などでこういった見直しがあるのか。品川区内での現状というのは、この見直しの現状というのは何かあるのかということをお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"品川区内におきましては、１カ所公表されている所がございまして、品川区の大井一丁目で、ちょうど阪急デパートと京浜東北線の間の道のところが、午前５時から午前８時までの間、これで貨物ということで。","voiceIndex":5,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"そういうことのために、機械的な路上駐車の取締まりの中でちょっと困っているのだという話も聞いたことがあるのです。ですから、時間帯とか場所というのはあるかもしれないのですが、どういった形でというのは難しいのですけれども、やはり小規模事業所とか商店支援という観点から、例えば業種などになるのでしょうか、やはり一定の改善が必要なのかなという思いがしております。これは全て意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"提案","question":"多分、当委員会として国家戦略特区における提案項目を確認する議論だと思います。それでいいのですよね。ただし、これも各自治体が条例で基準を定めているわけですから、果たしていわゆる特区構想にまで持っていく必要があるのかどうかというのは、甚だちょっと疑問だということです。この確認と、それからいつぐらいにこの方向が見えるかということについて、品川区の現状のお考えをお聞かせください。","respondent":"柏原企画調整課長","answer":"これがこの先どのタイミングで認められるかというところはありますけれども、先ほども若干ありましたが、介護人材の人が足らなくなっている状況は、やはり区としても、これは社会福祉法人が事業を進めていく上で、それから品川区としても施策を進めていく上で。","voiceIndex":8,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうすると、外国人介護人材の活用については、それこそ国会で多分法案が提出されて議論されていくのでしょうから、やはりその議論を待った上でないと、こちらの当委員会として出すのは非常に難しいのではないかという気がします。けれども都道府県の公安委員会では、極めて少ないけれども許可していることも事実です。繰り返しますけれども、もちろん私たち自民党のところにも多くの要望が来ています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-005"},{"speaker":"石田（秀）副委員長","kind":"提案","question":"委員長が話してくれたとおりでありまして、議員間討議をしたいというのは、最初に１番から６番までは国家戦略特区で、最終的にこの行財政改革特別委員会として提案・提言をしていくということです。とりあえず６つは結構議論をしたと。そういうのを分けていきたいということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-006"},{"speaker":"中塚委員長","kind":"確認","question":"まとめについての議論の方向は、次回しっかり確認をして進めていきたいということは思いますけれども、今回、いま一度この残りの部分をこの行財政改革特別委員会の議論のテーマに載せたという趣旨は、今、副委員長から話があったように、確かに国家戦略特区に関することというのが大きなテーマではありますけれども、議論の中で挙がってきた一つ一つの意見ですので、それはしっかりもんで、方向が見えるもの。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問・要望","question":"となると、例えば品川区、皆さんの合意が得られればの話なんだけれども、こういうことがあって、この緩和については東京都の公安委員会になるのでしょうか、ぜひ緩和を検討していただきたいなり、そのようなことは検討してもいいのではないでしょうか。国家戦略特区ではないのだけれども、都の公安委員会に対して部分的な緩和とするのは非常に理解できる部分がありますよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-008"},{"speaker":"たけうち委員","kind":"質問・要望","question":"あと大体見てみますと、もちろん国家戦略特区に挙げる話ではないような中で、一定程度規制緩和を行っていたりとか、今の枠組みの中でそこへの具体的な要望等で対応できるものもあるような感じなので、結論から言いますと、うちはこの１２番の水辺観光ルート開拓に向けた憩いの場の設置というここを、これはこれだけだとちょっとあれなので、上の６番の２点間の運航の許可とあわせて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-009"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"私から２点。もちろん安全性はそうなのだけれども、もう蹴上げの部分のその何cmというのはもう現実問題無理がある。それを変えろということは借りるビルだと無理があるので、そういうところぐらいはやはり緩和してほしいなと。そうしないと、この待機児童対策の賃貸ビルの空き室を借りられないという要望があったので、ここに挙げてもらったというのが一つです。","respondent":"柏原企画調整課長","answer":"今、副委員長からもありましたけれども、２点間航路をやるときに桟橋をどうするのだというのはどうしてもやはりクリアしなくてはいけない課題だということで、不定期航路をやるにしても具体的にどことどこを結ぶとか。","voiceIndex":15,"id":"exchange-010"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"だから、１２番については別に上に上げてもいい、この６番をうまく書き方を変えてやればいいのかなと。結論じみた話をしてしまって悪いのだけれども、やってやれないことはないというか、これはやるべきだなと私は思っています。それは長くしたい気は確かにわかるけれども、それは１０年、２０年の中で償却できていくというようなことは訴えていければいいのかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問","question":"１１番の未接道住居等の建替えに際する要件緩和とあるのですけれども、私もいろいろな相談事を受けるのですけれども、こういうことを緩和するとなると、今までこのとおりにつくってきた方々に対して不利益が生じる可能性が当然出てくるわけですね。しかも、これは例外的に建替えが認められているという表現になっているのですけれども、聞いて大丈夫ですかね、どのような例外があるのですか。","respondent":"柏原企画調整課長","answer":"それもそれほどたくさんのものがあるということではなくて、やはり例外ですので、年に何回あるかどうかというのを、それを手続きを踏んで建築審査会を通した上でということですので、こういう例外ですというのがかっちりしたもので条文化されたものではないのですけれども。","voiceIndex":18,"id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問","question":"建築基準法上は２ｍ以上接しなければならないということがあるのでしょうけれども、品川区もそうですが、全国の様々な状況があった中で、つまり品川区が建築審査会の同意を得て許可するということで、ある程度対応可能なわけですよね。よく都市計画の話があるじゃないですか、外す、外さない。そうするとこれも同じような可能性が、もしかしたら出てくる可能性があるわけじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"その中で商店街のアーケードの更新要件の緩和ですとか支援策などを、やはり守っていくためにやっていくべきではないかと思っているのですが、区の現状の考えを教えていただきたいと思います。","respondent":"柏原企画調整課長","answer":"ある意味規制がないといけない部分もあるというのは事実であろうと思いますので、その部分についてフリーに全部規制緩和というのはなかなか難しいだろうとは思ってありますけれども、商店街全体の考え方で、活性化という意味で安全・安心がもう担保できるということであれば。","voiceIndex":21,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうですね、私としても当然安心・安全等といったことは確保していった中で、やはりアーケードの老朽化もしてきていると思いますので、これをどう維持していくのか、更新していくのかというところで、今ありましたとおりに安全を確保してしっかり支援等をしていっていただけたらと、これは意見として、やっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"いろいろお話も伺う中で、７番についてはまさに現国会で審議中ということで、注視していくということでもいいのかなと思っていまして、先ほどお話があった１２番は、書き方によって国家戦略特区になるのではないかというところで、まさに水辺の部分の利活用という部分では抱き合わせになるのか、水辺に面したレストランとかというところで国家戦略というお話が副委員長のほうからあったので、可能であれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"現行のルール自体も、大変１人あたりの子どもの面積が非常に狭いということで、緩過ぎるという問題もあります。ですから、私は現行のルールをさらに緩めるというのは、やはり問題があるという意見です。そのために事業者が、あるいは社会福祉法人などがそういった基準にかなう施設をつくるときに、やはり必要な支援こそ、やはり私は行うべきではないかという意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-017"},{"speaker":"横山委員","kind":"質問","question":"認可保育所設備基準の緩和についてなのですけれども、先ほどほかの委員から、階段の２０cmという規制というお話があったのですけれども、逆に今の児童福祉法の規制の部分から考えるのではなくて、現在品川区にある空いている施設であったり、空き物件であったり、そして子どもの安全・安心を守れる可能性が非常に高いものだけれども、現行の児童福祉法ではどうしても難しいというものについて。","respondent":"柏原企画調整課長","answer":"ですので、区としましても待機児童対策は喫緊の課題ということで取り組んでいるところではありますけれども、この規制緩和という意味で言いますと、東京都という認可を実際している大きな自治体がありますので、そことの調整といいますか、これは東京都全体の話。","voiceIndex":26,"id":"exchange-018"},{"speaker":"横山委員","kind":"質問・要望","question":"今、品川区はこういった物件が実際あって、可能性があるみたいな情報交換だったりというところは、東京都のほうと今いろいろしていただいているかと思いますので、国家戦略特区の枠組みで直接的には難しいというお話があったのですけれども、また今回は国家戦略特区についてのお話ではあるのですけれども、先ほどの、今回のこの議論の趣旨にもありましたように、今後。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-019"},{"speaker":"たけうち委員","kind":"確認","question":"今のところでちょっとわからないところがあるのですけれども確認で、そうすると児童福祉法自体の改正は別の問題として、そのままでやるとすれば、東京都がある程度理解があれば、国家戦略特区のほうに挙げることができる、そこでどうなるかはわからないけれども、という考えなのかというのが一つと。","respondent":"柏原企画調整課長","answer":"ちょっと認可保育園のところの考え方がなかなか難しいものがあるのですけれども、児童福祉法で言っておりますのは、大きなところで一定の基準をクリアしなくてはいけないと法律で言う。その下に、それに基づいた基準というものを厚生労働省がつくっている。","voiceIndex":29,"id":"exchange-020"},{"speaker":"たけうち委員","kind":"意見","question":"わかりました。そうすると、通るか通らないかわからないけれども、やるとすれば、ある程度東京都の理解をいただいた上で国家戦略特区のほうに挙げてやらないと、あとは法律改正しかないということですね。わかりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-021"}]},{"id":"topic-02","title":"基金に関すること","agenda":"基金に関すること","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"減債基金についてもう少し詳しくお聞かせいただきたいのですけれども、いわゆる地方債の償還ということで、平たく言うと品川区の借金の返済のための基金だと思うのですが、今、平成２６年度末起債残高１８５億円ということになっているのですけれども、これはこれまでの区政の運営の中で、いわゆるどうしても歳入で不足米があって。","respondent":"秋山財政課長","answer":"例えば学校用地の購入でありますとか、公園の用地の購入ですとかというものということでございまして、そういうものの平準化をしたものについても、十分な返済のものを持つという意味で、この減債基金を積み立てると考えているものです。","voiceIndex":37,"id":"exchange-022"},{"speaker":"塚本委員","kind":"質問・要望","question":"ありがとうございました。一応、年度当初ではないのですけれども、そういう減債基金とかというのを聞くと何かすごい借金をしてしまったのかみたいなことを時々誤解をされる方もいらっしゃるので、改めて確認のために質問させていただきました。","respondent":"秋山財政課長","answer":"そういうこともありますし、オリンピック・パラリンピックというのも一つの契機ということでもありますので、今回新しいものを、今、検討を進めている最中です。","voiceIndex":39,"id":"exchange-023"},{"speaker":"塚本委員","kind":"質問・要望","question":"新しいオリンピック・パラリンピック、スポーツ振興等でのというところで基金を設けるですけれども、これからの話にはなりますが、一つだけ要望的なことを言わせていただくと、なるべくオリンピック後も考えたような、オリンピック開催に向けてもちろん必要なところもあるのでしょうけれども、オリンピック開催後のいわゆるレガシーみたいなところにも視点を入れた形で考えていただければと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-024"},{"speaker":"沢田委員","kind":"質問・要望","question":"ちょっとわからないことがあるので教えていただきたいのですけれども、この間の決算特別委員会の中でも、基金全体のことでいろいろ質問があったかと思うのですけれども、この４つの基金のそれぞれどれだけあれば足りていると言えるのかというところを、ちょっともう一回確認したいのですけれども、例えば公共施設整備基金というのは「耐用年数を５０年として。","respondent":"秋山財政課長","answer":"それから公共施設整備基金につきましては、この１０年間の改築の想定をして、先ほどm2数に単価ということで、およそ３５０億円程度を目標と。それから義務教育施設整備基金も同じように、学校改築が１０校程度ということで、３００億円程度というような目標を立てております。","voiceIndex":42,"id":"exchange-025"},{"speaker":"沢田委員","kind":"意見","question":"まだちょっと足りていないという感じなのかもしれないですけれども、特に財政調整基金のところで、「経済状況の著しい変動等によって」ということもあると思うのですけれども、例えばこの何年か、リーマンショックのときもありましたけれども、これは予算書などを見ればわかることなのかもしれないですけれども、どの程度取崩しをしたときがあったのか。","respondent":"秋山財政課長","answer":"ただ、だからといって、歳出のほうは継続性がありますので、そこまで落とすことはもちろんできません。ということで、その財源をどうするのかというのが、一つはその基金を用いて、行政の区民の福祉のための業務が継続されていくという考えで、今いるです。","voiceIndex":44,"id":"exchange-026"},{"speaker":"沢田委員","kind":"質問","question":"そのとき財政調整基金はどの程度の取崩しがあったのか。その年、リーマンショックは今からもう６年前ですか、その年に取り崩したということでよろしいですか。それとも毎年取り崩しているわけではないですよね。その辺のところのこの財政調整基金が取り崩されたときというのはいつなのか。","respondent":"中山企画部長","answer":"この辺で様々な取崩し型基金というものが活用されたということで、ちょっと内訳の金額は今確認しておりますけれども、当然こういうときには充当していったと、取崩し型基金を取り崩していって対応したです。","voiceIndex":46,"id":"exchange-027"},{"speaker":"沢田委員","kind":"質問・要望","question":"そのときにどれだけの額かというのはあるかと思うのですけれども、そう考えるとそれほど滅多に取崩しは、平成の初めのころにあったということで、それだけ大きな経済状況、リーマンショックのときも結局はそれほど取り崩されていないということなのかと思うのですけれども、そうするとその１９０億円という目標は、どういう形のことを想定されて立てられているのか、お聞かせいただきたいです。","respondent":"中山企画部長、秋山財政課長","answer":"このように考えているものだということでご理解いただきたいと考えています。そういう時間的な余裕を持つことによって、景気対策もできるでしょうし、そういう対応もできるのではないかという形で、標準財政規模の約１０％を２年分というのを今のところ想定しているというところが、今。","voiceIndex":48,"id":"exchange-028"},{"speaker":"横山委員","kind":"意見","question":"こちらの２番の基金の設置と財源についての(3)で想定される政策等にオリンピック・パラリンピック、スポーツ振興、施設建設などとあるのですけれども、今挙げられているこの３点以外にどのようなものを想定していらっしゃるのかお聞かせいただけたらと思います。","respondent":"秋山財政課長","answer":"これは一般的に現時点で考えられるものということで想定をされていましたので、私どもが想定をしているというよりも、一般的にこういうことが考えられるということで出させていただいたもので、例えばこれ以外にも庁舎の建設で基金を持っているような自治体もありますし。","voiceIndex":51,"id":"exchange-029"},{"speaker":"横山委員","kind":"質問","question":"そうした点については、現在はどのような考えでしょうか。","respondent":"秋山財政課長","answer":"そういうものも含めて、普段から待機児童対策も含めて施策を立てているところですので、そういう経済が落ちて減収になったとしても、そういうものを継続的に進めていくというところがひとつ重要なものだと考えております。","voiceIndex":53,"id":"exchange-030"},{"speaker":"伊藤委員","kind":"質問","question":"個々具体的な基金のことももちろん必要です、これも必要です。見えることは見えるのですけれども、いろいろなものをあちこちから照らし合わせて見ないとわからないところがあるわけじゃないですか。だから、そこのところは少し工夫をする可能性があるのではないかと思ったのですが、ちょっと今日の基金についての内容とは変わってくるのだけれども、ぜひいい機会ですから、お考えをお聞かせください。","respondent":"秋山財政課長","answer":"多分、予算書とか決算書等というつくりの中で、いかにわかりやすくお伝えをしていくかというところのご質問かなと考えていますので、その辺につきましてはよりわかりやすいものができないかということで、今後とも引き続き検討はさせていただきたいと考えています。","voiceIndex":55,"id":"exchange-031"},{"speaker":"伊藤委員","kind":"質問","question":"公共施設有効活用プランとの連携も、これも基金と相当絡んでくるわけじゃないですか。けれども、経年的な変化については、こちらが勉強して資料を探していかないと見当たらないわけじゃないですか。となると、この表だけではなかなかそれが見えにくいということを指摘するのだけれども、品川区のお考えをもう一回聞かせてください。","respondent":"秋山財政課長","answer":"今回の資料につきましては、将来的な基金の内容についてご議論を伺うということでお出しさせていただいたので、過去の充当というものについては載せてはいないという状況ですので、充当先の内容につきましてもご要望ですので、今後ともわかりやすくということも含めて。","voiceIndex":57,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"資料の具体的なところからまずお伺いしたいのですけれども、積立原資ということで４つの箇所に出ていますが、税等増収分と税増収分とありますけれども、具体的には何を指しているのか。一般区民税なのか財政調整交付金なのかということもお伺いしますし、あと「等」があるのとないのとがあるので、そこら辺の違いもお伺いしたいと思います。","respondent":"秋山財政課長","answer":"財政調整基金の積立原資と公共施設整備基金の「等」ですけれども、「税等」と書いてあるのは、歳入のほうのその他の財調等のことです。この「税」と書いてあるのは区民税です。","voiceIndex":59,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"例えば保育園あるいは児童センター、図書館などは含まれるのかどうか伺います、これが２点目です。３点目は、義務教育施設整備基金のほうでも同様に「今後１０年間で１０校程度の改築を想定し積立」とありますけれども、結構耐震化や建替えなども進んでいるところもたくさんあると思うのですが、どの学校を想定しているのか、伺いたいと思います。","respondent":"秋山財政課長","answer":"積立原資の話ですけれども、税についてはその割合をいかに決めて積立てをするかということではなくて、結果として、税は一般財源ですから、その年の通常の事業のほうに使うのが通常ですから、それの通常使った分と税収の増の部分というのを見合わせまして。","voiceIndex":61,"id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"ですから、それを積み立てていくということなのでしょうけれども、ちょっとわかればでいいのですけれども、じゃあ、今までのこの間の推移として、毎年増収分のうちどれぐらい、何割ぐらいが結果として積立てのほうに回ったのかというのが、これはちょっと口頭で聞いてもあれかもしれないですけれども、わかる範囲でいいのですが教えていただければと思います。","respondent":"秋山財政課長","answer":"例えば財政調整基金は、平成２６年度の積立が９億５,０００万円ほどですので、増収分としては、すみません、ちょっと今手元に数字はないのですが、たしかかなり増収はしていたと記憶しておりますので、その中でその積立額というのは。","voiceIndex":63,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問","question":"そこら辺は引き続き私も研究していきたいと考えています。やはり取り崩すという想定はほとんどないということなのか、ちょっとそこら辺がよくわからなかったので、お伺いしたいと思います。","respondent":"秋山財政課長","answer":"ですので、財政調整基金を使っていないから、ずっと基金を使わないのかということではないかと考えています。","voiceIndex":65,"id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"その上で財政調整基金もあるということで、本来財政調整基金で公共施設などの備えをしているところもあるのかなと思うのですが、そういった総体を見ると、やはり他区に比べますと非常に、先ほどの積立ての原資の話もありましたけれども、やはりなるべく入りを増やし、出を減らし、その差額を積み立てているのかなという印象があるのですが、そうした他区の基金との関係の中で。","respondent":"秋山財政課長","answer":"今回、第１回定例会に提出を予定しているものにつきましても同じような考えでやっているです。","voiceIndex":67,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから基金にするということが、じゃあイコールその振興につながるのか。区が今考えている、あえて基金にするというお考えということですけれども、これがスポーツの振興につながっていくのか、具体的には施設整備の充実などにつながっていくのかどうかお伺いしたいと思います。","respondent":"中塚委員長、秋山財政課長","answer":"条例はこれから出るということで、ただ一般的な特定財源としての基金について一つの考える視点でもあるかなと思いますので、その辺をよろしくお願いします。基金につきましては、先ほども何度もご説明させていただきましたけれども、一定の施策を今後していくのだというところの財源的な担保といいますか、平たく言えばお金を用意して。","voiceIndex":69,"id":"exchange-038"},{"speaker":"たけうち委員","kind":"質問・要望","question":"少し考え方を教えていただきたいのですけれども、よく品川区のほうでも予算とかを家計に例えて、例えば食費だとか、いろいろな家計に例えてやりますよね、品川区の予算の場合は食費はないですけれども。分母になるところですね。例えば一般会計だけだったら１,５００億円ぐらいの中で、約半分が家計で言うと貯金になりますよと。そういう、どう考えればいいかというのを教えてください。","respondent":"秋山財政課長","answer":"そこに８００億円程度の基金があるというところは、その多い少ないというのはちょっといろいろ評価があるかと思いますけれども、その８００億円がどうかというよりも、基金それぞれの性質を考えてこの程度持っていることが、何があってもというのはおかしいですが。","voiceIndex":72,"id":"exchange-039"},{"speaker":"たけうち委員","kind":"質問・要望","question":"もちろん一般の家庭と区と、例えば公共施設だとか義務教育のこれをあてはめると、一般家庭で言えば家の建替え費用とか改築費用というのはこのような割合なのかということになってしまうので、それが幾つもあるということだから、別荘が幾つもあるのという話になってしまうから違うのだけれども、何かわかりやすいものをやはりつくってもらえると非常にいいかなというのが、これと直接関係ないのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-040"},{"speaker":"安藤委員","kind":"意見","question":"やはり財政調整基金は何でも使えるということですし、公共施設整備基金ももちろんそうですし、減債基金も一度起債をして、それを後から返すというために使うということなので、基本的にはほとんど使えると思っていますけれども、やはり額が幾らというよりも、今実態としてこういう要求があって、そこにやはり地方自治体の使命としてどうそこに応えていくかといいますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":75,"id":"exchange-041"},{"speaker":"たけうち委員","kind":"意見","question":"だったら明確にこれくらいまではと、今、品川区も全くつくっていないわけではなくて一生懸命やっている中でそういうふうにおっしゃるのだったら、もうちょっとこの金額でこれくらいまでできるのではないかというのをやはりお示ししないと、行財政改革特別委員会でなくていいので予算特別委員会とかでやってもらったほうがいいと思いますので、それはご提言として言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-042"},{"speaker":"のだて委員","kind":"質問","question":"少し調べてきました。２位が港区で４８万円。３位が中央区で３３万円となっておりまして、６位に品川区が２１万円ということになっているのですけれども、やはり２３区の中でも上のほうだと思いますので、やはり１人あたりで見ると多いと思うのですけれども、これを多いと思っているかどうか、品川区にお伺いしたいと思います。","respondent":"秋山財政課長","answer":"品川区は品川区の考え方で、基金をこれだけ持っていれば行政の継続性が担保されるということで考えて、今までやってきておりますし、これからもやっていくというつもりですので、その額について多い少ないというのは、特に私どもでは考えたことがないというのが現状です。","voiceIndex":78,"id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"各区考え方があるということでしたけれども、多いとも少ないとも考えたことがないということでしたが、やはりこの２３区の中で６位というのは多いと思うのですね。そういったところに増収分のところは使っていっていただきたいと思いますが、そこのお考えをお聞かせください。","respondent":"秋山財政課長","answer":"区民の福祉の向上のためにはなかなかできにくいということから、そういう税収の変動についても対応をとるために基金というものを積み立てて、今、運用しているというところでご理解いただければと思います。","voiceIndex":80,"id":"exchange-044"},{"speaker":"のだて委員","kind":"質問・要望","question":"減収もあるということで、その減収になったときにワクチン等はやめられないというお話ですけれども、一つのことをやるのにそれほどお金が、１００億円とかかかるわけではないので、やはりそういったことにはしっかり使っていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-045"},{"speaker":"伊藤委員","kind":"提案","question":"先ほどのたけうち委員の議論で思い出したのですけれども、文教委員会ですべての子どもが保育園に入ってもらう請願を審議したことがありました。文教委員会でいろいろ研究したら、結構なお金がかかるわけですね。だから、すぐには答えは出てこないと思うのだけれども、紹介議員としてやった以上は、それはこの財源も含めてぜひどこかの部分で提案していただきたいと思うのですが、いかがですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":83,"id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"共産党は既に本会議などでも質問しておりますけれども、４月の時点で待機児をゼロにするというためには、２０園の保育園の増設が必要だということも言っております。保育園一つつくるのにかかる建設費は２億円と言われていますので、２億円掛ける２０の建設費が出るわけですね。第一日野小学校の跡地もそうですし、区で持っている土地もあります。もちろん認証保育園を望む方もいます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-047"},{"speaker":"伊藤委員","kind":"質問","question":"何かあまり光りはしませんけれども、すべての希望する子どもたちが入るための保育園をつくってほしいと請願であったのです。これはすごいことをおっしゃっていますよね。それは方向性としてはあるかもしれない。けれども、万万が一大きな震災が起こったときどうするのですか。あるいはほかの様々な行政上の緊急の目的が出てきたときに、どうするのですかということについても考えなくてはいけない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-048"},{"speaker":"松永委員","kind":"確認","question":"ちょっと間違えていたら申し訳ございません、先ほど公共施設整備基金のところで、新築、改築、大規模改修と言われたような気がしたのですけれども、義務教育施設整備基金のほうでは新築というのはなかったのですが、その確認だけお願いします。","respondent":"秋山財政課長","answer":"聞き間違いではないのですが、私も冒頭お話しさせていただいたのは、公共施設の場合は、今後有効活用プランとかいろいろなプランを今後検討していく中で、新築が全くないということではないのかなということで、お話をさせていただいたです。","voiceIndex":86,"id":"exchange-049"},{"speaker":"大倉委員","kind":"質問・要望","question":"ちょっと教えていただきたいのですが、先ほど財政調整基金とかの取崩しがここ数年ないというお話だったのですが、積立てと取崩し、各４つの項目でどれくらい年間積み立てられて、取り崩されているのかという数字がわかればちょっと教えていただきたいのと、そういうのがわかればありがたかったかなというところで、出るのですかね、ちょっと確認してこなかったので、わかれば教えていただきたいです。","respondent":"秋山財政課長","answer":"これは、まず義務教育のほうの校数ですけれども、これはあくまでも想定でありまして、今後１０年間で耐用年数等を考えていくとこれぐらいが必要になるだろうということで、決して今の現状でＡ学校が何年、Ｂ学校が何年という積上げの金額ではないということで。","voiceIndex":90,"id":"exchange-050"},{"speaker":"大倉委員","kind":"質問","question":"義務教育施設整備基金のほうなのですが、１０年でどこがというより想定だというところで、実際お金がかかる部分で言うと、１校二、三十億円というところで改築していこうとすると、積立てを増やしていきながら計画的にやっていかなくてはいけないのかなという思いがするのですが、その辺についてちょっとお考えを教えていただければと思います。","respondent":"秋山財政課長","answer":"義務教育施設整備基金の使い方ということですけれども、これで全部の改築を賄うということでは当然ありませんで、毎年毎年使っていく分もあれば、積み立てていく分もあるというものを含めて考えていますので、単純に今１校幾らぐらいかかって、１０校分だからこの金額というのは。","voiceIndex":92,"id":"exchange-051"},{"speaker":"大倉委員","kind":"意見","question":"これ全部、例えば３０億円丸々この基金からではないというのはわかっているのですが、そういった中でも本当にちゃんと１０年間で想定をしながら、今改築が行われている例えば芳水小学校とかを見ても、まだ擁壁の部分が多い学校もあったりする中で、ちゃんと積立てもしながら取崩しもしてという、うまく循環というか基金が回っていけばいいなとは思っているのですが。","respondent":"中山企画部長","answer":"そのことと、先ほどの一般財源を投入する部分と基金との関係を考えると、その１０年分で何十校ぐらい必要だということを、具体的にどこの学校も積み上げて基金が出しているものではないという説明が、ちょっと混同されてご理解されてしまっているかなという部分がありますので。","voiceIndex":94,"id":"exchange-052"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"基金のことなので、考え方をお伺いします。財政課とかが考えて、もう年数がこれぐらい来たから予想してざっくりいくのか、担当課、例えば義務教育施設なら教育委員会が、そこに耐震補強工事をやったから１５年で、学校などは順番がついている部分もあるのだけれども、そういうのをやって担当課が出してくるのか、企画財政部門で出してくるのか、そこら辺をちょっと教えてほしい。","respondent":"秋山財政課長","answer":"確かに委員がおっしゃるとおりに、平準化というものであれば、当面の何年か分という考え方もこれはあろうかとは考えてあります。その辺は今後どういう形になるのかということも含めて、ちょっと検討していかなければいけないかなと考えています。","voiceIndex":96,"id":"exchange-053"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"減債基金の話は、私が質問するかどうかは別としても、予算特別委員会なり何なりどこかで私はやるべきだと思っていて、だから私はこの１１１億円という根拠がやはり必要なのだろうと思って、そうするとさっきの１８５億円みたいな目安というのが出てきてしまうから、起債残高というのを持っていれば安全だろうと。平準化という話になると安全の話じゃないだろうと。","respondent":"中山企画部長","answer":"それにしても、それを額の積算としてきっちり合わせられるかというと、またどうしても大きな視点で備えていくという部分と、現実の積立ての部分ということになっていこうかと思いますけれども、ご指摘のことを踏まえてしっかり備えた対応はできるようにしてまいりたいと思います。","voiceIndex":98,"id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6000#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":40309,"voices":103}},{"id":"h28-20160121-18","meetingId":"h28-cm01","date":"2016年1月21日","dateIso":"2016-01-21","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ２時１５分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"それぞれ伺っていきたいと思います。そんなことも考えるためにも、この８万人の想定のイメージをどう捉えたらいいのかを教えてください。「今できることって何だろう」には、どうお答えしたらいいのかというのを、ちょっと質問になってしまうのですが、教えてください。もう１点、役立ち隊のところ。この説明でも、「メンバーの拡充を図り」となっていて、今後の目標値みたいなものはあるのでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長、伊崎子ども育成課長","answer":"ただ、区民の方から、今のところはそういった具体的なボランティアに関するお問い合わせはないのですけれども、もしお問い合わせがあった場合、お答えするとすれば、やはり、特に大会ボランティアは、おそらく語学力ですとか。この役立ち隊というのは、あくまでも子どもたちの自主性を大事にしながら育ててきているものですので、できれば行政主導ではなく、子どもたちの活動を行政が支援する形で継続していければいいと考えているところです。","voiceIndex":10,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今後。その、受講者も含めた把握です。登録。これは、さっきの話にもつながると思うので、続けていただきたいというか、ちょっと発展したほうがいいのではないかという思いで聞きました。これで区切ります。質問の仕方が難しいのですが。だから、組織委員会とのやりとりの中では、そういうやりとりを強く申し入れしてもいいのではないかなと感じたので、その辺のお考えを聞かせていただきたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長、河内協働・国際担当課長","answer":"都市ボランティアと大会ボランティアにつきましては、まだ明確なものが示されていない中で、区としても、いろいろ歯がゆい思いをしながら考えているところではありますが、委員ご指摘のことにつきましては、積極的に、東京都なり。先ほどの把握の件につきまして、ちょっと補足の説明をさせていただきたいと考えています。","voiceIndex":15,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私も、東京都のほうのパンフレットもいただいて、見てみたのですが、英検２級以上、ＴＯＥＩＣ５００点以上とかの要件があったりして。今回、ここにも説明にあるとおり、５回にわたって受けなければいけないというところ。ただ品川区で行うほうについては１回で、これは品川区の外国語講座を受けた方が、今回対象であったと。同じ東京都との関係で、どういうふうなくくりになっているのか教えてください。","respondent":"小川オリンピック・パラリンピック準備課長、河内協働・国際担当課長","answer":"おのずと東京都だけでは、やはり３万５,０００人という人数が確保できないということで、２３区並びに東京都内の市区町村のほうに、協力の依頼がございました。東京都に昨年末、確認したところなのですが、おおむね１万５,０００人程度の見込みであるというようなところが、言われたところです。これは、会場に限りがあること。","voiceIndex":18,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ご丁寧な説明、ありがとうございました。希望者の方が。で、区に協力を求められて、港区と品川区で先行されてやられたということで。今、現状では品川区内の大学、星薬科大学であるとか立正大学であるとか清泉女子大学とか、どうなのかなと思って見てみたら、ちょっとその中には、その２分の１の中には入っていなかったようなのですけれども。何かこの大学連携について情報があれば、教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"恐らく星薬科大学も確か入っていたのではないかと思います。区内の大学が入っているので、ちょっとほっとした記憶がありますので。そういったことで、区内の大学も、きちっとそれぞれの考え方を持って動いているというような情報は得ているところです。","voiceIndex":21,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後にちょっと１点だけ。これは非常に評価をされたということで、この動きが大きく広がって、先ほどの大学連携につながったということもあるみたいなのですけれども、これは教育委員会の中に入ってくるのかもしれませんが、こういう学校との連携、ボランティアというところからちょっと拡大してしまうかもしれませんけれども、こういったこと、何か動きがあれば教えていただきたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"私どもも教育委員会とは連携をしておりまして、東京都の教育庁のほうに動きがありまして、長野オリンピックに近いようなものを、具体的に考えてあります。","voiceIndex":23,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"詳しくは、多分、教育委員会のほうにお話が来ているかと思うのですけれども。先ほどもありましたけれども、一つのレガシーとして、ぜひそういったことも、今後の子どもたちが参加することに非常に大きな意義があると思いますので、進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"ご説明ありがとうございました。東京都の外国人おもてなし語学ボランティアの数字、３万５,０００人が目標ということで、わかりました。先ほど、あくつ委員からも質問ありましたけれども、この外国人おもてなし語学ボランティア、東京都でも品川区でもやっているのですけれども、この講座内容というのは、一緒なのですか。統一性を持たせたほうがいいかなと思ったので。その点。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"先ほども申しましたように、語学に関しましては、自己申告制ということがありますので、東京都のほうで独自にやっている語学講座というものはありますが、おもてなし講座に関しましては、区でやっているものも、東京都がやっているものも、全く同じでございまして。","voiceIndex":26,"id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"品川区内のボランティア・ガイドさんのご説明もあったのですけれども、こうした方々は、オリンピック・パラリンピックの際は、ご協力いただけるということになっているのでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"今年度４月１日より、品川区では、区長をトップといたしました、オリンピック・パラリンピックに関する推進本部を設置しています。","voiceIndex":28,"id":"exchange-008"},{"speaker":"筒井委員","kind":"質問","question":"ボランティアもそこの推進本部で統合して、うまく連携して活躍をされることを期待するというわけでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"各ボランティアにつきましては、それぞれの各所管のほうで育成をしたりですとか、活動をしていただいているところですけれども、全体の把握・調整、それから今後、本番までにまたいろいろな、新たな動きが出てくるかと思われますが、そういったことに確実に対応していくために。","voiceIndex":30,"id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"最初に、この平成２７年１２月１２日に行われた、もう既に実施されたものについて、こういう講座は大抵、参加された方からの反応といいますか、そういうものを聞いて次に活かしたりすると思うのですけれども、その辺の実績といいますか、そういうことを教えていただきたいのが１点と。その点、どういうふうに考えてらっしゃるのかということと。何かちょっと素朴な質問なのですが。３点伺いたいと思います。","respondent":"河内協働・国際担当課長","answer":"区といたしましても、先ほどちょっとお話ししたところと重複いたしますけれども、国際的な、外国人が来られるようなところを予想されるイベントに関しまして、実践の場として提供しながら、そういった経験を踏まえて、こう言ったほうがうまくいっただとかというところを。","voiceIndex":32,"id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"今、お答えの中で、「放っておかれるのが一番困る」ということで、ふと思いついたのですが。例えば、こういう、オリンピック・パラリンピックの最中の、もし災害が起きたときの情報。なので、こういう講座の中で、やはりその災害時ということも想定する必要があると思うのですけれども、その点については現状ではいかがなのでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"もちろん、会場区です品川区といたしましても、何かしらかかわる必要になってありますので、そういった細かい情報を得つつ、そういった情報をキャッチしつつ、品川区としても、何ができるかということを、できるだけ早目に検討していきたいと考えています。","voiceIndex":34,"id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今、区内のボランティア活動や、またこれからボランティアに携わってもらう人を育てていくというようなお話があったのですけれども。こういったボランティア全般を見て、区の中で、やはり区民の皆さんが、ボランティアに自主的に参加していくというところでの課題などをどう見られているのか、もし把握されていれば、教えていただきたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ちなみに、東京都のほうで調べておりますボランティアの方々の行動者率というものがありまして、２０１１年度の実績は、東京都のボランティア行動者率が２４.６％という統計が出ておりますが、２０２４年度には。","voiceIndex":37,"id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり日本は、このボランティア文化というのですか。ヨーロッパ諸国とか世界的に見ても、あまり、なかなか浸透していない国というふうに言われがちです。だと思うのですけれども。こういった、過去の大会、ロンドンだったり、そういったところでは、やはり、ボランティアの中心というのは、若い世代になってくるのでしょうか。どういった方々が中心に取り組んできたかというのは、わかるでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そういった中で、２０２０年の東京オリンピック、どう、いかにボランティアに活躍していただくかということが重要だと思いますので、それについては、まだまだおもてなし語学ボランティアも始まったばかりですので。","voiceIndex":39,"id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、先ほどほかの委員からもあった、この災害時の対応について、今、大会組織委員会のほうからもいろいろ来ているということですけれども、こういった災害時のボランティアの行動という講座なども、そうしたら、開いていくということに、そういう検討もされているということですか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"まだ具体的に災害時のボランティアというところまでは行き着いてございませんが、災害時については当然、品川区もいろいろな形でかかわる必要が生じてくると思われますので、まず区の方で、きちんとそういった位置付けとか動きですとかを確認しつつ。","voiceIndex":41,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"いろいろ出ていたのですけれども、大会ボランティアそのものでも８万人で、それプラスその周辺のボランティアをする方も当然いらっしゃると、そういう捉え方でいいのですよね。大体その辺の、この８万人の中身、どういうふうに考えたらいいのかというのを、ちょっと１つ教えていただきたいのと。その３点、教えてください。","respondent":"小川オリンピック・パラリンピック準備課長、河内協働・国際担当課長","answer":"８万人の中身につきましては、先ほども申しましたとおり、こちらのほうで、大会組織委員会のほうで、具体的な数字が示されているわけではないので、ちょっとなかなかご説明が難しいところではありますが。そういうところをしっかり押さえながら、次年度以降も講座を展開していきたいという考えです。","voiceIndex":44,"id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"私、ちょっと一番知りたかったのは、全体的にどういうふうな体制があって、その一つがこのボランティアなのだけれども、その全体的なところというのがなかなか見えてこない。５年先なので。ちょっと全体のところのあれを教えていただければ、ぜひ紹介していただきたいのですけれども。同時に、正副の委員長さんにお願いしたいのは、今、どういうところがあって、どこまで到達されているのか、全体的に。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"基本計画自体は、もうこのぐらい分厚い本なのではありますが、委員ご指摘の、いろいろなさまざまな課題について、具体的には５２ほどあるのですけれども、そちらのほうが、一つ一つ丁寧に記載されてありますので、ぜひそちらをご参照いただければと考えています。","voiceIndex":47,"id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"どうも済みません。なかなかちょっと、出てくる項目がぽつんぽつんとなっているので、ちょっとわからずに、そんな質問をさせていただいたのですけれども、ありがとうございました。改めて、過去の資料なども振り返って、もう少し整理をしたいと思います。ぜひ、今、委員長がそうおっしゃってくださったので、それは本当にうれしく思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-017"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"特に、３.１１の災害のときにも、本当に多くの方がボランティアに駆けつけたけれども、実はできなかった理由の一つとしては、地元が受け入れ態勢が万全ではなかったということで、気持ちはあったけれどもできなかったという方も多く存在をしてしまったというのは、僕はこれを一つの教訓として受け止めていかなければいけないのではないかというふうに思うし。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ただ、区といたしましては、今、気運醸成事業をさまざましておりますので、そういったイベントでの、ボランティアでかかわっていただくとか、そういったことについては考えておりまして、例えば、昨年もホッケー教室などもいたしましたが。","voiceIndex":51,"id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6486#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":26498,"voices":58}},{"id":"h28-20160122-10","meetingId":"h28-cm01","date":"2016年1月22日","dateIso":"2016-01-22","committee":"議会運営委員会","time":"午後 １時００分～午後 １時４１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の３、区議会防災訓練の実施結果","agenda":"の３、区議会防災訓練の実施結果","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"できるだけ参集するということなのですが、おそらく参集時間のばらつきもあるだろうし、現実的に、訓練として集まってくれというのは、手法としてはいいとは思うのですが、ただ、現実を考えたら、ちょっとどうなのかなという疑問点が残ります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"資料ナンバー２なのですけれども、第３回になっているのですが、私の記憶がもし間違っていたら言ってください。区内の公共施設を地図上で見て、本部員が確認したほうが機能がよくなるのではないかとか課題があったのが、今回の平成２７年１２月５日にやったときに、改善された点とかがあれば教えていただきたいのです。","respondent":"原区議会事務局長","answer":"あわせて、今回、手前みそになるかと思って、あえて説明しませんでしたけれども、区議会事務局の職員のまとめのところに、前回の訓練を受けて、白地図であるとか事務用の備品、張り紙も一部、もうすぐに準備して、いつも棚のところに置いて、災害があったら。","voiceIndex":16,"id":"exchange-002"},{"speaker":"塚本委員","kind":"意見","question":"私も、これは家で待ち構えていたのだけれども、やはり聞こえなくて、もしかしたら、私だけが聞き逃したのかと思ったら、結構、そういうのがあったのだと思って、ＩＣＴ導入になった場合に、災害対応を含めた対応を考えているということが裏面に書いてありますけれども、防災無線だけではなくて、ＩＣＴ導入のときに災害発生時を、ＩＣＴを導入するときにも、そこを考えていただければと思います。","respondent":"原区議会事務局長","answer":"先ほどの塚本委員のＩＣＴのところについては、それも含めて、何らかの形がとれるかどうか、ちょっと検討をしてみたいというふうなところです。","voiceIndex":18,"id":"exchange-003"},{"speaker":"あべ委員","kind":"質問・要望","question":"一部、繰り返しになりますけれども、今回、私、現場のほうと拡大本部のほうと、一度の訓練で両方見させていただいて、非常にいろいろと気付かせていただいて、よかったと思います。それで、先ほども少し出ていました。改めて、やはり本部に行ってみないと気付かないことはいろいろあるので、今後の訓練では、ぜひ、全会派に本部を体験していただくということを積極的にやっていただきたいと切に願います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-004"},{"speaker":"飯沼副委員長","kind":"提案","question":"この本部の設置のところで、議会の使命を果たすというところにおいて、災害時も変わりがないということで、今回の要綱の体制について、以前にも改善点を述べさせていただいたのですが、いつ、どこでというのは、まだこれからだと思うのですけれども、ぜひ全議員を本部員にしていただきたいということと、各会派の代表を本部役員にしていただきたい、あと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5166#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":13591,"voices":36}},{"id":"h28-20160216-10","meetingId":"h28-cm02","date":"2016年2月16日","dateIso":"2016-02-16","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時４６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２８年第１回定例会","agenda":"平成２８年第１回定例会","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"陳情の参考送付についてですけれども、特に陳情第２号と第３号については、今ご説明にありましたように、国に対する意見書を提出するという形ではありますけれども、区民の方から送られてきているということ、それから全国的に一斉に各自治体にまいているというものではなく、内容的にも、まさに品川区に対して求めているという内容であることなどを考えると、一律に参考送付にすることはなくて。","respondent":"大沢議長、渡辺委員長、原区議会事務局長","answer":"なぜ出したかというのは、意見書を求める原理原則に従ってということです。それしか言いようがありません。問いに対して、今お答えをいただいたと思いますが、重なってしまうかと思いますが、今のご意見について、局長。そういった意味では、過去のことをご案内させていただき、今回のことについても。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"申し合わせ確認事項によると、陳情の取扱いという項目があって、さまざま書いてありますけれども、これが参考送付になったというのは、議長権限により参考送付できる陳情例というところの意見書等を求める陳情というところで、議長が参考送付という取扱いにしたのではないかと思うのですけれども、そういうことであっても、陳情の取扱いについては、議会運営委員会の意見を求めることが適当と認めるものは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-002"},{"speaker":"本多委員","kind":"意見","question":"まさに陳情の議会運営委員会での取扱いをどうするかという投げかけについては、検討をしてほしいという申し入れについてはわかります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-003"},{"speaker":"塚本委員","kind":"提案","question":"それを今この場で議論しましょうという提案をされているのですけれども、この内容を一読して、あえて議長の判断を覆してまで審議するものに当たるどうかというと、そこまでのものではないかという思いがいたしておりますので、議長の判断のとおりで進めていいのではないかという意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-004"},{"speaker":"須貝委員","kind":"提案","question":"今回、議会運営委員会の中でそういう提案をされたということは一理あると思うのですが、それはそれで、また別の場でしっかりやらなければいけないということもあると思います。ただ、今この場でどうしよう、こうしようとなると、少し問題があるのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-005"},{"speaker":"あべ委員","kind":"意見","question":"基本的に陳情を出すか、請願を出すかというのは、私は、どちらも区民の権利であると思っているので、どちらにすべきだったというようなことは、議会としての発言としてはどうかと思います。それは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-006"},{"speaker":"あべ委員","kind":"意見","question":"やはり、区民の方が直接持って来られた陳情に対して、機械的にと言ったら言い過ぎかもしれませんけれども、参考送付にするということは、より広く区民の皆さんの意見を区議会の議論に乗せていこうという考え方から言えば、私は、ちょっと機械的過ぎるのではないかと感じております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-007"}]},{"id":"topic-02","title":"議会報告会の実施","agenda":"議会報告会の実施","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"内容については、会派としても賛成しております。ワークショップの議題について、いつごろまでに決まることになるのでしょうか。もし目途があれば教えていただきたい。あまり直前だと、ちょっと困るというのがあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-008"},{"speaker":"たけうち副委員長","kind":"意見","question":"次回の２月１９日の住民参加分科会までに、各会派で案を持ってきてください。私の思いとしては、２月１９日に粗々固めたいと思っていますが、厳しければ、もしかしたらもう１回くらい持ち帰りになる可能性はありますけれども、いずれにしても、３月中旬前までには決めていかなければいけないと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-009"}]},{"id":"topic-03","title":"東京都後期高齢者医療広域連合議会の報告","agenda":"東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"たけうち副委員長","kind":"質問・要望","question":"(9)その他の２番目の報告で、傍聴席の手すり等の設置の対応をしたということですけれども、４月１日から障害者の関係の法律が変わって、合理的配慮ということになって、今回、総務委員会でもいろいろ出されていると思うのですが、一定程度やってこられたとは思うのですが、議場、委員会室を含めて、議会として何か合理的配慮で必要なものがないのかどうかということを、今でなくて結構ですが。","respondent":"原区議会事務局長","answer":"２点目の関係ですけれども、この間、区議会事務局、あるいは各議員からの提案等々がございまして、さまざま障害のあるなしに関係なく、傍聴等々をしていただけるような環境整備ということで、物理的な配慮、それから窓口での対応等々の配慮ということでやってきたところです。","voiceIndex":58,"id":"exchange-010"},{"speaker":"飯沼副委員長","kind":"提案","question":"北朝鮮の弾道ミサイル発射の強行に対して、品川区議会として抗議の決議を上げてはどうかと、提案をしたいと思います。弾道ミサイル技術を利用したいかなる発射も行わないことを求めた国連安保理の決議にも反しますし、６カ国協議の共同声明や日朝平壌宣言に反するものであるといった立場で、ぜひ厳重に抗議したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-011"},{"speaker":"本多委員","kind":"提案","question":"今の提案を受けて、私は平成２１年に区議会議長に就任させていただきましたときに、北朝鮮が核実験をやって区議会が抗議文を出すという動きがありまして、当時の書記長、金正日宛てに区議会議長名で抗議文を出すのに議長の判を押すのが、議長になって最初の仕事だったのを思い出しました。確かに重要な提起ですので、会派に持ち帰りとさせていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-012"},{"speaker":"塚本委員","kind":"意見","question":"大前提としては、そういう抗議、または決議をやっていくことに関しては、前向きに検討すべきことだと思いますけれども、文言その他、今あったいろいろなことへの配慮もしながら、どのタイミングで、どういう形かは、一たんは会派に持ち帰って検討したうえで形にしていけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"軍事的な技術をいろいろな形でいろいろな国が誇示する形で、その全てに一つ一つ出していくのか、品川区としては、特に核実験に係わる部分で対応していくのか、そういったことも含めて、もし過去にミサイル関係では出していなかったことの判断の基準がわかれば、事務局にお伺いしたい。それから、前回、１月のときには、区長の抗議文に倣った部分もあったと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"私はやはり、国民、都民、区民から考えれば、抗議文を出したほうがいいとは思います。ただ、品川区議会に議長がいらっしゃるわけですから、我々の代表ですから、議長にいろいろな意味で考えいただいて、どういう対応がいいのかお任せしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5168#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":21781,"voices":75}},{"id":"h28-20160218-10","meetingId":"h28-cm02","date":"2016年2月18日","dateIso":"2016-02-18","committee":"議会運営委員会","time":"午前１１時４０分～午前１１時４５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、北朝鮮のミサイル発射に対する抗議","agenda":"の１、北朝鮮のミサイル発射に対する抗議","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"持ち帰りということで会派内で話をさせていただき、議長のほうで改めてしっかりと判断をしていただきたい。決議ではなくということでお願いします。抗議の形で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":3,"id":"exchange-001"},{"speaker":"塚本委員","kind":"意見","question":"北朝鮮のこのミサイル、いわゆる事実上の弾道ミサイルの発射ということについては、これはやっぱり今回に限らず、この間、何年かにわたってずっと反対、抗議すべきということについては、ずっとそういう姿勢で我々の会派はありますので、今回、こういうことに関して、今までやってこなかったということはあるのですけれども、何かしらの抗議を。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"あべ委員","kind":"意見","question":"そういった意味でも、とりあえず前回並みの扱いにするかどうかも含めて、一旦議長判断も含めてという形に持っていくと同時に、やはり今後どういうような場合には、たとえ臨時会を開いてでも決議を出すのだとか、こういうときには抗議文で対応するのだということなども含めて、何らかのちょっと目安みたいなものも少しずつ固めていけたらいいなとは思っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5170#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":1834,"voices":15}},{"id":"h28-20160219-3","meetingId":"h28-c-budget","date":"2016年2月19日","dateIso":"2016-02-19","committee":"予算特別委員会","time":"午後３時４０分～午後３時４７分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"つる副委員長","kind":"意見","question":"ただいま皆様のご推挙により副委員長の大任を拝命いたしました。石田秀男委員長のもと、しっかりと、今、委員長のほうからもご挨拶ございました活発な議論、そして実りある委員会としてまいりたいと思います。そのためのしっかりと副委員長としての職務を全うしてまいりますので、各委員の皆様のご協力をどうかよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1034#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":2085,"voices":17}},{"id":"h28-20160222-6","meetingId":"h28-cm02","date":"2016年2月22日","dateIso":"2016-02-22","committee":"区民委員会","time":"午前１０時００分～午後 ２時００分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"質問","question":"今回は納税証明書と住民票の写し、そして印鑑登録、この３つの種類がコンビニ交付になるわけですけれども、この３つでスタートするけれども、今後以降さらにこういう業務を拡大する計画、思いはあるのか、その辺を２点伺いたいと思います。","respondent":"井浦戸籍住民課長","answer":"今後の拡大の可能性といたしましては、戸籍証明についてはシステム的に現在でも実施可能ですが、現在は区としては考えていないです。","voiceIndex":6,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、やはりこのコンビニ交付というのはやめていただきたいと思います。現実的にどこでも自分のナンバーを提供しなくてはいけないという仕組みになっているわけです。したがって、態度も言いますけども、この条例については、後半のこの２つの２番以降の問題については賛成の立場ではあるのですけれども、これに賛成する以上に大問題がマイナンバーだ、コンビニ交付だと思いますので、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"マイナンバーカードを利用してのコンビニ交付は、どのくらいの利用を見込んでいるかというのを教えていただきたいのですが。","respondent":"井浦戸籍住民課長","answer":"当初の平成２８年度につきましては、１０％の利用を見込んです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"松永委員","kind":"質問","question":"私からは、まずこの印鑑登録証というラミネートされたものがあるのですけれども、それはコンビニでも使えるのかどうかちょっと伺いたいのが１点です。もう一つは区の窓口との違い。例えばどのくらいの手続時間。要するにコンビニでやるのと区の窓口でやるのでは、時間がどのくらい短縮されるのか、その点について伺いたいと思います。","respondent":"井浦戸籍住民課長","answer":"区の窓口とのスピードの違いですが、やはり繁忙時間帯等、窓口が混むこともあります。それに比べますと、コンビニの多機能端末機につきましては常時お１人いるかいないかというところですので、かなりスピードアップも図れるのではないかと考えています。","voiceIndex":11,"id":"exchange-004"},{"speaker":"松永委員","kind":"質問","question":"その短縮というのは、要は、今窓口で大体１人何分かかる、ではコンビニだったら何分という、具体的なのを教えていただければ。","respondent":"井浦戸籍住民課長","answer":"現在平均いたしますと、印鑑証明については３分ほどで窓口でも交付という形で運用されているところです。コンビニ交付につきましては１分前後で交付可能と考えています。","voiceIndex":13,"id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問","question":"あとこの２番の建築物のほうなのですが、長期優良住宅については、先ほどもありましたけれども平成２０年からということで、品川区でも毎回予算書にも出てくると思うのですが、何かあまり実績として伸びていないような気がするのですけれども、この辺のこの間の状況、何件ぐらい申請、認定があるのかというのを教えてください。","respondent":"井浦戸籍住民課長、鈴木建築課長","answer":"１点目の全国の約５万店舗です。こちらでご案内してあります４社につきましては、全国どこのコンビニでも区民の方はマイナンバーカードを利用してコンビニ交付が可能です。長期優良住宅の認定申請の実績ですが、平成２２年度から受付を開始しておりまして、例年７０件から９０件程度というところで、今月現在時点で、トータルで４８９件という実績です。","voiceIndex":15,"id":"exchange-006"},{"speaker":"たけうち委員","kind":"意見","question":"わかりました。コンビニのほうは、そういう面では非常に利便性が高まるなという感想です。長期優良住宅のほうは、そうすると、今回この増改築もという中で、予算書を見ればよかったのですけれども、予算的には新年度、どれくらい見込んでいるのかがわかれば。","respondent":"鈴木建築課長","answer":"法律の改正を見込んでの予算上の措置は、今のところしてございませんが、見込み的には、全体の新築に対する増改築の割合というのが大体２％程度ですので、年間１件あるかないかというところで見込んでいるところです。","voiceIndex":18,"id":"exchange-007"}]},{"id":"topic-02","title":"第２３号議案、品川区町会および自治会の活動活性化の推進に関する条例","agenda":"第２３号議案、品川区町会および自治会の活動活性化の推進に関する条例","exchanges":[{"speaker":"田中委員","kind":"質問","question":"幾つかあるので、少し分けて質問します。そして、区政協力員、町会長にお願いしているわけですけれども、その区政協力委員会というのですか、その発言は町会を背負ってではなく、個人の発言でいいというように聞いています。しかし、それが町会・自治会が条例で位置付けられることで、区政協力委員としての立場がどのようになるのかということをまずお聞かせください。","respondent":"久保田地域活動課長","answer":"第４条で町会・自治会の位置付けや役割を定めてありますが、具体的にこういうことをやりなさいとか、こういうことをやらなければならないということの規定ではございませんので。","voiceIndex":39,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"最後のところをもう一回聞きたいのですけれども、個人の発言ではなくて、地域を背負った発言ということになるのですか。","respondent":"久保田地域活動課長","answer":"ちょっと説明が足りなかったのですけれども、会長が個人の思いで発言をされているのではなくて、やはりきちんとその地域の課題として、それぞれの町会・自治会や連合会の中で議論してきたものを発言されたこととして区のほうでは捉えてありますので。","voiceIndex":41,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"２０１５年３月５日の予算特別委員会のときに、ネットからの「参加しにくい、できないという人たちの声をどのように条例案に反映させていくのか」という問いに、課長が「次年度もこの会議を進めていきますので、いろいろな方のご意見を伺っていきたいと思っています」と答弁されているのですが、どの場面でどのような方たちから意見を聞いたのか、それらの意見をどの部分に反映されているか教えてください。","respondent":"久保田地域活動課長","answer":"何か参加をすると、役員を任されるのではないかという声もよく聞くということで私ども聞いてありますので、そういうことがないように、理解を求めながら相手の方とよく話をしていきたいと町会・自治会側はおっしゃってありますので。","voiceIndex":43,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"前文を読んで、それからずっと条文も見たのですけれども、まず前文のところでは、品川区が古くから栄えて賑わってきたのは共助の精神で、町会や自治会によって育まれてきているのだと冒頭書いてあるわけです。そういう角度で、やはりこの条例が本当にそういう皆さんの支えになるのかどうか、そういうところをしっかり見ていきたいと思っているので、質問させていただきたいと思います。","respondent":"久保田地域活動課長","answer":"そうした意味では、私どもは町会・自治会の皆様がなければ、行政としてもなかなか立ち行かないということも認識していますので、こういった条例をつくることによりまして、町会・自治会の活動というものに対して、区民の方々にもう一度注目をしていただきたいと。","voiceIndex":45,"id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"そういうところに対して、さらに共助の精神を持って今まで以上にという点では、今やっているいろいろな活動については、ちょっと言い方は悪いですけれども、区としては不十分な部分があるのかと見ているのかと、そういうことを思ってしまうような印象を私はちょっと持ったので、改めてそこについてどのように見ておられるのかを伺いたいと思います。しかし今まで以上に力を合わせてと書いてある。","respondent":"久保田地域活動課長","answer":"もう十分によくやっていただいているということで、感謝の気持ちを持って皆様方の活動を私どもも支えているということが私どもの認識としていますので、委員からお話がありましたように、不十分だからこの条例を書いて。","voiceIndex":47,"id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"改めてそこを確認したいと思います。あるいは、行政との関係ではそういう枠組みをつくっていきたいと思っておられるのか、そのあたりを確認したいと思うのです。いや、とんでもない、そのようなことは全然やっていないということであれば、それはそれでおっしゃっていただきたいのですけれども、そういう不安があるということについてどのように区は見ているのかというところを伺いたいと思います。","respondent":"久保田地域活動課長","answer":"第４条等の条文の中等にも、町会および自治会の自主性および主体性を尊重しなければならないということもきちんと明記させていただいてありますので、そういう意味では将来にわたりましてもそのようなことがないように、私どもは十分注意をしていかなければならないということを。","voiceIndex":49,"id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"だからしつこくあのような質問をしたわけですけれども、お願いする仕事に対しては、自主的な取組みについての財政的な支援というのはこれからの課題でやっていこうというご答弁なのでそれはそれとして伺っておきたいけれども、今やっている仕事にプラスアルファでこの条例がつくられることによって増えるということは、ないと見ていいのですかというのをさっき質問したつもりなのですけれども。","respondent":"久保田地域活動課長","answer":"私ども、逆に答申でいただいている三本の柱の３本目でありましたように、区からの依頼業務が多いということ、例えば区や警察、消防、その他いろいろな団体からの依頼業務が多いので、それの負担軽減を図らなければならないと考えています。","voiceIndex":51,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"仕事は増えないと、今、むしろ負担軽減したいのだという答弁です。しかし、高齢者の見守りという点では、これからいろいろな課題も出てくる分野ですから、そこのところでいろいろな支え愛・ほっとステーションでしたか、そういうのが始まっています。行政の仕事は行政としてしっかりやるという態度にしっかり立っていただきたいということを強く求めたいと思います。改めてその点について答弁してください。","respondent":"久保田地域活動課長","answer":"支え愛・ほっとステーション等につきましても、身近な地域で福祉の相談等に応じることができるということは、ある意味ではこれは町会・自治会にとりましては負担が軽減されるというものの一つにはなるかなと思ってありますので、身近な地域で相談機能等があるということは。","voiceIndex":53,"id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"確かに身近に相談できる機能は必要だけれども、しかしやはりここは自治体がやるべき仕事は、品川区が行政としてやるべき分野だと思います。そこのことは指摘をしておきたいと思います。それから、もう一つ伺いたいのですけれども、第５条に「地域コミュニティの活性化に資する施策を総合的に策定」と書いてあるのですけれども、施策とは例えばどのような内容なのか、それを伺いたいと思います。","respondent":"久保田地域活動課長","answer":"これ以外にも地域コミュニティの活性化のために必要な施策というものはいろいろありますので、そういったものに新規の事業があれば、それは町会・自治会ともいろいろ話をしながら、区の責任において実施をしていきたいと思ってあります。","voiceIndex":55,"id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"第５条の第２項に「区民が主体的に参加することを促進するために必要な支援を行わなければならない」と書いてあるのだけれども、これは町会・自治会の加入促進なのかなと読んでいて想像するのですけれども、そういうことなのかということと、まだほかにあれば教えていただきたいと思います。この「資する施策」というのはどのようなことなのかを伺って、終わりにしたいと思います。","respondent":"久保田地域活動課長","answer":"第５条の第２項ですけれども、委員から話がありました主なものとしましては、加入促進活動というものが主なものだと思います。","voiceIndex":57,"id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"第１１条に、全部読まなくてはだめですよね、「宅地建物取引業法第３５条第１項各号に掲げる事項の説明その他当該住宅についての説明を行う際に、当該住宅の存する地域において活動する町会および自治会の活動に関する情報を提供するように努めなければならない」とあるわけですが、ここに掲げられている宅地建物取引業法が１４項目もあるのですけれども、その中でこの条例も加えるということなのでしょうか。","respondent":"久保田地域活動課長","answer":"住宅購入者のほうの重要事項説明については、私どもとしましては宅地建物取引業法の中で、住宅販売をする方々に、新たに町会・自治会の情報提供をしていただきたいと思ってありますので、加えていただきたいと思ってあります。","voiceIndex":59,"id":"exchange-018"},{"speaker":"田中委員","kind":"質問","question":"事業者の方の了承についてなのですけれども、条例を提出後に話をするということだったのですけれども、その話をするのは、町会・自治会の方が事業者の方に条例のことを説明するのではなくて、行政のほうからきちんと条例の説明を行うのでしょうか。","respondent":"久保田地域活動課長","answer":"私どもが責任を持って相手の団体に説明はします。","voiceIndex":61,"id":"exchange-019"},{"speaker":"たけうち委員","kind":"質問・要望","question":"２３区の中では高いほうなのですけれども、その中で何か区として目標ではないのだけれども、６５％にするだとか、何かそういうのがあるのかどうか教えてください。それから最後ですけれども、この名和田委員長のお話を２年ぐらい前に伺う機会があったのですが、名和田先生は、僕のイメージでは比較的、地区分権というか、今、地方分権とかいろいろ言っていますが、いわゆる町会が加入率を高める。","respondent":"久保田地域活動課長","answer":"１点目ですけれども、アクションプランの取りまとめについては、現時点では特に予定はしてございません。この２年間の成果を報告書に取りまとめる等は、今、考えてありますけれども、アクションプラン等の取りまとめは予定はございません。","voiceIndex":63,"id":"exchange-020"},{"speaker":"たけうち委員","kind":"確認","question":"あとそういう面で、町会・自治会のあり方と区との協働に関する調査研究委員会は、もう、そうすると１回延長したと思うのですけれども、もう終わってしまったということですか。まだやるのか、そこを確認したいのと、あとはそれとも連動するのでしょうけれども、やはりいろいろ懸念があるのは、いろいろな事情はあるにせよ、そうは言ってもなかなか町会・自治会に入りづらい、もしくは入りたくない。","respondent":"久保田地域活動課長","answer":"地域にもいろいろな考えを持っている方がいらっしゃいますので、こういった条例をつくるということは、町会・自治会側のほうにもそうした方々へのご配慮等も必要になってくるということは、私どもも認識していますし、今回この意見交換をしていく中で。","voiceIndex":65,"id":"exchange-021"},{"speaker":"田中委員","kind":"確認","question":"確認してもいいですか。ごめんなさい、聞きもらしてしまったのかもしれないのですけれども、財政上の措置のところで、会計の報告をきちんとしなければいけないと思うのですけれどもという質問にもう一回答えてもらってよいですか。今の町会・自治会の現状と照らし合わせてその辺は大丈夫かということと、町会・自治会によっては負担になってしまうのではないかというところです。お願いします。","respondent":"久保田地域活動課長","answer":"区から助成金等を出していますので、時期が来ましたらば、年に１回ですけれども、その会計報告についても報告をいただいてありますし、その当該年度の事業計画についても区のほうに提出していただいているですので、会計はきちんとできていると認識を持ってあります。","voiceIndex":67,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"その会計報告というのは、同じ町会・自治会の方たちが見られるのですか。","respondent":"久保田地域活動課長","answer":"会計報告ですので、きちんと総会等を経て決定していると認識していますので、町会・自治会の会員の方々にも公開はしているものと思ってあります。","voiceIndex":69,"id":"exchange-023"},{"speaker":"松永委員","kind":"確認","question":"確認で３点伺います。第１３条に関して、もし守られなかったら、区の対応について伺いたいと思います。もう一つは、その第１３条の中に、既存のマンションに地域連絡調整員がいないから第１３条ができたということでよろしいのでしょうか。３点目が、第１４条に関して、掲示板について新築だけなのか、それとも既存のマンションについても含まれているのか伺いたいと思います。","respondent":"久保田地域活動課長","answer":"第１４条に関しましては、これは新築だけではなくて既存のマンションの中でも、例えばそういう建替えだとか改築ですとかがあれば、そういった中でこういったものは取組んでいっていただきたいと思いますし、掲示板の設置だけではなくて。","voiceIndex":71,"id":"exchange-024"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"増えていません。なぜならば、掲示板一つ張る量にしても、回覧板を回す量にしても、間違いなく減っています。区からの依頼があるのも事実です。区民に対して責務を背負わせるわけではないですし、当然その責務というのは区は負うのでしょうけれども、町会・自治会、区民に対してそれを求めるわけではないですから、そこは相当自由度が高い条例になっていると思います。その辺の仕組みを教えてください。","respondent":"久保田地域活動課長","answer":"この第１３条ですけれども、条例では地域連絡調整員の選任をしなければならないという規定だけなのですが、私ども、今イメージとして考えていますのは、開発指導の関係で、マンション等を建てるときには都市計画課のほうに事業者が来ますので。","voiceIndex":73,"id":"exchange-025"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"それで町会・自治会の方々が一番懸念されているのが、例えばそういうのが選任されたところで、向こうがすり替えてくる可能性も、よく１年で交代するとかいう話も聞きます。そういうことがないような仕組みづくり、この説明のときに、しっかり変更の場合は速やかに提出をくださいとか、かなりここをきっちりやっていただきたいというのを要望するのですけれども、その辺はやっていただけますか。","respondent":"久保田地域活動課長","answer":"会社ですので、人事異動ですとかいろいろある中で、担当者がかわるという可能性もありますので、かわった際には変更の届出も出してくださいということは求めていきたいと思ってあります。","voiceIndex":75,"id":"exchange-026"},{"speaker":"南委員","kind":"確認","question":"私はむしろ増えていると思っていたのですけれども、区が昨年提供してくれた資料を読むと、平成２３年度からの五、六年間の委託している事業の一覧表については平成２３年度からずっと継続されているということなので、その限りにおいては減ってはいないというか、同じ仕事量ということがあるのではないかと思っているのですけれども、もう少し前から見ると。","respondent":"久保田地域活動課長","answer":"私どもは減っていると認識はしています。","voiceIndex":77,"id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"その辺はどうなのですか。繰り返しだけれども、さっき統合チラシとかポスターのそこだけではなくて、いろいろな種類、いろいろな項目でのお願いしている仕事については、むしろ拡大しているのではないかと私は思ったので、さっきそのように質問したのですけれども、いかがなのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-028"},{"speaker":"渡部副委員長","kind":"質問","question":"町会・自治会が２０３団体あって様々な事業をなさって、今の高齢者の見守りというのは手挙げですから、別に手を挙げなければやっていないです。区にやれと言われてやっているのではないです。ですから、南委員のお話で言ったら仕事など雪だるまのように増えていくわけで、減ることはなくなるのです。逆に、町会・自治会が手を挙げてどんどんやります、やりますというところはやればいいのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-029"},{"speaker":"南委員","kind":"確認","question":"そのことは全然否定しない、そういう事実になっているということは改めて確認したのですけれども、しかしこれから高齢者の見守りだとか、団塊の世代が高齢化していく中で、そういうのが大事だという認識がまちの中にもいっぱいあるではないですか。増えているわけでしょう。そういうことに対して、やはりもうすごく苦労しているところは事実としてあるわけですから、そこのところをちょっと言ったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-030"},{"speaker":"南委員","kind":"意見","question":"けれども大事なことは、やはりいろいろな地域の町会・自治会の皆さんの荷が、意識はもちろん前向きに捉えていただいて頑張ってくださっているのですけれども、期待されるのは非常に多いというところがあって、それを受けてはいくけれども、なかなか現実的には大変なことなのだろうとちょっと思っているので、そういうところに対しての捉え方、行政の側の見方。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"最後に意見を言っていいですか。結論的には反対です。その理由というのは、さっきも繰り返し言っているけれども、行政が支援するのは大事だと思っています。それは繰り返し言っていることです。そういうことで、私はやはり任意団体というところをしっかりと改めて確認をして、必要な支援はするけれども、しっかりと仕切っていくという態度が行政の側で求められるのではないかと思います。だから反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-032"},{"speaker":"田中委員","kind":"意見","question":"ちょっと意見を言わせていただいて、町会・自治会の活動は大切だと思います。決して町会・自治会の負担が重くなり過ぎることのないように、個々の町会・自治会の状況に合わせた活動の自由と、参加する個人の自由は担保されるべきだと考えています。その２つを前提にして賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-033"}]},{"id":"topic-03","title":"第２５号議案、品川区消費者センター条例の一部を改正する条例","agenda":"第２５号議案、品川区消費者センター条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"平成２１年に法律が制定されたということなのですけれども、それ以前に品川区が置いていたことは評価していきたいと思っているのですけれども、配置をしていたことのその思い、そのあたりがどうだったのかをひとつ教えていただきたい。","respondent":"山崎商業・ものづくり課長","answer":"かれこれ３５年前というようなことで、こうした品川区の行政の中で、消費者被害の防止などについて区のほうの施策の中に取り込んでしっかり対応してきたということと、あと国のほうの国民生活センターが近接している関係で、先ほどそちらの検定試験を受け。","voiceIndex":101,"id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"相当前から品川区がこういう消費者相談コーナーを配置していたということは、本当に評価をしていきたいと思っているし、いろいろな団体の方々が集まって団体同士の連携プレーもとれていると私も思っておりますので、品川区の早い時期からのそういう態勢がそういう事実をつくっているのかなと思っているのですけれども、批判するつもりは全然なくて評価する意味でも。","respondent":"山崎商業・ものづくり課長","answer":"区の様々な事業につきましては、１０年を一区切りの長期基本計画というものが一番計画行政の骨子としています。","voiceIndex":103,"id":"exchange-035"},{"speaker":"田中委員","kind":"質問","question":"それがどうしてその火曜日になったのかということと、日曜日にしか相談に行けないという方はどうするのかということと、消費者センター所長を置くことにより、今とどう変わるのかということを教えてください。","respondent":"山崎商業・ものづくり課長","answer":"やはり仕事を終わった時間で直接相談をということになりまして、月１回午後７時までという夜間での対応をしようということで、第４火曜日と定めております。","voiceIndex":105,"id":"exchange-036"},{"speaker":"たけうち委員","kind":"意見","question":"ちょっと聞き逃したのかもしれないですけれども、第４条を第１０条とすると、もとの４条、さっきもおっしゃったかもしれないですけれども聞き逃したので、もう一回、どのような内容だったのか。","respondent":"山崎商業・ものづくり課長","answer":"したがいまして、平成２８年６月１３日までですが、政令で施行日のほうが平成２８年４月１日ということになりました。それは、２年の間に施行を消費者庁もにらみながら、それぞれの自治体の対応具合を見ていたと聞いてあります。","voiceIndex":109,"id":"exchange-037"},{"speaker":"たけうち委員","kind":"意見","question":"第４条を第１０条とするとあるので、第４条をちょっと知りたかったのです。それと、現場のほうは、そうすると品川区は実質もう整っていたのでいつでも条例対応できたと思うのですけれども、いわゆる２年以内ということは、逆に言えば早くてもいいということだったのか、それとも政省令で平成２８年、今年度の４月１日にしなさいとなっていたのか、そこがわかれば。","respondent":"山崎商業・ものづくり課長","answer":"この条例に今日お示しの６項目を追加するために、品川区はそういった要望はありませんでしたけれども、それぞれの自治体が消費者庁のほうに、要は国のほうでモデルの条文をつくるべきだというようなことで政令を出すような形のやり取りがありまして。","voiceIndex":111,"id":"exchange-038"}]},{"id":"topic-04","title":"第２６号議案、品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","agenda":"第２６号議案、品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ＮＰＯ法人が融資の対象になるという点では、前向きに評価したいと思います。そして２つ目に、ＮＰＯ法人というのはもう特定非営利法人ということですから、営利を目的としていないので、利益を民間の事業所みたいになかなか出すような仕組みになっていないと思うのです。ですから、返済能力についてはどのように評価するのか。","respondent":"河内協働・国際担当課長、山崎商業・ものづくり課長","answer":"次に多いのが福祉、保健、医療の分野で１０％です。その次は子どもの健全育成の８.５％でございまして、そのほか人権、国際、科学技術、情報というようなものが１９個並んでいるという状況です。先ほどちょっと説明を申し上げなかったのですが、冒頭の資料のほうでも、改正理由で１０月１日に法改正があって、今回条例が４月１日に改正になります。","voiceIndex":125,"id":"exchange-039"},{"speaker":"南委員","kind":"確認","question":"東京都全体の数字なのかなと誤解してしまいました。そうして実際に融資を申し込まれていくと、信用保証協会の保証制度によって保証されるのかということを確認したいのですけれども、その点と、同時に、全額保証を受けられるのか、部分保証になるのか、そのあたりも教えてください。","respondent":"山崎商業・ものづくり課長","answer":"全額信用保証付きというものにつきましては、国のほうで今、３カ月に１回不況業種認定をやっていまして、そちらの認定がとれた融資については１００％、それ以外のものが先ほどの８対２というような責任割合のものを利用できるということが基本になっております。","voiceIndex":130,"id":"exchange-040"},{"speaker":"南委員","kind":"質問","question":"したがって、１００％保証ではない銀行の責任共有制度の中で２割を銀行が持つというところになると、なかなか今までのこの間の経験の中で、ちょっと融資を断るみたいな貸し渋りみたいなことが結構あった時期があったと思うので、これからの活動の中でそういうことになっていくと、事業活動が継続していけないのかなと心配をするので、その辺について。","respondent":"山崎商業・ものづくり課長","answer":"これによって、保証料の補助の部分というのはどうしてもそういう国制度の仕組みの中で融資制度というのは適切に運営されていると認識をしておりますので、融資制度の適正な運営に資する部分と、それから区としてＮＰＯ活動を支援していくということで。","voiceIndex":132,"id":"exchange-041"},{"speaker":"南委員","kind":"意見","question":"ちょっとあまりよくわからなかったのですけれども、要するに２４２団体の品川区内で活動している非営利法人のうちの、不況業種にあたる活動をしているところはどのくらいあるのかがまず１つ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":134,"id":"exchange-042"},{"speaker":"南委員","kind":"質問・要望","question":"それが１つ。だからそうなると、品川区の責任共有制度でやっていくのだというところは、ちょっと国とは齟齬が出てくるのかなと思ったので、改めてここを確認したいと思って質問したのですけれども、その国の状況を受けて品川区はどのように考えて、不況業種とそうでないところの仕分けをしたのか、そこを教えていただきたいと思います。","respondent":"河内協働・国際担当課長","answer":"ＮＰＯ団体の登録要件の中には、その資金の状況につきまして調査する項目というのがございませんので、この２４２の内訳の中で、その資金状況がわかるものは今のところないという状況でございまして、今の段階でちょっとお答えすることが難しいということです。","voiceIndex":135,"id":"exchange-043"},{"speaker":"南委員","kind":"意見","question":"今の答弁で私が聞きたかったのは、調べようがないという話もあるということを言われているのですけれども、２４２のこのＮＰＯの団体が、資金がどうこうではなくて、不況業種として認定した、そういう活動をしているのかどうか、そういう団体があるのかということを聞いているのです。資金ではなくて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":137,"id":"exchange-044"},{"speaker":"南委員","kind":"質問・要望","question":"だから、その辺をちょっと教えていただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"対応をしっかりとらなければわかりません。","voiceIndex":138,"id":"exchange-045"},{"speaker":"南委員","kind":"質問","question":"そうしますと、この品川区内で活動しているＮＰＯ法人の２４２というのは、不況業種にはあたらないと見てしまってもいいのですか。（「わからないって言ったでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":140,"id":"exchange-046"},{"speaker":"南委員","kind":"質問","question":"それは、では相談に来たときに、こういう活動をしていてこういう運営状況だという話が当然ありますね。その中で、では、あなたの活動しているのは不況業種として該当できそうなので、可能性があるので、では１００％保証になりますとか、そうではないから責任共有制度での融資なのですよというふうに仕分けをするということなのですか。","respondent":"山崎商業・ものづくり課長","answer":"それから現在も中小企業の経営者が来られて、その企業なりＮＰＯ法人の事業活動について聞き取りをして、最適な融資あるいは希望というのもありますので、その中でやり取りをして、ご要望で幾つか選べるのであれば。","voiceIndex":141,"id":"exchange-047"},{"speaker":"南委員","kind":"質問・要望","question":"だからその点で非常にさっきからしつこく聞いているのですけれども、そういう思いで聞いているので、その辺のフォローはどのように考えているのかを教えていただきたい。","respondent":"山崎商業・ものづくり課長","answer":"銀行のほうで例えば不適切な事例で貸し渋りがないことも含めて、区としては銀行のほうに協力あるいは指導をさせていただいているようなことを通じて、先ほどのご意見などについて対応してまいりたいです。","voiceIndex":143,"id":"exchange-048"},{"speaker":"南委員","kind":"確認","question":"今の答弁の確認ですけれども、銀行のほうに区が肩がわりしてやる気持ちはないけれども、しかし一定の銀行に対しての指導、指導という表現だったかちょっと忘れてしまったけれども、そういうことをしていくとおっしゃいましたけれども、そこは具体的にはもっと厳しく見るのではなくて、そこのところをちょっと確認したいのですけれども。","respondent":"山崎商業・ものづくり課長","answer":"ですから、そうした協定遵守をお願いすることによって適正な関係を保ちつつ、いろいろな経営の支援の一助ということでやってまいりたいと思っているところです。","voiceIndex":145,"id":"exchange-049"},{"speaker":"南委員","kind":"確認","question":"最後に１点、国会での経済産業大臣とのやり取りのところで、やはりそれはもう上位のところですから、一番最高機関のところで、ＮＰＯ法人のそういう責任共有制度というのは将来的に考えてはいるけれども、今この時期にはそれはやらないという趣旨のご答弁なのです。そういうところで、そこから発した今の答弁と読んで評価をして受けとめていいのかということを最後に確認して、終わりたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"国の法律に基づいて信用保証制度というのはありますので、法の規定を遵守する形で、区としては取組んでまいるです。","voiceIndex":147,"id":"exchange-050"},{"speaker":"たけうち委員","kind":"意見","question":"この２４２のＮＰＯ法人は、それぞれこういうのに関心を持っているからもう十分知っていらっしゃるとは思うのですけれども、一応こういう形で融資あっ旋できるようになりましたよというものの周知、ご案内などはどうされるのかということと、あとこれはわかればで結構なのですけれども、たしか寄附金の税控除が受けられるＮＰＯ法人というのは、比較的大きいＮＰＯ法人だったかと思うのですけれども。","respondent":"河内協働・国際担当課長、堀越地域振興部長","answer":"区の段階につきましては、ＮＰＯ団体を含みます例えば社会貢献活動展、それから八潮にありますこみゅにてぃぷらざ八潮の推進室など、定例のＮＰＯ団体が集まる場におきましては、こういった融資の制度をしっかりと周知するとともに。区としても、こみゅにてぃぷらざ八潮ですとかいろいろなことをやっていますし、また来年度の予定ですけれども、区民活動助成制度という形で、立ち上げ期の団体へのいろいろな資金的な助成ですとかいうのも考えておりますので。","voiceIndex":149,"id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、業種によっては責任共有制度の融資になるという話なのですけれども、しかし最終的な答弁の中で国の法律を守っていくという立場でやるのだということなので、そこをもって、反対をしないで賛成したいと思っているのですけれども、やはり小さなところの支援という点では区がある程度肩がわりということも含めて、責任共有制度になった場合はそういうことも含めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-052"}]},{"id":"topic-05","title":"────────────────────────────── (6) 第２７号議案 品川区立総合区民会館条例の一部を改正する条例 次に、(6)第２７号議案","agenda":"────────────────────────────── (6) 第２７号議案 品川区立総合区民会館条例の一部を改正する条例 次に、(6)第２７号議案","exchanges":[{"speaker":"田中委員","kind":"意見","question":"細かなことなのですけれども、改正内容の（１）「母子」を「母子等」に改めると書いてあるのですが、なぜ「母子・父子」ではなかったのかということ。","respondent":"間部文化観光課長","answer":"その第１条第１項の部分「母子」を「母子等」にというのは、まさに今委員がご指摘のように、父子を含むということで「等」とさせていただいたものです。","voiceIndex":162,"id":"exchange-053"}]},{"id":"topic-06","title":"報告第１号、専決処分の報告","agenda":"報告第１号、専決処分の報告","exchanges":[{"speaker":"たけうち委員","kind":"意見","question":"１点だけ。通常、任意保険の場合も車両保険をつけるか、つけないかという契約の仕方とかがありますけれども、区の場合はかなりの台数を抱えているので、よくタクシーなどもそうですけれども、あまり車両保険をつけていないケースが多いのですが、区の場合はどうなっているのか、もしわかれば、担当が違ってわからなければ、今日でなくて結構です。","respondent":"間部文化観光課長","answer":"保険につきましては経理課庁舎管理係のほうで一括してなのですが、本件については多分任意保険に入っておりまして、そちらからの補償ということになっていると思います。","voiceIndex":176,"id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2744#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":56612,"voices":182}}]);
